function resolveEpisodeBatchVideoModelDurationOptions(model) {
  const schema = model?.parameterSchema && typeof model.parameterSchema === "object" && !Array.isArray(model.parameterSchema)
    ? model.parameterSchema
    : {};
  const field = resolveEpisodeBatchVideoDurationField(model);
  const schemaOptions = field ? generationParameterOptionValues(schema[field]) : [];
  return schemaOptions.length ? schemaOptions : [...normalizeGenerationOptionValues(model?.supportedDurations), "5", "10"];
}

function resolveEpisodeBatchVideoResolutionField(model) {
  const schema = model?.parameterSchema && typeof model.parameterSchema === "object" && !Array.isArray(model.parameterSchema)
    ? model.parameterSchema
    : {};
  return ["resolution", "quality", "videoResolution"].find((key) => {
    const parameter = schema[key];
    return Boolean(parameter && typeof parameter === "object" && !Array.isArray(parameter));
  }) ?? "";
}

function resolveEpisodeBatchVideoDurationField(model) {
  const schema = model?.parameterSchema && typeof model.parameterSchema === "object" && !Array.isArray(model.parameterSchema)
    ? model.parameterSchema
    : {};
  return ["durationSec", "videoDurationSec", "duration"].find((key) => {
    const parameter = schema[key];
    return Boolean(parameter && typeof parameter === "object" && !Array.isArray(parameter));
  }) ?? "";
}

function resolveEpisodeBatchRatioField(model) {
  const schema = model?.parameterSchema && typeof model.parameterSchema === "object" && !Array.isArray(model.parameterSchema)
    ? model.parameterSchema
    : {};
  return ["aspectRatio", "ratio", "imageAspectRatio", "size"].find((key) => {
    const parameter = schema[key];
    if (!parameter || typeof parameter !== "object" || Array.isArray(parameter)) {
      return false;
    }
    if (key !== "size") {
      return true;
    }
    const label = String(parameter.label ?? "").trim().toLowerCase();
    const options = generationParameterOptionValues(parameter);
    return /比例|宽高比|ratio|aspect/.test(label) || (options.length > 0 && options.every((value) => /^(?:auto|adaptive|\d+\s*:\s*\d+)$/i.test(value)));
  }) ?? "";
}

function resolveEpisodeBatchClarityField(model) {
  const schema = model?.parameterSchema && typeof model.parameterSchema === "object" && !Array.isArray(model.parameterSchema)
    ? model.parameterSchema
    : {};
  return ["quality", "resolution", "imageResolution", "size"].find((key) => {
    const parameter = schema[key];
    if (!parameter || typeof parameter !== "object" || Array.isArray(parameter)) {
      return false;
    }
    if (key !== "size") {
      return true;
    }
    const label = String(parameter.label ?? "").trim().toLowerCase();
    const options = generationParameterOptionValues(parameter);
    return !(/比例|宽高比|ratio|aspect/.test(label) || (options.length > 0 && options.every((value) => /^(?:auto|adaptive|\d+\s*:\s*\d+)$/i.test(value))));
  }) ?? "";
}

function resolveEpisodeBatchConfiguredModelCredit(model) {
  const pricing = model?.pricing && typeof model.pricing === "object" && !Array.isArray(model.pricing)
    ? model.pricing
    : {};
  const pricingJson = model?.pricingJson && typeof model.pricingJson === "object" && !Array.isArray(model.pricingJson)
    ? model.pricingJson
    : {};
  const pricingSnakeJson = model?.pricing_json && typeof model.pricing_json === "object" && !Array.isArray(model.pricing_json)
    ? model.pricing_json
    : {};
  const candidates = [
    pricing.baseCredits,
    pricing.credits,
    pricing.cost,
    pricing.price,
    pricingJson.baseCredits,
    pricingJson.credits,
    pricingJson.cost,
    pricingJson.price,
    pricingSnakeJson.baseCredits,
    pricingSnakeJson.credits,
    pricingSnakeJson.cost,
    pricingSnakeJson.price,
    model?.displayBaseCost,
    model?.baseCredits,
    model?.credits,
    model?.creditCost,
    model?.cost,
    model?.price,
    model?.priceCredits,
  ];
  for (const candidate of candidates) {
    const value = Number(candidate);
    if (Number.isFinite(value) && value > 0) {
      return Math.round(value);
    }
  }
  return null;
}

function resolveEpisodeBatchFallbackUnitCredit(modal) {
  const modelId = modal?.imageModelId ?? "tnb-pro";
  const size = String(modal?.imageClarity ?? "2K").toUpperCase();
  if (modelId === "jimeng-4-5" || modelId === "jimeng-4-5-vip") {
    return size === "1K" ? 40 : 50;
  }
  if (modelId === "tnb-fast") {
    return size === "1K" ? 60 : 70;
  }
  if (modelId === "tnb-ultra") {
    return size === "1K" ? 110 : 120;
  }
  return size === "1K" ? 80 : 90;
}

function resolveEpisodeBatchImageModelOptions(workbench) {
  const generationModels = Array.isArray(workbench.ui?.episodeGenerationConfig?.models)
    ? workbench.ui.episodeGenerationConfig.models
    : [];
  const batchModels = Array.isArray(workbench.ui?.episodeBatchImageModelConfig?.models)
    ? workbench.ui.episodeBatchImageModelConfig.models
    : [];
  const configuredModels = generationModels.length ? generationModels : batchModels;
  const options = configuredModels
    .filter((model) => normalizeGenerationModelMediaKind(model) === "image")
    .filter((model) => modelSupportsGenerationMode(model, "multi-image"))
    .map((model) => {
      const modelCode = String(model?.modelCode ?? model?.id ?? "").trim();
      if (!modelCode) {
        return null;
      }
      const providerGroup = String(model?.providerGroup ?? model?.group ?? model?.providerName ?? "").trim();
      return {
        value: modelCode,
        label: String(model?.modelLabel ?? model?.label ?? modelCode).trim() || modelCode,
        group: providerGroup || "后台配置",
        supportedRatios: normalizeGenerationOptionValues(model?.supportedRatios),
        supportedQuality: normalizeGenerationOptionValues(model?.supportedQuality),
        supportedResolutions: normalizeGenerationOptionValues(model?.supportedResolutions),
        parameterSchema: model?.parameterSchema && typeof model.parameterSchema === "object" && !Array.isArray(model.parameterSchema)
          ? model.parameterSchema
          : {},
        defaultParams: model?.defaultParams && typeof model.defaultParams === "object" ? model.defaultParams : {},
        pricing: model?.pricing,
        pricingJson: model?.pricingJson,
        pricing_json: model?.pricing_json,
        displayBaseCost: model?.displayBaseCost,
        baseCredits: model?.baseCredits,
        credits: model?.credits,
        creditCost: model?.creditCost,
        cost: model?.cost,
        price: model?.price,
        priceCredits: model?.priceCredits,
      };
    })
    .filter(Boolean);
  if (options.length) {
    return options;
  }
  return [
    { value: "tnb-pro", label: "nano banana 2（链路G）", group: "Nano banana" },
    { value: "tnb-fast", label: "nano banana fast（链路G）", group: "Nano banana" },
    { value: "tnb-ultra", label: "nano banana pro（链路G）", group: "Nano banana" },
    { value: "jimeng-4-5", label: "gpt image 2（链路G）", group: "Gpt image" },
    { value: "jimeng-4-5-vip", label: "gpt image 2 VIP（链路G）", group: "Gpt image" },
  ];
}

function resolveEpisodeBatchVideoModelOptions(workbench) {
  const videoMode = workbench.ui?.videoGenerationMode ?? "reference-video";
  const configuredModels = Array.isArray(workbench.ui?.episodeGenerationConfig?.models)
    ? workbench.ui.episodeGenerationConfig.models
    : [];
  const options = configuredModels
    .filter((model) => normalizeGenerationModelMediaKind(model) === "video")
    .filter((model) => modelSupportsGenerationMode(model, videoMode))
    .map((model) => {
      const modelCode = String(model?.modelCode ?? model?.id ?? "").trim();
      if (!modelCode) {
        return null;
      }
      const providerGroup = String(model?.providerGroup ?? model?.group ?? model?.providerName ?? "").trim();
      return {
        value: modelCode,
        label: String(model?.modelLabel ?? model?.label ?? modelCode).trim() || modelCode,
        group: providerGroup || "后台配置",
        supportedRatios: normalizeGenerationOptionValues(model?.supportedRatios),
        supportedQuality: normalizeGenerationOptionValues(model?.supportedQuality),
        supportedResolutions: normalizeGenerationOptionValues(model?.supportedResolutions),
        supportedDurations: normalizeGenerationOptionValues(model?.supportedDurations),
        parameterSchema: model?.parameterSchema && typeof model.parameterSchema === "object" && !Array.isArray(model.parameterSchema)
          ? model.parameterSchema
          : {},
        defaultParams: model?.defaultParams && typeof model.defaultParams === "object" ? model.defaultParams : {},
        pricing: model?.pricing,
        pricingJson: model?.pricingJson,
        pricing_json: model?.pricing_json,
        displayBaseCost: model?.displayBaseCost,
        baseCredits: model?.baseCredits,
        credits: model?.credits,
        creditCost: model?.creditCost,
        cost: model?.cost,
        price: model?.price,
        priceCredits: model?.priceCredits,
      };
    })
    .filter(Boolean);
  if (options.length) {
    return options;
  }
  return [
    { value: "vidu-q3-pro", label: "Vidu Q3 Pro", group: "默认", supportedRatios: ["16:9", "9:16"], supportedQuality: ["1080p"], supportedDurations: ["5", "10"] },
  ];
}

function resolveBatchPromptPresetCategories(workbench) {
  const configured = workbench.ui?.episodeGenerationConfig?.batchPromptPresetCategories;
  return {
    scene: normalizeBatchPromptPresetCategoryList(configured?.scene),
    character: normalizeBatchPromptPresetCategoryList(configured?.character),
    prop: normalizeBatchPromptPresetCategoryList(configured?.prop),
  };
}

function normalizeBatchPromptPresetCategoryList(value) {
  if (!Array.isArray(value)) {
    return [];
  }
  const seen = new Set();
  const options = value
    .map((item) => {
      const id = String(item?.id ?? "").trim();
      const label = String(item?.label ?? "").trim();
      const promptContent = String(item?.prompt_content ?? item?.promptContent ?? "").trim();
      if (!id || !label || id === "none") {
        return null;
      }
      return promptContent ? { id, label, prompt_content: promptContent, promptContent } : { id, label };
    })
    .filter(Boolean)
    .filter((item) => {
      if (seen.has(item.id)) {
        return false;
      }
      seen.add(item.id);
      return true;
    });
  return options;
}

function resolveDefaultBatchPromptPresetId(options, fallbackId) {
  if (Array.isArray(options) && options.some((option) => option.id === fallbackId)) {
    return fallbackId;
  }
  return options?.[0]?.id ?? "none";
}

function buildEpisodeBatchAssetImageSubmission(workbench, modal, item, assetKind, promptPreview, selectionContext, createdAt) {
  const selectedModel = (modal?.imageModelOptions ?? []).find((option) => {
    return String(option?.value ?? option?.id ?? "").trim() === String(modal?.imageModelId ?? "gpt-image-2-cn").trim();
  }) ?? null;
  const configuredParameters =
    selectedModel ? filterExplicitImageSizeParameters(configuredGenerationParametersForModel(workbench, String(selectedModel.value ?? selectedModel.id ?? ""))) : {};
  const selectedModelCode = String(selectedModel?.value ?? selectedModel?.id ?? modal?.imageModelId ?? "gpt-image-2-cn").trim();
  const selectedModelConfig = findConfiguredGenerationModel(workbench, selectedModelCode);
  const imageResolutionFallback = modal?.imageClarity ?? selectedModelConfig?.defaultParams?.quality ?? selectedModelConfig?.defaultParams?.resolution;
  const imageAspectRatioFallback = selectedModelConfig?.defaultParams?.aspectRatio;
  return {
    turnId: createAssetConversationTurnId(),
    mediaKind: "image",
    assetId: item?.id ?? null,
    promptPreview,
    quickReferenceItems: [],
    attachmentItems: [],
    selectionContext,
    selectedModelId: modal?.imageModelId ?? "gpt-image-2-cn",
    resolution: resolveGenerationDisplayResolution(configuredParameters, imageResolutionFallback) || null,
    aspectRatio: resolveGenerationDisplayAspectRatio(
      configuredParameters,
      imageAspectRatioFallback,
    ) || null,
    creditCost: resolveEpisodeBatchUnitCredit(modal),
    createdAt,
    status: "running",
  };
}

function buildEpisodeBatchImageTaskPayload(workbench, modal, item, assetKind, submission) {
  const model = String(modal?.imageModelId ?? "gpt-image-2-cn").trim() || "gpt-image-2-cn";
  const configuredParameters = filterExplicitImageSizeParameters(configuredGenerationParametersForModel(workbench, model));
  const qualityVisible = isConfiguredGenerationParameterVisible(workbench, model, "quality");
  const resolutionVisible = isConfiguredGenerationParameterVisible(workbench, model, "resolution");
  const aspectRatioVisible = isConfiguredGenerationParameterVisible(workbench, model, "aspectRatio");
  const explicitImageSize = hasExplicitImageSizeParameter(configuredParameters);
  return {
    shotId: null,
    promptOverride: submission?.promptPreview ?? "",
    model,
    parameters: {
      ...configuredParameters,
      mode: "multi-image",
      count: 1,
      ...(qualityVisible && (configuredParameters.quality !== undefined || !explicitImageSize)
        ? { quality: configuredParameters.quality ?? modal?.imageClarity ?? "2K" }
        : {}),
      ...(resolutionVisible && (configuredParameters.resolution !== undefined || !explicitImageSize)
        ? { resolution: configuredParameters.resolution ?? modal?.imageClarity ?? "2K" }
        : {}),
      ...(aspectRatioVisible && (configuredParameters.aspectRatio !== undefined || !explicitImageSize)
        ? { aspectRatio: configuredParameters.aspectRatio ?? modal?.imageAspectRatio ?? workbench.state?.project?.aspectRatio ?? "16:9" }
        : {}),
      strategy: workbench.ui.multiImageStrategy ?? "spatial-multi-view",
      references: [],
      quickReferences: [],
      firstFrame: null,
      imageReference: null,
      localReferenceRoles: [],
      selectionContext: submission?.selectionContext ?? {},
    },
    targetType: "asset",
    targetId: item?.id ?? null,
    assetId: item?.id ?? null,
    assetType: assetKind,
    prompt: submission?.promptPreview ?? "",
  };
}

async function submitEpisodeBatchStoryboardVideoTasks(workbench, modal, items, now) {
  const activeStoryboards = getActiveStoryboards(workbench);
  stopGenerationPolling(workbench);
  workbench.ui.generationPollingActive = true;
  let firstResult = null;
  let selectedStoryboardResult = null;

  for (const item of items) {
    const storyboard = activeStoryboards.find((candidate) => candidate.id === item.id) ?? null;
    if (!storyboard) {
      continue;
    }
    const payload = buildEpisodeBatchStoryboardVideoTaskPayload(workbench, modal, storyboard);
    const submission = {
      id: `batch-video-${storyboard.id}-${Date.now()}`,
      mediaKind: "video",
      promptPreview: payload.motionPrompt,
      selectedModelId: payload.model,
      resolution: payload.parameters.resolution ?? null,
      aspectRatio: payload.parameters.aspectRatio ?? null,
      creditCost: resolveEpisodeBatchUnitCredit(modal),
      createdAt: now,
      status: "running",
      targetType: "storyboard",
      targetId: storyboard.linkedShotId ?? storyboard.id,
      selectionContext: {
        episodeId: workbench.ui.selectedEpisodeId ?? "episode-primary",
        storyboardId: storyboard.id,
        storyboardTitle: storyboard.displayTitle ?? storyboard.title ?? item.name ?? "分镜",
      },
      quickReferenceItems: payload.parameters.quickReferences ?? [],
      attachmentItems: payload.parameters.referenceUploads ?? [],
      generatedAudioItems: [],
    };
    updateStoryboardGenerationState(workbench, storyboard.id, (generationState) => ({
      ...generationState,
      lastSubmission: submission,
    }));
    workbench.ui.videoGenerationResult = submission;
    const task = await workbench.api.createVideoTask(workbench.ui.selectedEpisodeId, {
      ...payload,
      targetType: "storyboard",
      targetId: storyboard.linkedShotId ?? storyboard.id,
      prompt: payload.motionPrompt,
    });
    const result = normalizeEpisodeTaskForLegacyResult(task, submission, "video");
    applyEpisodeGenerationTaskResult(workbench, result, storyboard.id, "video");
    firstResult = firstResult ?? result;
    if (storyboard.id === workbench.ui.selectedStoryboardId) {
      selectedStoryboardResult = result;
    }
  }

  workbench.ui.selectedStoryboardIds = [];
  workbench.ui.episodeBatchModal = null;
  workbench.ui.toast = `已为 ${items.length} 条分镜创建视频任务。`;
  const activeResult = selectedStoryboardResult ?? firstResult;
  const activeStoryboardId = selectedStoryboardResult
    ? workbench.ui.selectedStoryboardId
    : items[0]?.id ?? workbench.ui.selectedStoryboardId;
  if (activeResult) {
    workbench.ui.videoGenerationResult = activeResult;
  }
  if (activeResult?.taskId) {
    if (activeStoryboardId && shouldContinueGenerationPolling(workbench, activeStoryboardId, "video")) {
      scheduleGenerationPolling(workbench, activeStoryboardId, "video", { immediate: true });
    }
  }
  render(workbench);
}

function buildEpisodeBatchStoryboardVideoTaskPayload(workbench, modal, storyboard) {
  const videoMode = workbench.ui.videoGenerationMode ?? "reference-video";
  const model = String(modal?.videoModelId ?? workbench.ui.selectedModelId ?? fallbackVideoModelCodeForMode(videoMode)).trim();
  const selectedModel = findConfiguredGenerationModel(workbench, model);
  const configuredParameters = filterParametersForConfiguredModel(
    configuredGenerationParametersForModel(workbench, model),
    selectedModel,
  );
  const generationState = storyboard?.generationState ?? createEmptyGenerationState();
  const prompt = String(storyboard?.description ?? storyboard?.prompt ?? "").trim();
  const quickReferences = generationState.quickReferenceItems ?? [];
  const referenceUploads = generationState.referenceUploads ?? [];
  return {
    shotId: storyboard?.linkedShotId ?? null,
    motionPrompt: prompt,
    model,
    parameters: {
      ...configuredParameters,
      mode: videoMode,
      count: 1,
      resolution: modal?.videoResolution ?? configuredParameters.resolution ?? workbench.ui.videoResolution ?? "1080p",
      durationSec: Number(modal?.videoDurationSec ?? configuredParameters.durationSec ?? workbench.ui.videoDurationSec ?? 5),
      aspectRatio: modal?.imageAspectRatio ?? configuredParameters.aspectRatio ?? workbench.ui.imageAspectRatio ?? workbench.state?.project?.aspectRatio ?? "16:9",
      references: storyboard?.references ?? [],
      quickReferences,
      firstFrame: generationState.firstFrame ?? null,
      lastFrame: generationState.lastFrame ?? null,
      editSourceVideo: generationState.editSourceVideo ?? null,
      referenceUploads,
      selectionContext: {
        episodeId: workbench.ui.selectedEpisodeId ?? "episode-primary",
        storyboardId: storyboard?.id ?? null,
      },
    },
  };
}

export async function generateAssetImages(workbench) {
  const selectionContext = resolveEpisodeAssetSelectionContext(workbench);
  const asset = selectionContext.selectedAsset;
  const assetKind = selectionContext.assetTab ?? workbench.ui.projectAssetTab ?? "character";
  if (!asset?.id) {
    workbench.ui.validationMessage = "请先创建或选中资产后再生成。";
    workbench.ui.toast = "请先创建或选中资产后再生成。";
    render(workbench);
    return;
  }
  if (!String(getCurrentScopePrompt(workbench) ?? "").trim()) {
    workbench.ui.validationMessage = "请输入内容";
    workbench.ui.toast = "请输入内容";
    render(workbench);
    return;
  }

  const submission = createAssetGenerationSubmissionSnapshot(workbench, asset, assetKind, "image");
  if (typeof workbench.api?.createImageTask === "function") {
    stopGenerationPolling(workbench);
    workbench.ui.generationPollingActive = true;
    const runningResult = {
      ...(workbench.ui.imageGenerationResult ?? {}),
      ...submission,
      taskId: null,
      platform: null,
      status: "running",
      progressPercent: 10,
      progressStage: "task_created",
      failure: null,
      failureCode: null,
      fixedImages: [],
      quickReferenceItems: submission.quickReferenceItems,
      attachmentItems: submission.attachmentItems,
      selectionContext: submission.selectionContext,
    };
    workbench.ui.imageGenerationResult = runningResult;
    appendAssetConversationHistoryEntry(workbench, runningResult);
    workbench.ui.episodeBatchResults = {
      ...(workbench.ui.episodeBatchResults ?? {}),
      [asset.id]: runningResult,
    };
    workbench.ui.episodeWorkbenchConversationScrollMode = "latest";
    render(workbench);
    try {
      await persistAssetConversationEntry(workbench, runningResult, { includeUserRequest: true });
      render(workbench);
    } catch (error) {
      const failedResult = {
        ...runningResult,
        ...submission,
        status: "failed",
        failureCode: "asset_conversation_persist_failed",
        failure: {
          displayMessage: friendlyError(error),
        },
        quickReferenceItems: submission.quickReferenceItems,
        attachmentItems: submission.attachmentItems,
        fixedImages: [],
        selectionContext: submission.selectionContext,
      };
      workbench.ui.imageGenerationResult = failedResult;
      workbench.ui.episodeBatchResults = {
        ...(workbench.ui.episodeBatchResults ?? {}),
        [asset.id]: failedResult,
      };
      workbench.ui.generationPollingActive = false;
      appendAssetConversationHistoryEntry(workbench, failedResult);
      render(workbench);
      throw error;
    }

    const payload = buildImageGenerationPayload(workbench);
    collectEpisodeWorkbenchEvent(workbench, "generation.submit", {
      mediaKind: "image",
      payload: {
        ...payload,
        targetType: "asset",
        targetId: asset.id,
        assetId: asset.id,
        assetType: assetKind,
        prompt: submission.promptPreview,
      },
      submission,
    });
    let createdTask;
    try {
      createdTask = await workbench.api.createImageTask(workbench.ui.selectedEpisodeId, {
        ...payload,
        targetType: "asset",
        targetId: asset.id,
        assetId: asset.id,
        assetType: assetKind,
        prompt: submission.promptPreview,
      });
    } catch (error) {
      const failedResult = {
        ...runningResult,
        ...submission,
        status: "failed",
        failureCode: "asset_image_task_failed",
        failure: {
          displayMessage: friendlyError(error),
        },
        quickReferenceItems: submission.quickReferenceItems,
        attachmentItems: submission.attachmentItems,
        fixedImages: [],
        selectionContext: submission.selectionContext,
      };
      workbench.ui.imageGenerationResult = failedResult;
      workbench.ui.episodeBatchResults = {
        ...(workbench.ui.episodeBatchResults ?? {}),
        [asset.id]: failedResult,
      };
      workbench.ui.generationPollingActive = false;
      appendAssetConversationHistoryEntry(workbench, failedResult);
      render(workbench);
      try {
        await persistAssetConversationEntry(workbench, failedResult, { includeUserRequest: true });
        render(workbench);
      } catch {
        // The local failure state remains visible even if persistence is temporarily unavailable.
      }
      throw error;
    }
    const result = normalizeEpisodeTaskForLegacyResult(
      createdTask,
      submission,
      "image",
    );
    const submittedResult = {
      ...result,
      ...submission,
      status: resolveGenerationTaskDisplayStatus(result),
      taskId: result?.platform?.tasks?.[0]?.taskId ?? result?.taskId ?? null,
      quickReferenceItems: submission.quickReferenceItems,
      attachmentItems: submission.attachmentItems,
      fixedImages: result?.fixedImages ?? [],
      selectionContext: result?.selectionContext ?? submission.selectionContext,
    };
    workbench.ui.imageGenerationResult = submittedResult;
    appendAssetConversationHistoryEntry(workbench, submittedResult);
    workbench.ui.episodeBatchResults = {
      ...(workbench.ui.episodeBatchResults ?? {}),
      [asset.id]: submittedResult,
    };
    setCurrentScopePrompt(workbench, "");
    workbench.ui.assetPromptDraft = {
      ...(workbench.ui.assetPromptDraft ?? {}),
      scopeMode: "assets",
      prompt: "",
      quickReferenceItems: [],
      mentionReferences: [],
    };
    workbench.ui.episodeWorkbenchConversationScrollMode = "latest";
    if (Number.isFinite(Number(result?.creditBalance))) {
      workbench.ui.creditBalance = Number(result.creditBalance);
    }
    if (isGenerationTaskTerminalStatus(resolveWorkflowStatus(submittedResult.status))) {
      workbench.ui.generationPollingActive = false;
    } else {
      scheduleSelectedAssetGenerationPolling(workbench, "image", { immediate: true });
    }
    render(workbench);
    try {
      await persistAssetConversationEntry(workbench, submittedResult, { includeUserRequest: true });
      render(workbench);
    } catch {
      // Keep the generated result visible if conversation persistence is temporarily unavailable.
    }
    return;
  }

  workbench.ui.validationMessage = "真实图片生成接口不可用，请刷新后重试。";
  workbench.ui.toast = "真实图片生成接口不可用，请刷新后重试。";
  render(workbench);
  throw new Error("episode_image_generation_api_missing");
}

function validateLipSyncGeneration(workbench) {
  const text = String(getCurrentScopePrompt(workbench) ?? "").trim();
  if (!text) {
    return { ok: false, message: "请输入配音内容后再生成。" };
  }
  if (!String(workbench.ui.lipSyncVoiceName ?? "").trim()) {
    return { ok: false, message: "请先选择配音员后再生成。" };
  }
  return { ok: true };
}

function calculateLipSyncCreditCost(value) {
  const length = [...String(value ?? "").trim()].length;
  if (!length) {
    return 0;
  }
  return Math.ceil(length / 10) * 2;
}

function playEpisodeVoicePreview(workbench, voiceInput) {
  stopEpisodeVoicePreview(workbench);
  if (typeof Audio === "undefined") {
    return;
  }
  const voiceName = typeof voiceInput === "object" ? String(voiceInput?.voiceName ?? "") : String(voiceInput ?? "");
  const audioUrl = typeof voiceInput === "object" ? String(voiceInput?.audioUrl ?? "") : "";
  const playbackUrl =
    audioUrl && /^(?:https?:|data:)/i.test(audioUrl)
      ? audioUrl
      : audioUrl
        ? resolveApiUrl(audioUrl)
        : buildEpisodeVoicePreviewDataUrl(voiceName);
  const audio = new Audio(playbackUrl);
  audio.volume = 0.45;
  audio.onended = () => {
    if (workbench.ui.episodeVoiceModal) {
      workbench.ui.episodeVoiceModal = {
        ...workbench.ui.episodeVoiceModal,
        previewVoiceId: "",
        previewVoiceName: "",
      };
      render(workbench);
    }
  };
  workbench.voicePreviewAudio = audio;
  void audio.play().catch(() => {});
}

function stopEpisodeVoicePreview(workbench) {
  if (workbench.voicePreviewAudio) {
    try {
      workbench.voicePreviewAudio.pause();
      workbench.voicePreviewAudio.currentTime = 0;
    } catch {}
    workbench.voicePreviewAudio = null;
  }
}

function playLipSyncAudioPreview(workbench, item) {
  stopLipSyncAudioPreview(workbench);
  if (typeof Audio === "undefined") {
    return;
  }
  const seed = `${item?.voiceName ?? ""}:${item?.summary ?? item?.name ?? ""}`;
  const audio = new Audio(item?.audioUrl ?? buildEpisodeVoicePreviewDataUrl(seed));
  audio.volume = 0.5;
  audio.onended = () => {
    workbench.ui.lipSyncPreviewAudioId = null;
    workbench.lipSyncPreviewAudio = null;
    render(workbench);
  };
  workbench.ui.lipSyncPreviewAudioId = item?.id ?? null;
  workbench.lipSyncPreviewAudio = audio;
  void audio.play().catch(() => {
    workbench.ui.lipSyncPreviewAudioId = null;
    workbench.lipSyncPreviewAudio = null;
    render(workbench);
  });
}

function stopLipSyncAudioPreview(workbench) {
  if (workbench.lipSyncPreviewAudio) {
    try {
      workbench.lipSyncPreviewAudio.pause();
      workbench.lipSyncPreviewAudio.currentTime = 0;
    } catch {}
    workbench.lipSyncPreviewAudio = null;
  }
  workbench.ui.lipSyncPreviewAudioId = null;
}

function buildEpisodeVoicePreviewDataUrl(voiceName) {
  const seed = [...String(voiceName ?? "")].reduce((sum, char) => sum + char.charCodeAt(0), 0);
  const sampleRate = 8000;
  const durationSec = 0.45;
  const samples = Math.floor(sampleRate * durationSec);
  const frequency = 300 + (seed % 220);
  const pcmBytes = new Uint8Array(samples);
  for (let index = 0; index < samples; index += 1) {
    const envelope = Math.min(1, index / 600) * Math.min(1, (samples - index) / 600);
    const sample = Math.sin((2 * Math.PI * frequency * index) / sampleRate) * 0.5 * envelope;
    pcmBytes[index] = Math.max(0, Math.min(255, Math.round(128 + sample * 127)));
  }
  const header = new ArrayBuffer(44);
  const view = new DataView(header);
  const writeString = (offset, value) => {
    for (let index = 0; index < value.length; index += 1) {
      view.setUint8(offset + index, value.charCodeAt(index));
    }
  };
  writeString(0, "RIFF");
  view.setUint32(4, 36 + pcmBytes.length, true);
  writeString(8, "WAVE");
  writeString(12, "fmt ");
  view.setUint32(16, 16, true);
  view.setUint16(20, 1, true);
  view.setUint16(22, 1, true);
  view.setUint32(24, sampleRate, true);
  view.setUint32(28, sampleRate, true);
  view.setUint16(32, 1, true);
  view.setUint16(34, 8, true);
  writeString(36, "data");
  view.setUint32(40, pcmBytes.length, true);
  const wavBytes = new Uint8Array(header.byteLength + pcmBytes.length);
  wavBytes.set(new Uint8Array(header), 0);
  wavBytes.set(pcmBytes, header.byteLength);
  let binary = "";
  for (const byte of wavBytes) {
    binary += String.fromCharCode(byte);
  }
  return `data:audio/wav;base64,${btoa(binary)}`;
}

async function persistLipSyncStoryboardDraft(workbench, options = {}) {
  if (!isRealEpisodeWorkbench(workbench) || typeof workbench.api.saveDraft !== "function") {
    return null;
  }
  const selectedStoryboard = getSelectedStoryboard(
    getActiveStoryboards(workbench),
    workbench.ui.selectedStoryboardId,
  );
  const targetId = selectedStoryboard?.linkedShotId ?? selectedStoryboard?.id ?? null;
  if (!targetId) {
    return null;
  }
  const text = String(workbench.ui.prompt ?? "");
  const payload = {
    prompt: text,
    mode: "lip_sync",
    payload: {
      text,
      textLength: [...text.trim()].length,
      voiceId: workbench.ui.lipSyncVoiceId ?? null,
      voiceName: workbench.ui.lipSyncVoiceName ?? "",
      voiceSource: workbench.ui.lipSyncVoiceSource ?? null,
      estimatedCreditCost: calculateLipSyncCreditCost(text),
    },
  };
  try {
    return await workbench.api.saveDraft(workbench.ui.selectedEpisodeId, "storyboard", targetId, payload);
  } catch (error) {
    if (!options?.silent) {
      workbench.ui.toast = `保存对口型草稿失败：${friendlyError(error)}`;
      render(workbench);
    }
    return null;
  }
}

async function refreshCanvasGenerationCreditContext(workbench) {
  const episodeId = resolveCanvasGenerationEpisodeId(workbench);
  if (episodeId && typeof workbench.api?.listGenerationConfig === "function") {
    await loadEpisodeGenerationConfig(workbench, episodeId);
    return;
  }
  if (typeof workbench.api?.listGlobalGenerationConfig === "function") {
    await loadGlobalGenerationConfig(workbench);
  }
}

const GENERATION_POLL_INTERVAL_MS = 30_000;
const IMAGE_GENERATION_FAST_POLL_INTERVAL_MS = 15_000;
const IMAGE_GENERATION_FAST_POLL_WINDOW_MS = 60_000;
const IMAGE_GENERATION_CLIENT_POLL_TIMEOUT_MS = 15 * 60 * 1000;
const VIDEO_GENERATION_CLIENT_POLL_TIMEOUT_MS = 3 * 60 * 60 * 1000;
const CANVAS_GENERATION_FAST_POLL_INTERVAL_MS = 15_000;
const CANVAS_GENERATION_FAST_POLL_WINDOW_MS = 60_000;

function resolveGenerationPollDelayMs(mediaKind, startedAt, immediate = false) {
  if (immediate) {
    return 0;
  }
  if (
    mediaKind === "image" &&
    Number.isFinite(Number(startedAt)) &&
    Date.now() - Number(startedAt) <= IMAGE_GENERATION_FAST_POLL_WINDOW_MS
  ) {
    return IMAGE_GENERATION_FAST_POLL_INTERVAL_MS;
  }
  return GENERATION_POLL_INTERVAL_MS;
}

function scheduleCanvasGenerationPolling(workbench, _preview = null, options = {}) {
  if (
    typeof window === "undefined" ||
    typeof window.setTimeout !== "function" ||
    (
      typeof workbench.api?.getGenerationTasks !== "function" &&
      typeof workbench.api?.getGenerationTask !== "function"
    )
  ) {
    return;
  }
  if (!isCanvasGenerationPollingVisible(workbench)) {
    stopCanvasGenerationPolling(workbench);
    return;
  }
  const targets = resolveCanvasGenerationPollTargets(workbench);
  if (!targets.length) {
    stopCanvasGenerationPolling(workbench);
    workbench.canvasGenerationPollStartedAt = null;
    return;
  }
  if (workbench.canvasGenerationPollTimer || workbench.canvasGenerationPollInFlight) {
    return;
  }
  workbench.canvasGenerationPollStartedAt = workbench.canvasGenerationPollStartedAt ?? Date.now();
  const delayMs = resolveCanvasGenerationPollDelayMs(
    workbench.canvasGenerationPollStartedAt,
    options.immediate === true,
  );
  workbench.canvasGenerationPollTimer = window.setTimeout(async () => {
    workbench.canvasGenerationPollTimer = null;
    if (!isCanvasGenerationPollingVisible(workbench)) {
      return;
    }
    const pollGeneration = Number(workbench.canvasGenerationPollGeneration ?? 0);
    workbench.canvasGenerationPollInFlight = true;
    try {
      const tasks = await loadCanvasGenerationTasks(workbench, targets);
      if (
        !isCanvasGenerationPollingVisible(workbench) ||
        Number(workbench.canvasGenerationPollGeneration ?? 0) !== pollGeneration
      ) {
        return;
      }
      let document = workbench.ui.canvasDocument;
      for (const target of targets) {
        const latestTask = tasks.get(target.taskId);
        if (!latestTask) continue;
        document = applyCanvasRunResult(document, target.preview, latestTask);
        if (workbench.ui.canvasRunPreview?.nodeId === target.nodeId) {
          workbench.ui.canvasRunPreview = { ...workbench.ui.canvasRunPreview, task: latestTask, taskId: target.taskId };
        }
      }
      updateActiveCanvasDocument(workbench, document);
      const pendingTargets = resolveCanvasGenerationPollTargets(workbench);
      workbench.ui.canvasGeneratingNodeId = pendingTargets[0]?.nodeId ?? null;
      render(workbench);
      if (!pendingTargets.length) {
        workbench.canvasGenerationPollStartedAt = null;
      }
    } catch (error) {
      workbench.ui.toast = `画布生成状态刷新失败：${friendlyError(error)}`;
      render(workbench);
    } finally {
      workbench.canvasGenerationPollInFlight = false;
      if (isCanvasGenerationPollingVisible(workbench) && resolveCanvasGenerationPollTargets(workbench).length) {
        scheduleCanvasGenerationPolling(workbench);
      }
    }
  }, delayMs);
}

function resolveCanvasGenerationPollDelayMs(startedAt, immediate = false, now = Date.now()) {
  if (immediate) return 0;
  return now - Number(startedAt ?? now) <= CANVAS_GENERATION_FAST_POLL_WINDOW_MS
    ? CANVAS_GENERATION_FAST_POLL_INTERVAL_MS
    : GENERATION_POLL_INTERVAL_MS;
}

function resumeCanvasGenerationPollingIfNeeded(workbench) {
  if (
    workbench.canvasGenerationPollTimer ||
    workbench.canvasGenerationPollInFlight ||
    (
      typeof workbench.api?.getGenerationTasks !== "function" &&
      typeof workbench.api?.getGenerationTask !== "function"
    )
  ) {
    return;
  }
  if (!isCanvasGenerationPollingVisible(workbench)) {
    stopCanvasGenerationPolling(workbench);
    return;
  }
  const targets = resolveCanvasGenerationPollTargets(workbench);
  if (!targets.length) {
    return;
  }
  workbench.ui.canvasGeneratingNodeId = targets[0].nodeId;
  scheduleCanvasGenerationPolling(workbench, null, { immediate: true });
}

function isCanvasGenerationPollingVisible(workbench) {
  return workbench?.ui?.activeNavTab === "tools" && workbench?.ui?.canvasProjectView === "detail";
}

function resolveCanvasGenerationPollTargets(workbench) {
  const canvasDocument = workbench.ui?.canvasDocument;
  return (Array.isArray(canvasDocument?.nodes) ? canvasDocument.nodes : [])
    .filter((node) => ["running", "queued", "processing"].includes(String(node?.data?.status ?? "").trim().toLowerCase()))
    .map((node) => {
      const taskId = resolveCanvasNodeTaskId(canvasDocument, node.id);
      return taskId ? {
        nodeId: node.id,
        taskId,
        preview: {
          ok: true,
          nodeId: node.id,
          mediaKind: node.data?.mediaKind === "video" || node.type === "video" ? "video" : "image",
          modelCode: String(node.data?.modelCode ?? ""),
          prompt: String(node.data?.prompt ?? ""),
          taskId,
          upstreamNodeIds: [],
          upstreamTextFragments: [],
        },
      } : null;
    })
    .filter(Boolean);
}

async function loadCanvasGenerationTasks(workbench, targets) {
  if (typeof workbench.api?.getGenerationTasks === "function") {
    const response = await workbench.api.getGenerationTasks(targets.map((target) => target.taskId));
    return new Map(
      (Array.isArray(response?.items) ? response.items : [])
        .map((task) => [resolveGenerationTaskIdForConversation(task), task])
        .filter(([taskId]) => taskId),
    );
  }
  const tasks = await Promise.all(targets.map((target) => workbench.api.getGenerationTask(target.taskId)));
  return new Map(tasks.map((task, index) => [targets[index].taskId, task]));
}

function resumeEpisodeStoryboardGenerationPollingIfNeeded(workbench) {
  if (
    workbench?.ui?.activeNavTab !== "project" ||
    workbench?.ui?.projectPanelMode !== "episode-workbench" ||
    (workbench.ui.museScopeMode ?? "storyboard") !== "storyboard"
  ) {
    return;
  }
  const mediaKind = resolveStoryboardConversationMediaKind(workbench);
  const storyboardId = workbench.ui.selectedStoryboardId ?? null;
  if (!storyboardId || !resolveSelectedStoryboardGenerationPollTarget(workbench, storyboardId, mediaKind)) {
    return;
  }
  resumeSelectedStoryboardGenerationPolling(workbench, {
    storyboardId,
    mediaKind,
    immediate: true,
  });
}

function resolveCanvasNodeTaskId(canvasDocument, nodeId) {
  const normalizedNodeId = String(nodeId ?? "");
  if (!normalizedNodeId) {
    return null;
  }
  const node = (Array.isArray(canvasDocument?.nodes) ? canvasDocument.nodes : [])
    .find((item) => String(item?.id ?? "") === normalizedNodeId);
  const data = node?.data ?? {};
  const value = data.lastTaskId ?? data.taskId ?? data.generationTaskId ?? data.platform?.tasks?.[0]?.taskId ?? null;
  const normalized = String(value ?? "").trim();
  return normalized || null;
}

function stopCanvasGenerationPolling(workbench) {
  if (workbench.canvasGenerationPollTimer) {
    if (typeof window !== "undefined" && typeof window.clearTimeout === "function") {
      window.clearTimeout(workbench.canvasGenerationPollTimer);
    }
    workbench.canvasGenerationPollTimer = null;
  }
  workbench.canvasGenerationPollGeneration = Number(workbench.canvasGenerationPollGeneration ?? 0) + 1;
}

function scheduleGenerationPolling(workbench, storyboardId, mediaKind, options = {}) {
  const pollTarget = resolveSelectedStoryboardGenerationPollTarget(workbench, storyboardId, mediaKind);
  const scopeKey = pollTarget
    ? `${pollTarget.storyboardId}:${pollTarget.mediaKind}:${pollTarget.taskId}`
    : null;
  if (scopeKey && workbench.generationPollTimer && workbench.generationPollScopeKey === scopeKey) {
    return;
  }
  stopGenerationPolling(workbench);
  workbench.generationPollStartedAt = workbench.generationPollStartedAt ?? Date.now();
  workbench.generationPollScopeKey = scopeKey;
  const delayMs = resolveGenerationPollDelayMs(mediaKind, workbench.generationPollStartedAt, options.immediate === true);
  const maxPollMs =
    mediaKind === "video"
      ? VIDEO_GENERATION_CLIENT_POLL_TIMEOUT_MS
      : IMAGE_GENERATION_CLIENT_POLL_TIMEOUT_MS;
  workbench.generationPollTimer = window.setTimeout(async () => {
    workbench.generationPollTimer = null;
    try {
      if (Date.now() - workbench.generationPollStartedAt > maxPollMs) {
        workbench.ui.generationPollingActive = false;
        const targetKey = mediaKind === "video" ? "videoGenerationResult" : "imageGenerationResult";
        workbench.ui[targetKey] = {
          ...(workbench.ui[targetKey] ?? {}),
          status: "failed",
          failureCode: "client_poll_timeout",
        };
        workbench.ui.toast =
          mediaKind === "video"
            ? "视频生成已等待 3 小时，后台会尝试取消供应商任务并刷新最终状态。"
            : "生成任务超过 15 分钟未完成，已标记为失败。";
        renderEpisodeWorkbenchPollingUpdate(workbench);
        return;
      }
      const taskId =
        mediaKind === "video"
          ? workbench.ui.videoGenerationResult?.taskId
          : workbench.ui.imageGenerationResult?.taskId;
      if (taskId && typeof workbench.api.getGenerationTask === "function") {
        const latestTask = await workbench.api.getGenerationTask(taskId);
        applyEpisodeGenerationTaskResult(workbench, latestTask, storyboardId, mediaKind);
        if (isGenerationTaskEffectivelyTerminal(latestTask, mediaKind)) {
          finishGenerationPolling(workbench, storyboardId, mediaKind);
          return;
        }
      } else {
        await refresh(workbench);
      }
      const shouldContinue = shouldContinueGenerationPolling(workbench, storyboardId, mediaKind);
      if (shouldContinue) {
        renderEpisodeWorkbenchPollingUpdate(workbench);
        scheduleGenerationPolling(workbench, storyboardId, mediaKind);
        return;
      }
      finishGenerationPolling(workbench, storyboardId, mediaKind);
    } catch (error) {
      workbench.ui.generationPollingActive = false;
      workbench.ui.toast = `轮询刷新失败：${friendlyError(error)}`;
      renderEpisodeWorkbenchPollingUpdate(workbench);
    }
  }, delayMs);
}

function scheduleSelectedAssetGenerationPolling(workbench, mediaKind = "image", options = {}) {
  if (typeof window === "undefined" || typeof window.setTimeout !== "function") {
    return;
  }
  const target = resolveSelectedAssetGenerationPollTarget(workbench, mediaKind);
  if (!target) {
    stopAssetGenerationPolling(workbench);
    return;
  }
  if (workbench.assetGenerationPollTimer && workbench.assetGenerationPollScopeKey === target.scopeKey) {
    return;
  }

  stopAssetGenerationPolling(workbench);
  workbench.assetGenerationPollStartedAt = workbench.assetGenerationPollStartedAt ?? Date.now();
  workbench.assetGenerationPollScopeKey = target.scopeKey;
  const delayMs = resolveGenerationPollDelayMs(mediaKind, workbench.assetGenerationPollStartedAt, options.immediate === true);
  workbench.assetGenerationPollTimer = window.setTimeout(async () => {
    workbench.assetGenerationPollTimer = null;
    try {
      const latestTask = await workbench.api.getGenerationTask(target.taskId);
      applyAssetBatchGenerationTaskResult(workbench, latestTask, target.entry, target.mediaKind);
      syncSelectedAssetConversationResult(workbench, target.assetId, target.mediaKind);
      const latestStatus = resolveWorkflowStatus(latestTask?.status);
      if (isGenerationTaskEffectivelyTerminal(latestTask, target.mediaKind)) {
        stopAssetGenerationPolling(workbench);
        const remainingTarget = resolveSelectedAssetGenerationPollTarget(workbench, target.mediaKind);
        if (remainingTarget) {
          workbench.assetGenerationPollStartedAt = Date.now();
        }
        workbench.ui.generationPollingActive = Boolean(remainingTarget);
        if (!remainingTarget) {
          workbench.assetGenerationPollStartedAt = null;
        }
        render(workbench);
        if (remainingTarget) {
          scheduleSelectedAssetGenerationPolling(workbench, target.mediaKind, { immediate: true });
        }
        return;
      }
      renderEpisodeWorkbenchPollingUpdate(workbench);
      scheduleSelectedAssetGenerationPolling(workbench, target.mediaKind);
    } catch (error) {
      stopAssetGenerationPolling(workbench);
      workbench.ui.toast = `轮询刷新失败：${friendlyError(error)}`;
      render(workbench);
    }
  }, delayMs);
}

function scheduleAssetBatchGenerationPolling(workbench, mediaKind = "image", options = {}) {
  if (
    typeof window === "undefined" ||
    typeof window.setTimeout !== "function" ||
    (
      typeof workbench.api?.getGenerationTasks !== "function" &&
      typeof workbench.api?.getGenerationTask !== "function"
    )
  ) {
    return;
  }
  const targets = resolveAssetBatchGenerationPollTargets(workbench, mediaKind);
  if (!targets.length) {
    stopAssetBatchGenerationPolling(workbench);
    workbench.ui.generationPollingActive = false;
    return;
  }
  const scopeKey = targets.map((target) => target.scopeKey).sort().join("|");
  if (workbench.assetBatchGenerationPollTimer && workbench.assetBatchGenerationPollScopeKey === scopeKey) {
    return;
  }

  stopAssetBatchGenerationPolling(workbench);
  workbench.assetBatchGenerationPollStartedAt = workbench.assetBatchGenerationPollStartedAt ?? Date.now();
  workbench.assetBatchGenerationPollScopeKey = scopeKey;
  const delayMs = resolveGenerationPollDelayMs(mediaKind, workbench.assetBatchGenerationPollStartedAt, options.immediate === true);
  workbench.assetBatchGenerationPollTimer = window.setTimeout(async () => {
    workbench.assetBatchGenerationPollTimer = null;
    let settled = [];
    try {
      if (typeof workbench.api?.getGenerationTasks === "function") {
        const response = await workbench.api.getGenerationTasks(targets.map((target) => target.taskId));
        const tasksById = new Map(
          (Array.isArray(response?.items) ? response.items : [])
            .map((task) => [resolveGenerationTaskIdForConversation(task), task])
            .filter(([taskId]) => taskId),
        );
        targets.forEach((target) => {
          const latestTask = tasksById.get(target.taskId);
          if (latestTask) {
            applyAssetBatchGenerationTaskResult(workbench, latestTask, target.entry, target.mediaKind);
          }
        });
        settled = [{ ok: true }];
      } else {
        settled = await Promise.all(targets.map(async (target) => {
          try {
            const latestTask = await workbench.api.getGenerationTask(target.taskId);
            applyAssetBatchGenerationTaskResult(workbench, latestTask, target.entry, target.mediaKind);
            return { ok: true };
          } catch (error) {
            return { ok: false, error };
          }
        }));
      }
    } catch (batchError) {
      settled = await Promise.all(targets.map(async (target) => {
        try {
          if (typeof workbench.api?.getGenerationTask !== "function") {
            throw batchError;
          }
          const latestTask = await workbench.api.getGenerationTask(target.taskId);
          applyAssetBatchGenerationTaskResult(workbench, latestTask, target.entry, target.mediaKind);
          return { ok: true };
        } catch (error) {
          return { ok: false, error };
        }
      }));
    }
    const firstError = settled.find((item) => item.ok === false)?.error;
    if (firstError) {
      workbench.ui.toast = `轮询刷新失败：${friendlyError(firstError)}`;
    }
    const hasPending = resolveAssetBatchGenerationPollTargets(workbench, mediaKind).length > 0;
    workbench.ui.generationPollingActive = hasPending;
    if (hasPending) {
      renderEpisodeWorkbenchPollingUpdate(workbench);
    } else {
      render(workbench);
    }
    if (hasPending) {
      scheduleAssetBatchGenerationPolling(workbench, mediaKind);
    } else {
      stopAssetBatchGenerationPolling(workbench);
    }
  }, delayMs);
}

function stopAssetBatchGenerationPolling(workbench) {
  if (workbench.assetBatchGenerationPollTimer) {
    if (typeof window !== "undefined" && typeof window.clearTimeout === "function") {
      window.clearTimeout(workbench.assetBatchGenerationPollTimer);
    }
    workbench.assetBatchGenerationPollTimer = null;
  }
  workbench.assetBatchGenerationPollScopeKey = null;
  if (!workbench.ui.generationPollingActive) {
    workbench.assetBatchGenerationPollStartedAt = null;
  }
}

function stopAssetGenerationPolling(workbench) {
  if (workbench.assetGenerationPollTimer) {
    if (typeof window !== "undefined" && typeof window.clearTimeout === "function") {
      window.clearTimeout(workbench.assetGenerationPollTimer);
    }
    workbench.assetGenerationPollTimer = null;
  }
  workbench.assetGenerationPollScopeKey = null;
  if (!workbench.ui.generationPollingActive) {
    workbench.assetGenerationPollStartedAt = null;
  }
}

function resolveProjectAssetGenerationTaskId(asset) {
  const result = asset?.generationResult ?? {};
  const value =
    asset?.generationTaskId ??
    result?.taskId ??
    result?.generationTaskId ??
    result?.platform?.tasks?.[0]?.taskId ??
    asset?.latestVersion?.metadata?.generationTaskId ??
    "";
  return String(value ?? "").trim();
}

function resolveProjectAssetTaskPreviewUrl(task) {
  const result = task?.result ?? {};
  return resolvePreferredFixedImageUrl(
    task?.previewUrl,
    task?.imageUrl,
    task?.version?.previewUrl,
    task?.version?.metadata?.previewUrl,
    task?.version?.metadata?.sourceUrl,
    result?.imageUrl,
    result?.previewUrl,
    result?.sourceUrl,
    result?.downloadUrl,
    result?.thumbnailUrl,
    task?.fixedImages?.[0]?.previewUrl,
    task?.fixedImages?.[0]?.url,
    task?.fixedImages?.[0]?.src,
  );
}

function applyProjectAssetGenerationTaskResult(workbench, asset, task) {
  const status = resolveWorkflowStatus(task?.status ?? task?.workflowStatus ?? "running");
  const previewUrl = resolveProjectAssetTaskPreviewUrl(task);
  const taskId = resolveProjectAssetGenerationTaskId(asset) || String(task?.taskId ?? "").trim();
  const assetKind = asset?.assetKind ?? asset?.kind ?? workbench.ui.assetGeneratorModal ?? workbench.ui.projectAssetTab ?? "character";
  const mediaType = asset?.mediaType ?? workbench.ui.projectOtherAssetMediaType ?? "image";
  const nextAsset = {
    ...asset,
    generationTaskId: taskId,
    generationStatus: status,
    generationResult: task,
    preview: previewUrl || asset?.preview || "",
    previewUrl: previewUrl || asset?.previewUrl || "",
    fixedImageUrl: previewUrl || asset?.fixedImageUrl || "",
    latestVersion: {
      ...(asset?.latestVersion ?? {}),
      previewUrl: previewUrl || asset?.latestVersion?.previewUrl || "",
      metadata: {
        ...(asset?.latestVersion?.metadata ?? {}),
        ...(previewUrl ? { previewUrl, fixedImageUrl: previewUrl, sourceUrl: previewUrl, downloadUrl: previewUrl } : {}),
        generationTaskId: taskId,
        generationStatus: status,
        generationResult: task,
      },
    },
  };
  upsertProjectGeneratedAsset(
    workbench,
    assetKind,
    nextAsset,
    nextAsset.name ?? asset?.name ?? "",
    nextAsset.description ?? asset?.description ?? "",
    task,
    { status, mediaType },
  );
  if (String(workbench.ui.assetGeneratorEditingAsset?.id ?? "") === String(asset?.id ?? "")) {
    workbench.ui.assetGeneratorEditingAsset = {
      ...workbench.ui.assetGeneratorEditingAsset,
      ...nextAsset,
      assetKind,
      mediaType,
    };
    if (previewUrl) {
      workbench.ui.assetGeneratorPreviewUrl = previewUrl;
    }
  }
  return nextAsset;
}

function stopProjectAssetGenerationPolling(workbench) {
  if (workbench.projectAssetGenerationPollTimer) {
    if (typeof window !== "undefined" && typeof window.clearTimeout === "function") {
      window.clearTimeout(workbench.projectAssetGenerationPollTimer);
    }
    workbench.projectAssetGenerationPollTimer = null;
  }
  workbench.projectAssetGenerationPollScopeKey = null;
}

function isProjectAssetPollingViewActive(workbench) {
  if (workbench.ui.projectPanelMode === "episode-workbench") {
    return (workbench.ui.museScopeMode ?? "storyboard") === "assets";
  }
  return (
    workbench.ui.activeNavTab === "project" &&
    workbench.ui.projectPanelMode === "workspace" &&
    workbench.ui.projectInteriorSection === "assets"
  );
}

function resolveProjectAssetPollingCandidates(workbench) {
  if (!isProjectAssetPollingViewActive(workbench)) {
    return [];
  }
  const assetKind = workbench.ui.projectAssetTab ?? "character";
  if (assetKind === "other") {
    return [];
  }
  const assets = getImportedAssetBucket(
    workbench.ui.importedAssets,
    assetKind,
    workbench.ui.projectOtherAssetMediaType ?? "audio",
  );
  return assets
    .filter((asset) => {
      const taskId = resolveProjectAssetGenerationTaskId(asset);
      const status = resolveWorkflowStatus(asset?.generationStatus ?? asset?.generationResult?.status ?? asset?.generationResult?.workflowStatus);
      return Boolean(taskId) && isGenerationTaskPendingStatus(status);
    })
    .sort((left, right) => {
      const leftUpdated = Date.parse(left?.updatedAt ?? left?.createdAt ?? 0) || 0;
      const rightUpdated = Date.parse(right?.updatedAt ?? right?.createdAt ?? 0) || 0;
      return rightUpdated - leftUpdated;
    });
}

function syncProjectAssetGenerationPollingForCurrentView(workbench, options = {}) {
  if (!isProjectAssetPollingViewActive(workbench)) {
    stopProjectAssetGenerationPolling(workbench);
    return;
  }
  const forceImmediate = options.immediate === true;
  if (workbench.ui.assetGeneratorModal && workbench.ui.assetGeneratorEditingAsset) {
    const editingAsset = workbench.ui.assetGeneratorEditingAsset;
    const editingTaskId = resolveProjectAssetGenerationTaskId(editingAsset);
    const editingStatus = resolveWorkflowStatus(
      editingAsset?.generationStatus ??
      editingAsset?.generationResult?.status ??
      editingAsset?.generationResult?.workflowStatus,
    );
    if (editingTaskId && isGenerationTaskPendingStatus(editingStatus)) {
      const scopeKey = `${editingAsset?.id ?? ""}:${editingTaskId}`;
      scheduleProjectAssetGenerationPolling(workbench, editingAsset, {
        immediate: forceImmediate || workbench.projectAssetGenerationPollScopeKey !== scopeKey,
      });
      return;
    }
  }
  const [candidate] = resolveProjectAssetPollingCandidates(workbench);
  if (!candidate) {
    stopProjectAssetGenerationPolling(workbench);
    return;
  }
  const taskId = resolveProjectAssetGenerationTaskId(candidate);
  const scopeKey = `${candidate?.id ?? ""}:${taskId}`;
  scheduleProjectAssetGenerationPolling(workbench, candidate, {
    immediate: forceImmediate || workbench.projectAssetGenerationPollScopeKey !== scopeKey,
  });
}

function scheduleProjectAssetGenerationPolling(workbench, asset, options = {}) {
  if (
    typeof window === "undefined" ||
    typeof window.setTimeout !== "function" ||
    typeof workbench.api?.getGenerationTask !== "function"
  ) {
    return;
  }
  const taskId = resolveProjectAssetGenerationTaskId(asset);
  if (!taskId) {
    stopProjectAssetGenerationPolling(workbench);
    return;
  }
  const scopeKey = `${asset?.id ?? ""}:${taskId}`;
  if (workbench.projectAssetGenerationPollTimer && workbench.projectAssetGenerationPollScopeKey === scopeKey) {
    return;
  }
  stopProjectAssetGenerationPolling(workbench);
  workbench.projectAssetGenerationPollScopeKey = scopeKey;
  const delayMs = options.immediate ? 0 : GENERATION_POLL_INTERVAL_MS;
  workbench.projectAssetGenerationPollTimer = window.setTimeout(async () => {
    workbench.projectAssetGenerationPollTimer = null;
    try {
      const latestTask = await workbench.api.getGenerationTask(taskId);
      const nextAsset = applyProjectAssetGenerationTaskResult(workbench, asset, latestTask);
      const status = resolveWorkflowStatus(latestTask?.status ?? latestTask?.workflowStatus);
      if (isGenerationTaskTerminalStatus(status)) {
        stopProjectAssetGenerationPolling(workbench);
        if (typeof workbench.api?.updateProjectAsset === "function") {
          const previewUrl = resolveProjectAssetTaskPreviewUrl(latestTask);
          await workbench.api.updateProjectAsset(nextAsset.id, {
            generationTaskId: taskId,
            generationStatus: status,
            generationResult: latestTask,
            ...(previewUrl ? { previewUrl, sourceUrl: previewUrl, downloadUrl: previewUrl } : {}),
          });
        }
        renderEpisodeWorkbenchPollingUpdate(workbench);
        syncProjectAssetGenerationPollingForCurrentView(workbench);
        return;
      }
      renderEpisodeWorkbenchPollingUpdate(workbench);
      syncProjectAssetGenerationPollingForCurrentView(workbench);
    } catch (error) {
      stopProjectAssetGenerationPolling(workbench);
      workbench.ui.toast = `任务状态刷新失败：${friendlyError(error)}`;
      render(workbench);
    }
  }, delayMs);
}

function stopGenerationPolling(workbench) {
  if (workbench.generationPollTimer) {
    window.clearTimeout(workbench.generationPollTimer);
    workbench.generationPollTimer = null;
  }
  workbench.generationPollScopeKey = null;
  if (!workbench.ui.generationPollingActive) {
    workbench.generationPollStartedAt = null;
  }
}

function finishGenerationPolling(workbench, storyboardId, mediaKind) {
  stopGenerationPolling(workbench);
  workbench.generationPollStartedAt = null;
  workbench.ui.generationPollingActive = false;
  const targetKey = mediaKind === "video" ? "videoGenerationResult" : "imageGenerationResult";
  const currentStatus = resolveWorkflowStatus(
    workbench.ui[targetKey]?.status ??
      workbench.ui[targetKey]?.platform?.workflowStatus,
  );
  if (isGenerationTaskTerminalStatus(currentStatus) && currentStatus !== "completed") {
    renderEpisodeWorkbenchPollingUpdate(workbench);
    return;
  }
  updateStoryboardGenerationState(workbench, storyboardId, (generationState) => ({
    ...generationState,
    lastSubmission: generationState.lastSubmission
      ? { ...generationState.lastSubmission, status: "completed" }
      : generationState.lastSubmission,
  }));
  if (workbench.ui[targetKey]) {
    workbench.ui[targetKey] = {
      ...workbench.ui[targetKey],
      status: "completed",
    };
  }
  renderEpisodeWorkbenchPollingUpdate(workbench);
}

function resolveSelectedStoryboardGenerationPollTarget(workbench, storyboardId, mediaKind = "image") {
  if (
    workbench.ui.projectPanelMode !== "episode-workbench" ||
    (workbench.ui.museScopeMode ?? "storyboard") !== "storyboard" ||
    typeof workbench.api?.getGenerationTask !== "function"
  ) {
    return null;
  }
  const normalizedStoryboardId = String(storyboardId ?? workbench.ui.selectedStoryboardId ?? "").trim();
  if (!normalizedStoryboardId) {
    return null;
  }
  const selectedStoryboard =
    getActiveStoryboards(workbench).find((item) => item.id === normalizedStoryboardId) ??
    (String(workbench.ui.selectedStoryboard?.id ?? "") === normalizedStoryboardId ? workbench.ui.selectedStoryboard : null) ??
    (Array.isArray(workbench.ui.storyboards)
      ? workbench.ui.storyboards.find((item) => item.id === normalizedStoryboardId)
      : null) ??
    null;
  const acceptableStoryboardIds = new Set(
    [
      normalizedStoryboardId,
      selectedStoryboard?.storyboardId,
      selectedStoryboard?.linkedShotId,
      selectedStoryboard?.shotId,
    ]
      .map((value) => String(value ?? "").trim())
      .filter(Boolean),
  );
  const entries = listStoryboardConversationHistoryEntries(workbench, normalizedStoryboardId, mediaKind);
  const candidates = [
    ...(Array.isArray(entries) ? entries : []),
    selectedStoryboard?.generationState?.lastSubmission
      ? {
          ...selectedStoryboard.generationState.lastSubmission,
          storyboardId: normalizedStoryboardId,
          selectionContext: {
            ...(selectedStoryboard.generationState.lastSubmission.selectionContext ?? {}),
            selectedStoryboardId: normalizedStoryboardId,
          },
        }
      : null,
    mediaKind === "video" ? workbench.ui.videoGenerationResult : workbench.ui.imageGenerationResult,
  ].filter(Boolean);
  const pendingEntry = [...candidates].reverse().find((entry) => {
    const entryMediaKind = String(entry?.mediaKind ?? "").trim().toLowerCase();
    if ((entryMediaKind === "image" || entryMediaKind === "video") && entryMediaKind !== mediaKind) {
      return false;
    }
    const entryStoryboardId = String(
      entry?.storyboardId ??
        entry?.selectionContext?.selectedStoryboardId ??
        "",
    ).trim();
    const taskId = resolveGenerationTaskIdForConversation(entry);
    const status = resolveWorkflowStatus(entry?.status ?? entry?.platform?.workflowStatus ?? entry?.workflowStatus);
    return acceptableStoryboardIds.has(entryStoryboardId) && Boolean(taskId) && isGenerationTaskPendingStatus(status);
  });
  if (!pendingEntry) {
    return null;
  }
  const taskId = resolveGenerationTaskIdForConversation(pendingEntry);
  return {
    storyboardId: normalizedStoryboardId,
    mediaKind,
    taskId,
    entry: pendingEntry,
  };
}

function resumeSelectedStoryboardGenerationPolling(workbench, options = {}) {
  if (typeof window === "undefined" || typeof window.setTimeout !== "function") {
    return false;
  }
  const mediaKind = options.mediaKind === "video" ? "video" : "image";
  const target = resolveSelectedStoryboardGenerationPollTarget(workbench, options.storyboardId, mediaKind);
  if (!target) {
    return false;
  }
  const targetKey = mediaKind === "video" ? "videoGenerationResult" : "imageGenerationResult";
  workbench.ui[targetKey] = {
    ...(workbench.ui[targetKey] ?? {}),
    ...(target.entry ?? {}),
    taskId: target.taskId,
    status: resolveWorkflowStatus(target.entry?.status ?? target.entry?.platform?.workflowStatus ?? "running"),
  };
  workbench.ui.generationPollingActive = true;
  scheduleGenerationPolling(workbench, target.storyboardId, mediaKind, { immediate: options.immediate === true });
  return true;
}

function resolveSelectedAssetGenerationPollTarget(workbench, mediaKind = "image") {
  if (
    workbench.ui.projectPanelMode !== "episode-workbench" ||
    (workbench.ui.museScopeMode ?? "storyboard") !== "assets" ||
    typeof workbench.api?.getGenerationTask !== "function"
  ) {
    return null;
  }
  const assetId = workbench.ui.selectedEpisodeAssetId ?? workbench.ui.selectedEpisodeCardId ?? null;
  if (!assetId) {
    return null;
  }
  const entries = listAssetConversationHistoryEntries(workbench, assetId, mediaKind);
  const candidates = [
    ...(Array.isArray(entries) ? entries : []),
    mediaKind === "video" ? workbench.ui.videoGenerationResult : workbench.ui.imageGenerationResult,
  ].filter(Boolean);
  const pendingEntry = [...candidates].reverse().find((entry) => {
    const entryAssetId = entry?.assetId ?? entry?.selectionContext?.selectedAssetId ?? null;
    const taskId = resolveGenerationTaskIdForConversation(entry);
    const status = resolveWorkflowStatus(entry?.status ?? entry?.platform?.workflowStatus ?? entry?.workflowStatus);
    return entryAssetId === assetId && Boolean(taskId) && isGenerationTaskPendingStatus(status);
  });
  if (!pendingEntry) {
    return null;
  }
  const taskId = resolveGenerationTaskIdForConversation(pendingEntry);
  return {
    assetId,
    mediaKind,
    taskId,
    entry: pendingEntry,
    scopeKey: `${mediaKind}:${assetId}:${taskId}`,
  };
}

function resolveAssetBatchGenerationPollTargets(workbench, mediaKind = "image") {
  if (
    workbench.ui.projectPanelMode !== "episode-workbench" ||
    (workbench.ui.museScopeMode ?? "storyboard") !== "assets" ||
    typeof workbench.api?.getGenerationTask !== "function"
  ) {
    return [];
  }
  const batchResults = workbench.ui.episodeBatchResults ?? {};
  return Object.entries(batchResults)
    .map(([assetId, entry]) => {
      const taskId = resolveGenerationTaskIdForConversation(entry);
      const status = resolveWorkflowStatus(entry?.status ?? entry?.platform?.workflowStatus ?? entry?.workflowStatus);
      const entryMediaKind = entry?.mediaKind === "video" ? "video" : "image";
      if (!taskId || entryMediaKind !== mediaKind || !isGenerationTaskPendingStatus(status)) {
        return null;
      }
      return {
        assetId,
        mediaKind,
        taskId,
        entry,
        scopeKey: `${mediaKind}:${assetId}:${taskId}`,
      };
    })
    .filter(Boolean);
}

function applyAssetBatchGenerationTaskResult(workbench, task, submission, mediaKind = "image") {
  if (!task || !submission) {
    return;
  }
  const normalized = normalizeEpisodeTaskForLegacyResult(task, submission, mediaKind);
  const assetId =
    normalized?.assetId ??
    submission?.assetId ??
    normalized?.selectionContext?.selectedAssetId ??
    submission?.selectionContext?.selectedAssetId ??
    null;
  if (!assetId) {
    return;
  }
  const result = {
    ...submission,
    ...normalized,
    status:
      resolveGenerationTaskDisplayStatus(normalized) === "completed" &&
      !hasGenerationTaskMediaResult(normalized, mediaKind)
        ? "running"
        : resolveGenerationTaskDisplayStatus(normalized),
    taskId: normalized?.platform?.tasks?.[0]?.taskId ?? normalized?.taskId ?? submission?.taskId ?? null,
    fixedImages: normalized?.fixedImages ?? submission?.fixedImages ?? [],
    selectionContext: normalized?.selectionContext ?? submission.selectionContext,
  };
  workbench.ui.episodeBatchResults = {
    ...(workbench.ui.episodeBatchResults ?? {}),
    [assetId]: result,
  };
  seedGeneratedEpisodeAsset(
    workbench,
    resolveGeneratedEpisodeAssetKind(workbench, assetId, result?.selectionContext?.assetTab ?? "character"),
    assetId,
    result?.selectionContext?.selectedAssetName ?? submission?.selectionContext?.selectedAssetName ?? "",
    result?.selectionContext?.selectedAssetDescription ?? submission?.selectionContext?.selectedAssetDescription ?? result?.promptPreview ?? "",
    result,
  );
  appendAssetConversationHistoryEntry(workbench, result);
  if (Number.isFinite(Number(result?.creditBalance))) {
    setWorkbenchCreditBalance(workbench, Number(result.creditBalance));
  }
  if (workbench.ui.selectedEpisodeAssetId === assetId || workbench.ui.selectedEpisodeCardId === assetId) {
    workbench.ui.imageGenerationResult = result;
  }
  if (isGenerationTaskEffectivelyTerminal(result, mediaKind)) {
    void persistAssetConversationEntry(workbench, result).catch(() => {});
  }
}

function isGenerationTaskPendingStatus(status) {
  return new Set(["queued", "running", "pending", "submitted", "accepted", "provider_submitted", "processing"])
    .has(String(status ?? "").toLowerCase());
}

function isGenerationTaskTerminalStatus(status) {
  return new Set(["completed", "succeeded", "failed", "canceled", "manual_review_required", "result_unknown"])
    .has(String(status ?? "").toLowerCase());
}

function hasGenerationTaskMediaResult(taskOrResult, mediaKind = "image") {
  if (mediaKind === "video") {
    return Boolean(
      readPublicGenerationMediaUrl(
        taskOrResult?.result?.videoUrl,
        taskOrResult?.videoUrl,
        taskOrResult?.fixedVideos?.[0]?.url,
        taskOrResult?.fixedVideos?.[0]?.src,
      ),
    );
  }
  return Boolean(
    taskOrResult?.result?.imageUrl ||
      taskOrResult?.result?.previewUrl ||
      taskOrResult?.imageUrl ||
      taskOrResult?.previewUrl ||
      taskOrResult?.fixedImages?.[0]?.url ||
      taskOrResult?.fixedImages?.[0]?.previewUrl ||
      taskOrResult?.fixedImages?.[0]?.src,
  );
}

function isGenerationTaskEffectivelyTerminal(taskOrResult, mediaKind = "image") {
  const status = resolveWorkflowStatus(taskOrResult?.status ?? taskOrResult?.workflowStatus);
  if (["failed", "canceled", "manual_review_required", "result_unknown"].includes(status)) {
    return true;
  }
  if (status === "completed" || status === "succeeded") {
    return hasGenerationTaskMediaResult(taskOrResult, mediaKind);
  }
  return false;
}

function isRealEpisodeWorkbench(workbench) {
  return (
    workbench.ui.projectPanelMode === "episode-workbench" &&
    hasPersistedEpisodeWorkbenchId(workbench)
  );
}

function isLipSyncTaskLike(taskOrResult) {
  const candidate = taskOrResult ?? {};
  const parameters =
    candidate.parameters && typeof candidate.parameters === "object"
      ? candidate.parameters
      : candidate.result?.parameters && typeof candidate.result.parameters === "object"
        ? candidate.result.parameters
        : {};
  return (
    candidate.lipSyncEnabled === true ||
    parameters?.mode === "lip-sync" ||
    (Array.isArray(candidate.generatedAudioItems) && candidate.generatedAudioItems.length > 0) ||
    (Array.isArray(candidate.result?.generatedAudioItems) && candidate.result.generatedAudioItems.length > 0)
  );
}

function normalizeEpisodeTaskForLegacyResult(task, submission, mediaKind) {
  const taskPayload = resolveGenerationTaskResponsePayload(task) ?? {};
  const result = taskPayload?.result ?? {};
  const mediaUrl = mediaKind === "video"
    ? readPublicGenerationMediaUrl(result.videoUrl, result.sourceUrl, result.downloadUrl, result.previewUrl)
    : result.imageUrl;
  const isLipSync = mediaKind === "video" && isLipSyncTaskLike(taskPayload);
  const selectionContext =
    taskPayload?.selectionContext && typeof taskPayload.selectionContext === "object"
      ? taskPayload.selectionContext
      : submission?.selectionContext && typeof submission.selectionContext === "object"
        ? submission.selectionContext
        : {};
  const targetType = taskPayload?.targetType ?? submission?.targetType ?? null;
  const targetId = taskPayload?.targetId ?? submission?.targetId ?? null;
  const taskParameters =
    taskPayload?.parameters && typeof taskPayload.parameters === "object"
      ? taskPayload.parameters
      : result?.parameters && typeof result.parameters === "object"
        ? result.parameters
        : {};
  const assetId =
    taskPayload?.assetId ??
    result?.assetId ??
    (targetType === "asset" ? targetId : null) ??
    submission?.assetId ??
    selectionContext?.selectedAssetId ??
    null;
  const generatedAudioItems = Array.isArray(taskPayload?.generatedAudioItems)
    ? taskPayload.generatedAudioItems
    : Array.isArray(result.generatedAudioItems)
      ? result.generatedAudioItems
      : submission?.generatedAudioItems ?? [];
  const resolvedResolution = resolveGenerationDisplayResolution(taskParameters, submission?.resolution) || submission?.resolution || null;
  const resolvedAspectRatio = resolveGenerationDisplayAspectRatio(taskParameters, submission?.aspectRatio) || submission?.aspectRatio || null;
  const resolvedCreditCost = resolveGenerationDisplayCreditCost(taskPayload, submission);
  const taskId = resolveGenerationTaskIdForConversation(taskPayload);
  const progressPercent = resolveGenerationTaskProgressPercent(taskPayload, submission);
  const progressStage = resolveGenerationTaskProgressStage(taskPayload, submission);
  return {
    ...taskPayload,
    ...submission,
    status: taskPayload?.status === "succeeded" ? "completed" : taskPayload?.status ?? "running",
    mediaKind,
    assetId,
    targetType,
    targetId,
    taskId: taskId || null,
    platform: {
      workflowId: taskPayload?.workflowId ?? null,
      workflowStatus: taskPayload?.workflowStatus ?? taskPayload?.status ?? "running",
      progressPercent,
      progressStage,
      tasks: taskId ? [{ taskId, status: taskPayload?.status }] : [],
    },
    progressPercent,
    progress_percent: progressPercent,
    progressStage,
    progress_stage: progressStage,
    fixedImages: mediaKind === "image" && mediaUrl
      ? [{
          id: result.storageObjectId ?? taskId,
          label: "分镜图片",
          url: mediaUrl,
          storageObjectId: result.storageObjectId ?? null,
          assetVersionId: null,
        }]
      : [],
    fixedVideos: mediaKind === "video" && mediaUrl && !isLipSync
      ? [{
          id: result.assetVersionId ?? result.storageObjectId ?? taskId,
          label: "分镜视频",
          src: mediaUrl,
          url: mediaUrl,
          storageObjectId: result.storageObjectId ?? null,
          assetVersionId: result.assetVersionId ?? null,
        }]
      : [],
    generatedAudioItems,
    result,
    selectionContext,
    resolution: resolvedResolution,
    aspectRatio: resolvedAspectRatio,
    creditCost: resolvedCreditCost,
    failure: taskPayload?.failure ?? submission?.failure ?? null,
    failureCode: taskPayload?.failureCode ?? taskPayload?.failure?.failureCode ?? submission?.failureCode ?? null,
    noticeType: taskPayload?.failure?.noticeType ?? taskPayload?.noticeType ?? submission?.noticeType ?? null,
    creditBalance: taskPayload?.creditBalance ?? null,
  };
}

function readPublicGenerationMediaUrl(...values) {
  for (const value of values) {
    const url = String(value ?? "").trim();
    if (url && !isProviderDirectContentUrl(url)) {
      return url;
    }
  }
  return "";
}

function isProviderDirectContentUrl(value) {
  try {
    const url = new URL(value, globalThis.location?.href ?? "http://localhost/");
    return (
      /(^|\.)lingdongapi\.com$/i.test(url.hostname) &&
      /^\/v1\/(?:videos|images)\/[^/]+\/content$/i.test(url.pathname)
    );
  } catch {
    return false;
  }
}

function resolveGenerationTaskProgressPercent(taskPayload, submission) {
  const rawValue =
    taskPayload?.progressPercent ??
    taskPayload?.progress_percent ??
    taskPayload?.progress?.percent ??
    taskPayload?.snapshot?.progressPercent ??
    taskPayload?.snapshot?.progress_percent ??
    taskPayload?.snapshot?.progress?.percent ??
    taskPayload?.platform?.progressPercent ??
    taskPayload?.platform?.progress_percent ??
    taskPayload?.platform?.progress?.percent ??
    submission?.progressPercent ??
    submission?.progress_percent ??
    submission?.progress?.percent ??
    submission?.snapshot?.progressPercent ??
    submission?.snapshot?.progress_percent ??
    submission?.platform?.progressPercent ??
    submission?.platform?.progress_percent;
  const value = Number(rawValue);
  if (!Number.isFinite(value)) {
    return null;
  }
  const percent = value > 0 && value <= 1 ? value * 100 : value;
  return Math.max(0, Math.min(100, Math.round(percent)));
}

function resolveGenerationTaskProgressStage(taskPayload, submission) {
  return String(
    taskPayload?.progressStage ??
      taskPayload?.progress_stage ??
      taskPayload?.snapshot?.progressStage ??
      taskPayload?.snapshot?.progress_stage ??
      taskPayload?.platform?.progressStage ??
      taskPayload?.platform?.progress_stage ??
      submission?.progressStage ??
      submission?.progress_stage ??
      "",
  ).trim() || null;
}

export function applyEpisodeGenerationTaskResult(workbench, task, storyboardId, mediaKind, options = {}) {
  if (!task) {
    return;
  }
  const shouldPersistConversation = options.persistConversation !== false;
  const targetKey = mediaKind === "video" ? "videoGenerationResult" : "imageGenerationResult";
  const current = workbench.ui[targetKey] ?? {};
  const normalized = normalizeEpisodeTaskForLegacyResult(task, current, mediaKind);
  const isAssetScope = (workbench.ui.museScopeMode ?? "storyboard") === "assets";
  if (!isAssetScope && storyboardId && !isStoryboardConversationEntryForTarget(workbench, normalized, storyboardId)) {
    return;
  }
  const targetType = String(
    task?.targetType ??
      normalized?.targetType ??
      task?.result?.targetType ??
      normalized?.result?.targetType ??
      normalized?.selectionContext?.targetType ??
      "",
  ).trim();
  const shouldUseStoryboardConversation = Boolean(storyboardId) && targetType !== "asset";
  const assetConversationAssetId =
    shouldUseStoryboardConversation
      ? null
      : normalized?.assetId ??
        current?.assetId ??
        (isAssetScope
          ? normalized?.selectionContext?.selectedAssetId ?? current?.selectionContext?.selectedAssetId ?? null
          : null);
  if (
    resolveWorkflowStatus(normalized?.status) === "completed" &&
    !hasGenerationTaskMediaResult(normalized, mediaKind)
  ) {
    normalized.status = "running";
    normalized.platform = {
      ...(normalized.platform ?? {}),
      workflowStatus: "running",
    };
  }
  workbench.ui[targetKey] = normalized;
  if (assetConversationAssetId) {
    const assetConversationEntry = {
      ...normalized,
      assetId: assetConversationAssetId,
    };
    const assetConversationTaskId = resolveGenerationTaskIdForConversation(assetConversationEntry);
    const isNewAssetConversationEntry = !assetConversationTaskId ||
      !listAssetConversationHistoryEntries(workbench, assetConversationAssetId, mediaKind).some(
        (item) => resolveGenerationTaskIdForConversation(item) === assetConversationTaskId,
      );
    appendAssetConversationHistoryEntry(workbench, assetConversationEntry);
    if (
      isNewAssetConversationEntry &&
      workbench.ui.projectPanelMode === "episode-workbench" &&
      isAssetScope
    ) {
      workbench.ui.episodeWorkbenchConversationScrollMode = "latest";
    }
    if (shouldPersistConversation) {
      void persistAssetConversationEntry(workbench, assetConversationEntry).catch(() => {});
    }
  }
  if (shouldUseStoryboardConversation) {
    const storyboardConversationEntry = {
      ...normalized,
      storyboardId,
      selectionContext: {
        ...(normalized.selectionContext ?? {}),
        selectedStoryboardId: storyboardId,
      },
    };
    const storyboardConversationTaskId = resolveGenerationTaskIdForConversation(storyboardConversationEntry);
    const isNewStoryboardConversationEntry = !storyboardConversationTaskId ||
      !listStoryboardConversationHistoryEntries(workbench, storyboardId, mediaKind).some(
        (item) => resolveGenerationTaskIdForConversation(item) === storyboardConversationTaskId,
      );
    appendStoryboardConversationHistoryEntry(workbench, storyboardConversationEntry);
    if (isNewStoryboardConversationEntry && workbench.ui.projectPanelMode === "episode-workbench" && !isAssetScope) {
      workbench.ui.episodeWorkbenchConversationScrollMode = "latest";
    }
    if (shouldPersistConversation) {
      void persistStoryboardConversationEntry(workbench, storyboardConversationEntry, { includeUserRequest: true }).catch(() => {});
    }
  }
  if (shouldUseStoryboardConversation) {
    const nextTaskId = resolveGenerationTaskIdForConversation(normalized);
    const nextStatus = resolveWorkflowStatus(
      normalized?.status ??
        normalized?.platform?.workflowStatus ??
        task?.status ??
        task?.workflowStatus,
    );
    if (nextTaskId || nextStatus) {
      updateStoryboardGenerationState(workbench, storyboardId, (generationState) => ({
        ...generationState,
        lastSubmission: {
          ...(generationState.lastSubmission ?? {}),
          mediaKind,
          ...(nextTaskId ? { taskId: nextTaskId } : {}),
          ...(nextStatus ? { status: nextStatus } : {}),
        },
      }));
    }
  }
  if (mediaKind === "video" && Array.isArray(normalized.generatedAudioItems) && normalized.generatedAudioItems.length > 0) {
    workbench.ui.lipSyncAudioItems = normalized.generatedAudioItems;
  }
  if (Number.isFinite(Number(normalized.creditBalance))) {
    workbench.ui.creditBalance = Number(normalized.creditBalance);
  }
  if (["failed", "canceled", "manual_review_required", "result_unknown"].includes(String(task.status ?? normalized.status ?? ""))) {
    updateStoryboardGenerationState(workbench, storyboardId, (generationState) => ({
      ...generationState,
      lastSubmission: generationState.lastSubmission
        ? { ...generationState.lastSubmission, status: "failed" }
        : generationState.lastSubmission,
    }));
    if (!options.suppressFailureToast) {
      workbench.ui.toast = generationTaskNoticePrefix(task) + generationTaskFailureMessage(task);
    }
    return;
  }
  if (resolveWorkflowStatus(task.status) !== "completed") {
    return;
  }
  if (mediaKind === "video" && isLipSyncTaskLike(task)) {
    updateStoryboardGenerationState(workbench, storyboardId, (generationState) => ({
      ...generationState,
      lastSubmission: generationState.lastSubmission
        ? { ...generationState.lastSubmission, status: "completed" }
        : generationState.lastSubmission,
    }));
    return;
  }
  const mediaUrl = mediaKind === "video" ? task.result?.videoUrl : task.result?.imageUrl;
  if (!mediaUrl) {
    return;
  }
  updateStoryboardGenerationState(workbench, storyboardId, (generationState) => ({
    ...generationState,
    lastSubmission: generationState.lastSubmission
      ? { ...generationState.lastSubmission, status: "completed" }
      : generationState.lastSubmission,
  }));
  if (mediaKind === "image") {
    return;
  }
  const storyboards = getActiveStoryboards(workbench).map((storyboard) => {
    if (storyboard.id !== storyboardId) {
      return storyboard;
    }
    if (mediaKind === "video") {
      const videoId = task.result?.assetVersionId ?? task.result?.storageObjectId ?? task.taskId;
      return {
        ...storyboard,
        currentVideoAssetVersionId: task.result?.assetVersionId ?? storyboard.currentVideoAssetVersionId ?? null,
        selectedUploadedVideoId: videoId,
        previewVideo: mediaUrl,
        videoStatus: "ready",
        uploadedVideos: mergeStoryboardUploadedVideos(storyboard.uploadedVideos ?? [], [
          { id: videoId, src: mediaUrl, status: "ready", storageObjectId: task.result?.storageObjectId ?? null },
        ]),
      };
    }
    const imageId = task.result?.assetVersionId ?? task.result?.storageObjectId ?? task.taskId;
    return {
      ...storyboard,
      currentImageAssetVersionId: task.result?.assetVersionId ?? storyboard.currentImageAssetVersionId ?? null,
      previewImageUrl: mediaUrl,
      previewUrl: mediaUrl,
      imageStatus: "ready",
      uploadedImages: [
        ...(storyboard.uploadedImages ?? []).filter((item) => item.id !== imageId),
        { id: imageId, src: mediaUrl, status: "ready", storageObjectId: task.result?.storageObjectId ?? null },
      ],
    };
  });
  replaceActiveStoryboards(workbench, storyboards);
}

function generationTaskFailureMessage(task) {
  const apiKeyEnv = String(task?.failure?.apiKeyEnv ?? task?.details?.apiKeyEnv ?? "").trim();
  const displayMessage = String(task?.failure?.displayMessage ?? "").trim();
  if (displayMessage) {
    return apiKeyEnv ? `${displayMessage} 缺失项：${apiKeyEnv}` : displayMessage;
  }
  const failureCode = String(task?.failureCode ?? task?.failure?.failureCode ?? "").trim();
  const finalizeMessage = generationFinalizeFailureMessage(failureCode);
  if (finalizeMessage) {
    return finalizeMessage;
  }
  const providerMessage = String(task?.failure?.providerMessage ?? "").trim();
  if (providerMessage) {
    return providerMessage;
  }
  const providerErrorCode = String(task?.failure?.providerErrorCode ?? "").trim();
  if (providerErrorCode) {
    return providerErrorCode;
  }
  return (
    modelGenerationErrorMessage(task?.failureCode) ||
    String(task?.failureCode ?? task?.failure?.failureCode ?? "任务失败，请稍后重试")
  );
}

function generationTaskNoticePrefix(task) {
  const noticeType = String(task?.failure?.noticeType ?? task?.noticeType ?? "").trim();
  if (noticeType === "manual_review" || noticeType === "admin_action_required") {
    return "需要后台处理：";
  }
  if (noticeType === "warning") {
    return "生成提醒：";
  }
  return "生成失败：";
}

function generationFinalizeFailureMessage(failureCode) {
  return (
    {
      provider_output_persist_failed: "已保存到平台存储，正在等待后台补写资产记录",
      provider_output_upload_failed: "视频已生成，但保存到平台存储失败，积分已返还",
      provider_output_download_failed: "供应商产物下载失败，积分已返还，可在链接未过期时由后台重试保存",
    }[String(failureCode ?? "")] ?? ""
  );
}

function shouldContinueGenerationPolling(workbench, storyboardId, mediaKind) {
  const targetKey = mediaKind === "video" ? "videoGenerationResult" : "imageGenerationResult";
  const currentStatus = resolveWorkflowStatus(
    workbench.ui[targetKey]?.status ??
      workbench.ui[targetKey]?.platform?.workflowStatus ??
      workbench.ui[targetKey]?.workflowStatus,
  );
  if (isGenerationTaskTerminalStatus(currentStatus)) {
    return false;
  }
  const currentTaskId = resolveGenerationTaskIdForConversation(workbench.ui[targetKey]);
  if (currentTaskId && isGenerationTaskPendingStatus(currentStatus)) {
    return true;
  }
  const storyboard = getActiveStoryboards(workbench).find((item) => item.id === storyboardId);
  if (!storyboard) {
    return false;
  }
  if (mediaKind === "video") {
    if (workbench.ui.episodeMediaMode === "lip-sync") {
      return false;
    }
    return !Boolean(storyboard.previewVideo || storyboard.currentVideoAssetVersionId);
  }
  return !Boolean(storyboard.previewImageUrl || storyboard.currentImageAssetVersionId);
}

function dedupeQuickReferenceItems(items = []) {
  const seen = new Set();
  return items.filter((item) => {
    const key = item.assetId ?? item.id;
    if (!key || seen.has(key)) {
      return false;
    }
    seen.add(key);
    return true;
  });
}

function dedupeMentionReferenceItems(items = []) {
  const seen = new Set();
  return items.filter((item) => {
    const key = item.assetId ?? item.id ?? item.token;
    if (!key || seen.has(key)) {
      return false;
    }
    seen.add(key);
    return true;
  });
}

function resolvePromptMentionAssetBuckets(workbench) {
  const importedAssets = workbench.ui.importedAssets ?? {};
  const mediaBuckets = resolvePromptMentionMediaBuckets(workbench);
  const detailAssets =
    workbench.ui.projectDetail?.assetsByType ??
    workbench.state?.projectDetail?.assetsByType ??
    null;
  const contextAssets = resolvePromptMentionContextAssetBuckets(workbench);
  const detailBuckets = detailAssets ? mapProjectDetailAssets(detailAssets, importedAssets) : null;
  return {
    ...importedAssets,
    character: dedupePromptMentionAssetItems([
      ...(importedAssets.character ?? []),
      ...(contextAssets.character ?? []),
      ...(detailBuckets?.character ?? []),
    ]),
    scene: dedupePromptMentionAssetItems([
      ...(importedAssets.scene ?? []),
      ...(contextAssets.scene ?? []),
      ...(detailBuckets?.scene ?? []),
    ]),
    prop: dedupePromptMentionAssetItems([
      ...(importedAssets.prop ?? []),
      ...(contextAssets.prop ?? []),
      ...(detailBuckets?.prop ?? []),
    ]),
    image: mediaBuckets.image,
    audio: mediaBuckets.audio,
    video: mediaBuckets.video,
  };
}

function resolvePromptMentionContextAssetBuckets(workbench) {
  const context = workbench.ui.episodeWorkbenchContext ?? {};
  const assetsByType =
    context.assetsByType ??
    context.assets ??
    context.episodeAssets ??
    context.data?.assetsByType ??
    context.data?.assets ??
    context.data?.episodeAssets ??
    {};
  return {
    character: mapEpisodeAssetContracts(resolvePromptMentionContextAssetList(assetsByType, ["character", "characters", "role", "roles"]), "character"),
    scene: mapEpisodeAssetContracts(resolvePromptMentionContextAssetList(assetsByType, ["scene", "scenes"]), "scene"),
    prop: mapEpisodeAssetContracts(resolvePromptMentionContextAssetList(assetsByType, ["prop", "props"]), "prop"),
  };
}

function resolvePromptMentionContextAssetList(assetsByType, keys = []) {
  for (const key of keys) {
    const value = assetsByType?.[key];
    if (Array.isArray(value)) {
      return value;
    }
    if (Array.isArray(value?.items)) {
      return value.items;
    }
    if (Array.isArray(value?.rows)) {
      return value.rows;
    }
    if (Array.isArray(value?.records)) {
      return value.records;
    }
  }
  return [];
}

function dedupePromptMentionAssetItems(items = []) {
  const seen = new Set();
  return items.filter((item) => {
    const key = String(
      item?.id ??
        item?.assetId ??
        item?.fixedImageUrl ??
        item?.previewUrl ??
        item?.preview ??
        item?.name ??
        "",
    ).trim();
    if (!key || seen.has(key)) {
      return false;
    }
    seen.add(key);
    return true;
  });
}

function resolvePromptMentionMediaBuckets(workbench) {
  const selectedStoryboard = getSelectedStoryboard(
    getActiveStoryboards(workbench),
    workbench.ui.selectedStoryboardId,
  );
  const generationState = isAssetScope(workbench)
    ? (workbench.ui.assetPromptDraft ?? {})
    : (selectedStoryboard?.generationState ?? createEmptyGenerationState());
  const orderedReferences = collectOrderedGenerationReferenceItems(workbench, generationState);
  const lipSyncAudioItems = Array.isArray(workbench.ui.lipSyncAudioItems) ? workbench.ui.lipSyncAudioItems : [];
  const buckets = {
    image: [],
    audio: [],
    video: [],
  };
  [...orderedReferences, ...lipSyncAudioItems].forEach((item, index) => {
    const mediaKind = resolveGenerationReferenceMediaKind(item);
    if (!buckets[mediaKind]) {
      return;
    }
    const number = buckets[mediaKind].length + 1;
    const originalName =
      resolveReferenceOriginalDisplayName(item) ||
      String(
        item?.originalName ??
          item?.assetOriginalName ??
          item?.assetName ??
          item?.matchedAssetName ??
          item?.selectedAssetName ??
          item?.label ??
          item?.name ??
          "",
      ).trim();
    const name = resolvePromptMentionMediaName(mediaKind, number);
    buckets[mediaKind].push({
      ...item,
      id: item?.id ?? item?.assetId ?? `mention-${mediaKind}-${index + 1}`,
      assetId: item?.assetId ?? item?.id ?? null,
      assetKind: mediaKind,
      kind: mediaKind,
      type: mediaKind,
      name,
      label: name,
      originalName,
      mentionAliases: resolvePromptMentionAliases(name, mediaKind, number, originalName),
    });
  });
  return buckets;
}

function resolvePromptMentionMediaName(mediaKind, number) {
  if (mediaKind === "audio") return `音频${number}`;
  if (mediaKind === "video") return `视频${number}`;
  return `图${number}`;
}

function resolvePromptMentionAliases(name, mediaKind, number = null, originalName = "") {
  const aliases = new Set();
  for (const [index, value] of [name, originalName].entries()) {
    const normalizedName = String(value ?? "").trim();
    if (!normalizedName) {
      continue;
    }
    aliases.add(normalizedName);
    const imageMatch = /^图(?:片)?\s*(\d+)$/u.exec(normalizedName);
    if (index === 0 && imageMatch) {
      aliases.add(`图${imageMatch[1]}`);
      aliases.add(`图片${imageMatch[1]}`);
    }
  }
  if (mediaKind === "image" && Number.isFinite(Number(number)) && Number(number) > 0) {
    aliases.add(`图${number}`);
    aliases.add(`图片${number}`);
  }
  return [...aliases];
}

function collectPromptMentionAssets(workbench) {
  const buckets = resolvePromptMentionAssetBuckets(workbench);
  return [
    ...(buckets.image ?? []).map((item) => ({ ...item, assetKind: "image" })),
    ...(buckets.audio ?? []).map((item) => ({ ...item, assetKind: "audio" })),
    ...(buckets.video ?? []).map((item) => ({ ...item, assetKind: "video" })),
    ...(buckets.character ?? []).map((item) => ({ ...item, assetKind: "character" })),
    ...(buckets.scene ?? []).map((item) => ({ ...item, assetKind: "scene" })),
    ...(buckets.prop ?? []).map((item) => ({ ...item, assetKind: "prop" })),
  ];
}

function findPromptMentionSuggestionById(workbench, assetKind, assetId) {
  const id = String(assetId ?? "").trim();
  if (!id) {
    return null;
  }
  return (workbench.ui.promptMentionSuggestions ?? []).find((item) => {
    const itemKind = String(item?.assetKind ?? item?.kind ?? "").trim();
    return (
      (!assetKind || itemKind === String(assetKind)) &&
      [item?.id, item?.assetId].map((value) => String(value ?? "").trim()).includes(id)
    );
  }) ?? null;
}

function doesPromptMentionMatchAssetName(asset, mentionName) {
  const normalizedMention = normalizeAssetReferenceLookupName(mentionName);
  if (!normalizedMention) {
    return false;
  }
  return [asset?.name, asset?.label, ...(asset?.mentionAliases ?? [])]
    .map((value) => normalizeAssetReferenceLookupName(value))
    .filter(Boolean)
    .some((name) => name === normalizedMention);
}

function resolvePromptMentionCurrentMediaAlias(workbench, asset, assetKind = null) {
  if (!asset || typeof asset !== "object") {
    return null;
  }
  const buckets = resolvePromptMentionMediaBuckets(workbench);
  const mediaKind = resolvePromptMentionAssetMediaKind(asset, assetKind);
  const sameKindMatch = (buckets[mediaKind] ?? []).find((item) => isPromptMentionSameMediaAsset(item, asset)) ?? null;
  if (sameKindMatch) {
    return sameKindMatch;
  }
  return [...(buckets.image ?? []), ...(buckets.audio ?? []), ...(buckets.video ?? [])]
    .find((item) => resolveGenerationReferenceMediaKind(item) === mediaKind && isPromptMentionSameMediaAsset(item, asset)) ?? null;
}

function resolvePromptMentionAssetMediaKind(asset, assetKind = null) {
  const normalizedKind = String(assetKind ?? asset?.assetKind ?? asset?.kind ?? asset?.type ?? "").trim();
  if (normalizedKind === "audio" || normalizedKind === "video" || normalizedKind === "image") {
    return normalizedKind;
  }
  if (normalizedKind === "character" || normalizedKind === "scene" || normalizedKind === "prop") {
    return "image";
  }
  return resolveGenerationReferenceMediaKind(asset);
}

function isPromptMentionSameMediaAsset(reference, asset) {
  const referenceIds = [
    reference?.id,
    reference?.assetId,
    reference?.assetVersionId,
    reference?.storageObjectId,
    reference?.fixedImageFileId,
  ].map((value) => String(value ?? "").trim()).filter(Boolean);
  const assetIds = [
    asset?.id,
    asset?.assetId,
    asset?.assetVersionId,
    asset?.storageObjectId,
    asset?.fixedImageFileId,
  ].map((value) => String(value ?? "").trim()).filter(Boolean);
  if (referenceIds.some((id) => assetIds.includes(id))) {
    return true;
  }
  const referenceUrl = String(resolveEpisodeAssetPreviewUrl(reference) ?? resolveGenerationReferenceUrl(reference) ?? "").trim();
  const assetUrl = String(resolveEpisodeAssetPreviewUrl(asset) ?? resolveGenerationReferenceUrl(asset) ?? "").trim();
  if (referenceUrl && assetUrl && referenceUrl === assetUrl) {
    return true;
  }
  const referenceNames = [
    reference?.name,
    reference?.label,
    reference?.originalName,
    reference?.assetOriginalName,
    reference?.assetName,
    ...(reference?.mentionAliases ?? []),
  ].map((value) => normalizeAssetReferenceLookupName(value)).filter(Boolean);
  const assetNames = [
    asset?.name,
    asset?.label,
    asset?.originalName,
    asset?.assetOriginalName,
    asset?.assetName,
    ...(asset?.mentionAliases ?? []),
  ].map((value) => normalizeAssetReferenceLookupName(value)).filter(Boolean);
  return referenceNames.some((name) => assetNames.includes(name));
}

export function updatePromptMentionState(workbench, value, selectionStart) {
  const text = String(value ?? "");
  const cursor = Math.max(0, Number(selectionStart ?? text.length));
  if ((workbench.ui.museScopeMode ?? "storyboard") !== "storyboard") {
    clearPromptMentionUi(workbench);
    return;
  }
  const completeMentionAsset = resolveCompletePromptMentionAsset(workbench, text, cursor);
  if (completeMentionAsset) {
    workbench.ui.promptMentionMenuOpen = false;
    workbench.ui.promptMentionQuery = "";
    workbench.ui.promptMentionSuggestions = [];
    workbench.ui.promptMentionPreviewOpen = true;
    workbench.ui.promptMentionPreviewAsset = completeMentionAsset;
    return;
  }
  const mentionDraft = resolvePromptMentionDraftAtCursor(text, cursor);
  if (mentionDraft) {
    const query = String(mentionDraft.query ?? "").trim().toLowerCase();
    const suggestions = collectPromptMentionAssets(workbench)
      .filter((item) => {
        if (!query) return true;
        return [item.name, item.label, item.description, ...(item.mentionAliases ?? [])]
          .map((entry) => String(entry ?? "").toLowerCase())
          .some((entry) => entry.includes(query));
      });

    workbench.ui.promptMentionMenuOpen = suggestions.length > 0;
    workbench.ui.promptMentionQuery = query;
    workbench.ui.promptMentionSuggestions = suggestions;
    workbench.ui.promptMentionPreviewOpen = false;
    workbench.ui.promptMentionPreviewAsset = null;
    return;
  }
  clearPromptMentionUi(workbench);
}

function resolvePromptMentionDraftAtCursor(text, cursor) {
  const value = String(text ?? "");
  const caret = Math.max(0, Math.min(value.length, Number(cursor ?? value.length)));
  const beforeCursor = value.slice(0, caret);
  const closedBracketMatch = /【@([^】]*)】$/.exec(beforeCursor);
  if (closedBracketMatch && !String(closedBracketMatch[1] ?? "").trim()) {
    return {
      start: beforeCursor.length - closedBracketMatch[0].length,
      end: caret,
      query: closedBracketMatch[1] ?? "",
    };
  }
  const openBracketMatch = /【@([^】]*)$/.exec(beforeCursor);
  if (openBracketMatch) {
    return {
      start: beforeCursor.length - openBracketMatch[0].length,
      end: value.charAt(caret) === "】" ? caret + 1 : caret,
      query: openBracketMatch[1] ?? "",
    };
  }
  const plainMentionMatch = /@([^\s【】]*)$/.exec(beforeCursor);
  if (!plainMentionMatch) {
    return null;
  }
  const atIndex = beforeCursor.lastIndexOf("@");
  if (atIndex < 0) {
    return null;
  }
  return {
    start: atIndex,
    end: caret,
    query: plainMentionMatch[1] ?? "",
  };
}

function clearPromptMentionUi(workbench) {
  workbench.ui.promptMentionMenuOpen = false;
  workbench.ui.promptMentionQuery = "";
  workbench.ui.promptMentionSuggestions = [];
  workbench.ui.promptMentionPreviewOpen = false;
  workbench.ui.promptMentionPreviewAsset = null;
}

function snapshotPromptMentionUi(workbench) {
  return {
    menuOpen: Boolean(workbench.ui.promptMentionMenuOpen),
    query: String(workbench.ui.promptMentionQuery ?? ""),
    suggestionIds: (workbench.ui.promptMentionSuggestions ?? [])
      .map((item) => String(item?.id ?? item?.assetId ?? item?.name ?? ""))
      .join("|"),
    previewOpen: Boolean(workbench.ui.promptMentionPreviewOpen),
    previewAssetId: String(
      workbench.ui.promptMentionPreviewAsset?.id ??
      workbench.ui.promptMentionPreviewAsset?.assetId ??
      workbench.ui.promptMentionPreviewAsset?.name ??
      "",
    ),
  };
}

function hasPromptMentionUiChanged(previous, workbench) {
  const next = snapshotPromptMentionUi(workbench);
  return (
    previous.menuOpen !== next.menuOpen ||
    previous.query !== next.query ||
    previous.suggestionIds !== next.suggestionIds ||
    previous.previewOpen !== next.previewOpen ||
    previous.previewAssetId !== next.previewAssetId
  );
}

function syncPromptMentionAfterSelection(workbench, textarea) {
  if (!textarea?.matches?.("#video-prompt-input")) {
    return;
  }
  const selectionStart = Number(textarea.selectionStart ?? textarea.value.length);
  const selectionEnd = Number(textarea.selectionEnd ?? selectionStart);
  const scrollTop = Number(textarea.scrollTop ?? 0);
  const beforeMentionUi = snapshotPromptMentionUi(workbench);
  updatePromptMentionState(workbench, textarea.value, selectionStart);
  if (!workbench.ui.promptMentionPreviewOpen) {
    removePromptMentionPreviewDom(workbench);
  }
  if (!hasPromptMentionUiChanged(beforeMentionUi, workbench)) {
    positionPromptMentionSurface(workbench, textarea);
    return;
  }
  syncPromptMentionSurfaceOnly(workbench, textarea);
  textarea.focus();
  textarea.setSelectionRange(selectionStart, selectionEnd);
  textarea.scrollTop = scrollTop;
  positionPromptMentionSurface(workbench, textarea);
}

function syncPromptMentionSurfaceOnly(workbench, textarea = null) {
  const input = textarea ?? workbench?.root?.querySelector?.("#video-prompt-input");
  const prompt = input?.closest?.(".episode-replica-prompt") ?? null;
  const anchor = prompt?.querySelector?.(".episode-replica-textarea") ?? null;
  if (!prompt || !anchor) {
    renderEpisodeWorkbenchPromptDockOnly(workbench);
    return false;
  }
  prompt.querySelectorAll(".episode-replica-mention-menu, .episode-replica-mention-preview[data-floating='caret']").forEach((node) => node.remove());
  let insertAfter = anchor;
  if (workbench.ui.promptMentionMenuOpen && (workbench.ui.promptMentionSuggestions ?? []).length) {
    const wrapper = document.createElement("div");
    wrapper.innerHTML = renderPromptMentionMenuHtml(workbench.ui.promptMentionSuggestions ?? []);
    const menu = wrapper.firstElementChild;
    if (menu) {
      insertAfter.after(menu);
      insertAfter = menu;
    }
  }
  if (workbench.ui.promptMentionPreviewOpen && workbench.ui.promptMentionPreviewAsset) {
    const wrapper = document.createElement("div");
    wrapper.innerHTML = renderPromptMentionPreviewHtml(workbench.ui.promptMentionPreviewAsset);
    const preview = wrapper.firstElementChild;
    if (preview) {
      insertAfter.after(preview);
    }
  }
  return true;
}

function renderPromptMentionMenuHtml(suggestions = []) {
  return `<div class="episode-replica-mention-menu">
    ${suggestions.map((item) => {
      const previewUrl = resolveEpisodeAssetPreviewUrl(item);
      const itemName = item?.name ?? item?.label ?? "素材";
      const itemKind = item?.assetKind ?? item?.kind ?? "character";
      return `
        <button
          class="episode-replica-mention-option"
          type="button"
          data-action="select-prompt-mention"
          data-asset-id="${escapeHtmlAttribute(item?.id ?? "")}"
          data-asset-kind="${escapeHtmlAttribute(itemKind)}"
        >
          <span class="episode-replica-mention-thumb">
            ${previewUrl ? `<img src="${escapeHtmlAttribute(previewUrl)}" alt="" />` : renderPromptMentionPlaceholder(itemKind, itemName)}
          </span>
          <span class="episode-replica-mention-copy">
            <strong>${escapeHtmlText(itemName)}</strong>
            <small>${escapeHtmlText(resolvePromptMentionAssetLabel(itemKind))}</small>
          </span>
        </button>
      `;
    }).join("")}
  </div>`;
}

function renderPromptMentionPreviewHtml(asset) {
  const previewUrl = resolveEpisodeAssetPreviewUrl(asset);
  const name = asset?.name ?? asset?.label ?? "素材";
  return `
    <div class="episode-replica-mention-preview" data-floating="caret" role="status">
      <span class="episode-replica-mention-preview-thumb">
        ${previewUrl ? `<img src="${escapeHtmlAttribute(previewUrl)}" alt="" />` : renderPromptMentionPlaceholder(asset?.assetKind ?? asset?.kind ?? "character", name)}
      </span>
      <strong>${escapeHtmlText(name)}</strong>
    </div>
  `;
}

function renderPromptMentionPlaceholder(kind, label) {
  return `
    <span class="episode-replica-quick-art episode-replica-quick-art-${escapeHtmlAttribute(kind)}">
      <i></i><b>${escapeHtmlText(String(label || "素材").slice(0, 4))}</b>
    </span>
  `;
}

function resolvePromptMentionAssetLabel(kind) {
  return ({
    character: "角色",
    scene: "场景",
    prop: "道具",
    image: "图片",
    audio: "音频",
    video: "视频",
  })[kind] ?? "素材";
}

function escapeHtmlText(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

function escapeHtmlAttribute(value) {
  return escapeHtmlText(value).replace(/"/g, "&quot;");
}

function dismissPromptMentionPreview(workbench) {
  if (!workbench?.ui) {
    return;
  }
  workbench.ui.promptMentionPreviewOpen = false;
  workbench.ui.promptMentionPreviewAsset = null;
  workbench.ui.promptMentionMenuOpen = false;
  workbench.ui.promptMentionQuery = "";
  workbench.ui.promptMentionSuggestions = [];
  removePromptMentionPreviewDom(workbench);
}

function removePromptMentionPreviewDom(workbench) {
  workbench?.root
    ?.querySelectorAll?.(".episode-replica-mention-menu, .episode-replica-mention-preview[data-floating='caret']")
    ?.forEach((node) => node.remove());
}

function positionPromptMentionSurface(workbench, textarea = null) {
  positionPromptMentionMenu(workbench, textarea);
  positionPromptMentionPreview(workbench, textarea);
}

function positionPromptMentionMenu(workbench, textarea = null) {
  const root = workbench?.root ?? null;
  const input = textarea ?? root?.querySelector?.("#video-prompt-input");
  const prompt = input?.closest?.(".episode-replica-prompt") ?? null;
  const menu = prompt?.querySelector?.(".episode-replica-mention-menu");
  if (!prompt || !menu || !input) {
    return;
  }
  const caret = resolveTextareaCaretViewportPosition(input, Number(input.selectionStart ?? 0));
  const promptRect = prompt.getBoundingClientRect();
  const inputRect = input.getBoundingClientRect();
  menu.style.removeProperty("max-height");
  const menuRect = menu.getBoundingClientRect();
  const gap = 8;
  const viewportPadding = 12;
  const minVisibleMenuHeight = 96;
  const viewportWidth = Number(globalThis.window?.innerWidth ?? 0);
  const viewportHeight = Number(globalThis.window?.innerHeight ?? 0);
  const fallbackX = inputRect.left + 12;
  const fallbackY = inputRect.top + 28;
  let viewportX = Number.isFinite(caret?.left) ? caret.left : fallbackX;
  let viewportY = Number.isFinite(caret?.bottom) ? caret.bottom + gap : fallbackY;
  if (viewportWidth > 0 && viewportX + menuRect.width > viewportWidth - viewportPadding) {
    viewportX = Math.max(viewportPadding, viewportX - menuRect.width + 18);
  }
  if (viewportHeight > 0) {
    const availableBelow = viewportHeight - viewportY - viewportPadding;
    const caretTop = Number.isFinite(caret?.top) ? caret.top : viewportY;
    const availableAbove = Math.max(0, caretTop - viewportPadding - gap);
    if (availableBelow >= minVisibleMenuHeight || availableBelow >= availableAbove) {
      const nextMaxHeight = Math.max(minVisibleMenuHeight, Math.min(menuRect.height, availableBelow));
      menu.style.setProperty("max-height", `${nextMaxHeight}px`);
    } else {
      const nextMaxHeight = Math.max(minVisibleMenuHeight, Math.min(menuRect.height, availableAbove));
      viewportY = Math.max(viewportPadding, caretTop - nextMaxHeight - gap);
      menu.style.setProperty("max-height", `${nextMaxHeight}px`);
    }
  }
  const x = viewportX - promptRect.left;
  const y = viewportY - promptRect.top;
  menu.style.setProperty("--prompt-mention-menu-x", `${x}px`);
  menu.style.setProperty("--prompt-mention-menu-y", `${y}px`);
}

function positionPromptMentionPreview(workbench, textarea = null) {
  const root = workbench?.root ?? null;
  const input = textarea ?? root?.querySelector?.("#video-prompt-input");
  const prompt = input?.closest?.(".episode-replica-prompt") ?? null;
  const preview = prompt?.querySelector?.(".episode-replica-mention-preview[data-floating='caret']");
  if (!prompt || !preview || !input) {
    return;
  }
  const selectionStart = Number(input.selectionStart ?? 0);
  const mentionToken = resolvePromptMentionTokenAtCursor(String(input.value ?? ""), selectionStart);
  const anchorIndex = mentionToken?.end ?? selectionStart;
  const caret = resolveTextareaCaretViewportPosition(input, anchorIndex);
  const promptRect = prompt.getBoundingClientRect();
  const inputRect = input.getBoundingClientRect();
  const previewRect = preview.getBoundingClientRect();
  const inputScrollTop = Math.max(0, Number(input.scrollTop ?? 0));
  const gap = 6;
  const viewportPadding = 12;
  const viewportWidth = Number(globalThis.window?.innerWidth ?? 0);
  const viewportHeight = Number(globalThis.window?.innerHeight ?? 0);
  const fallbackX = inputRect.left + 12;
  const fallbackY = inputRect.top + 12;
  const caretTop = Number.isFinite(caret?.top) ? caret.top + inputScrollTop : null;
  const caretBottom = Number.isFinite(caret?.bottom) ? caret.bottom + inputScrollTop : null;
  let viewportX = Number.isFinite(caret?.left) ? caret.left + gap : fallbackX;
  let viewportY = Number.isFinite(caretTop) ? caretTop + ((caret?.lineHeight ?? previewRect.height) - previewRect.height) / 2 : fallbackY;
  if (viewportWidth > 0 && viewportX + previewRect.width > viewportWidth - viewportPadding) {
    viewportX = Math.max(viewportPadding, viewportWidth - previewRect.width - viewportPadding);
    viewportY = Number.isFinite(caretBottom) ? caretBottom + gap : viewportY;
  }
  const minY = Math.max(viewportPadding, inputRect.top + 6);
  const maxVisibleY = viewportHeight > 0
    ? Math.min(inputRect.bottom - previewRect.height - 6, viewportHeight - previewRect.height - viewportPadding)
    : inputRect.bottom - previewRect.height - 6;
  const maxY = Math.max(minY, maxVisibleY);
  viewportX = Math.max(viewportPadding, viewportX);
  viewportY = Math.min(Math.max(minY, viewportY), maxY);
  const x = viewportX - promptRect.left;
  const y = viewportY - promptRect.top;
  preview.style.setProperty("--prompt-mention-x", `${x}px`);
  preview.style.setProperty("--prompt-mention-y", `${y}px`);
}

function resolveTextareaCaretViewportPosition(textarea, selectionIndex = null) {
  if (!textarea || typeof document === "undefined") {
    return null;
  }
  const selectionStart = Number(selectionIndex ?? textarea.selectionStart ?? String(textarea.value ?? "").length);
  const value = String(textarea.value ?? "");
  const beforeCaret = value.slice(0, Math.max(0, selectionStart));
  const mirror = document.createElement("div");
  const caretMarker = document.createElement("span");
  const style = window.getComputedStyle(textarea);
  const mirroredProperties = [
    "boxSizing",
    "width",
    "height",
    "paddingTop",
    "paddingRight",
    "paddingBottom",
    "paddingLeft",
    "borderTopWidth",
    "borderRightWidth",
    "borderBottomWidth",
    "borderLeftWidth",
    "fontFamily",
    "fontSize",
    "fontWeight",
    "fontStyle",
    "letterSpacing",
    "lineHeight",
    "textTransform",
    "textAlign",
    "wordSpacing",
    "tabSize",
  ];
  mirroredProperties.forEach((property) => {
    mirror.style[property] = style[property];
  });
  mirror.style.position = "fixed";
  mirror.style.left = "-9999px";
  mirror.style.top = "0";
  mirror.style.whiteSpace = "pre-wrap";
  mirror.style.overflowWrap = "break-word";
  mirror.style.visibility = "hidden";
  mirror.style.overflow = "hidden";
  mirror.textContent = beforeCaret || " ";
  caretMarker.textContent = "\u200b";
  mirror.append(caretMarker);
  document.body.append(mirror);
  mirror.scrollTop = textarea.scrollTop;
  const textareaRect = textarea.getBoundingClientRect();
  const mirrorRect = mirror.getBoundingClientRect();
  const markerRect = caretMarker.getBoundingClientRect();
  const left = textareaRect.left + markerRect.left - mirrorRect.left;
  const top = textareaRect.top + markerRect.top - mirrorRect.top - textarea.scrollTop;
  const lineHeight = Number.parseFloat(style.lineHeight) || Number.parseFloat(style.fontSize) || 16;
  mirror.remove();
  return {
    left,
    top,
    bottom: top + lineHeight,
    lineHeight,
  };
}

function resolveCompletePromptMentionAsset(workbench, textOrBeforeCursor, cursor = null) {
  const token = cursor == null
    ? resolvePromptMentionTokenAtCursor(String(textOrBeforeCursor ?? ""), String(textOrBeforeCursor ?? "").length)
    : resolvePromptMentionTokenAtCursor(String(textOrBeforeCursor ?? ""), cursor);
  const mentionName = String(token?.name ?? "").trim();
  if (!mentionName) {
    return null;
  }
  const matched = collectPromptMentionAssets(workbench).find((item) => doesPromptMentionMatchAssetName(item, mentionName));
  if (!matched) {
    return null;
  }
  return {
    ...matched,
    name: matched.name ?? matched.label ?? mentionName,
    previewUrl:
      matched.fixedImageUrl ??
      matched.previewUrl ??
      matched.preview ??
      matched.sourceUrl ??
      matched.latestVersion?.previewUrl ??
      matched.latestVersion?.metadata?.previewUrl ??
      null,
  };
}

function resolvePromptMentionTokenAtCursor(text, cursor) {
  const value = String(text ?? "");
  const caret = Math.max(0, Math.min(value.length, Number(cursor ?? value.length)));
  const tokenPattern = /【@([^】]+)】/g;
  let match;
  while ((match = tokenPattern.exec(value)) !== null) {
    const start = match.index;
    const end = start + match[0].length;
    if (caret >= start && caret <= end) {
      return {
        start,
        end,
        name: String(match[1] ?? "").trim(),
      };
    }
  }
  return null;
}

function insertEpisodeAssetMention(workbench, asset, assetKind) {
  const textarea = workbench.root?.querySelector?.("#video-prompt-input");
  const currentPrompt = String(workbench.ui.prompt ?? "");
  const cursor = Number(textarea?.selectionStart ?? currentPrompt.length);
  const currentMediaAlias = resolvePromptMentionCurrentMediaAlias(workbench, asset, assetKind);
  const mentionName = currentMediaAlias?.name ?? asset?.name ?? "素材";
  const nextToken = `【@${mentionName}】`;
  const mentionDraft = resolvePromptMentionDraftAtCursor(currentPrompt, cursor);
  const insertionStart = mentionDraft
    ? mentionDraft.start
    : currentPrompt.length + (currentPrompt.trim() ? 1 : 0);
  const selectionAfterInsert = insertionStart + nextToken.length;
  const promptInputState = {
    selectionStart: selectionAfterInsert,
    selectionEnd: selectionAfterInsert,
    scrollTop: Number(textarea?.scrollTop ?? 0),
    shouldFocus: true,
  };
  const nextPrompt = mentionDraft
    ? `${currentPrompt.slice(0, mentionDraft.start)}${nextToken}${currentPrompt.slice(mentionDraft.end)}`
    : `${currentPrompt}${currentPrompt.trim() ? "\n" : ""}${nextToken}`;
  setCurrentScopePrompt(workbench, nextPrompt);

  const selectedStoryboard = getSelectedStoryboard(
    getActiveStoryboards(workbench),
    workbench.ui.selectedStoryboardId,
  );
  const mentionMediaKind = resolvePromptMentionAssetMediaKind(asset, assetKind);
  const imageReference = mentionMediaKind === "audio"
    ? null
    : buildEpisodeAssetMentionImageReference(asset, assetKind);
  const nextMentionReference = {
    id: `mention-ref:${assetKind}:${asset?.id ?? Date.now()}`,
    assetId: asset?.id ?? null,
    kind: assetKind,
    name: mentionName,
    token: nextToken,
    description: asset?.description ?? "",
    preview: resolveEpisodeAssetPreviewUrl(asset),
  };
  if (selectedStoryboard) {
    updateStoryboardGenerationState(workbench, selectedStoryboard.id, (generationState) => {
      const nextQuickReferenceItems = imageReference
        ? dedupeQuickReferenceItems([
            ...(generationState.quickReferenceItems ?? []),
            imageReference,
          ])
        : (generationState.quickReferenceItems ?? []);
      const nextState = {
        ...generationState,
        quickReferenceItems: nextQuickReferenceItems,
      };
      const orderedAlias = imageReference
        ? resolvePromptMentionOrderedImageAlias(workbench, nextState, imageReference)
        : "";
      const mentionReference = orderedAlias
        ? {
            ...nextMentionReference,
            name: orderedAlias,
            token: `【@${orderedAlias}】`,
          }
        : nextMentionReference;
      return {
        ...nextState,
        mentionReferences: dedupeMentionReferenceItems([
          ...(generationState.mentionReferences ?? []),
          mentionReference,
        ]),
      };
    });
    const syncedStoryboard = getSelectedStoryboard(
      getActiveStoryboards(workbench),
      selectedStoryboard.id,
    );
    normalizeCurrentVideoAssetTablePromptByFileOrder(workbench, syncedStoryboard);
    syncStoryboardQuickReferencesToVideoGenerationState(
      workbench,
      selectedStoryboard.id,
      syncedStoryboard?.generationState?.quickReferenceItems ?? [],
    );
    appendStoryboardMentionAudioAttachments(workbench, nextPrompt);
    if (mentionMediaKind !== "audio") {
      appendEpisodeAssetMentionAudioAttachment(workbench, asset, assetKind);
    }
    return { promptInputState };
  }
  if (imageReference) {
    const assetPromptDraft = workbench.ui.assetPromptDraft ?? {};
    const nextQuickReferenceItems = dedupeQuickReferenceItems([
      ...(assetPromptDraft.quickReferenceItems ?? []),
      imageReference,
    ]);
    const nextDraft = {
      ...assetPromptDraft,
      quickReferenceItems: nextQuickReferenceItems,
    };
    const orderedAlias = resolvePromptMentionOrderedImageAlias(workbench, nextDraft, imageReference);
    const mentionReference = orderedAlias
      ? {
          ...nextMentionReference,
          name: orderedAlias,
          token: `【@${orderedAlias}】`,
        }
      : nextMentionReference;
    workbench.ui.assetPromptDraft = {
      ...nextDraft,
      mentionReferences: dedupeMentionReferenceItems([
        ...(assetPromptDraft.mentionReferences ?? []),
        mentionReference,
      ]),
    };
    setCurrentScopePrompt(
      workbench,
      normalizePromptByImageReferenceOrder(workbench, getCurrentScopePrompt(workbench), workbench.ui.assetPromptDraft),
    );
  }
  if (mentionMediaKind !== "audio") {
    appendEpisodeAssetMentionAudioAttachment(workbench, asset, assetKind);
  }
  return { promptInputState };
}

function resolvePromptMentionOrderedImageAlias(workbench, generationState = {}, reference = null) {
  if (!reference) {
    return "";
  }
  const orderedImages = filterOrderedGenerationReferences(
    enrichGenerationReferenceNamesFromAssets(
      workbench,
      collectOrderedGenerationReferenceItems(workbench, generationState),
    ),
    "image",
  );
  const imageIndex = orderedImages.findIndex((item) => isPromptMentionSameMediaAsset(item, reference));
  return imageIndex >= 0 ? `图${imageIndex + 1}` : "";
}

function buildEpisodeAssetMentionImageReference(asset, assetKind) {
  const previewUrl = resolveEpisodeAssetPreviewUrl(asset);
  if (!previewUrl) {
    return null;
  }
  const originalName = resolveReferenceOriginalDisplayName(asset);
  return {
    id: `mention-ref-image:${assetKind}:${asset?.id ?? asset?.assetId ?? asset?.name ?? Date.now()}`,
    assetId: asset?.id ?? asset?.assetId ?? null,
    kind: "image",
    type: "image",
    role: assetKind,
    name: asset?.name ?? asset?.label ?? "引用素材",
    ...(originalName ? { originalName, assetName: originalName } : {}),
    description: asset?.description ?? "",
    preview: previewUrl,
    previewUrl,
    url: previewUrl,
    src: previewUrl,
    fromQuickReference: true,
    voiceId: asset?.voiceId ?? null,
    voiceName: asset?.voiceName ?? "",
    voiceSource: asset?.voiceSource ?? inferEpisodeVoiceSource(asset),
  };
}

function appendEpisodeAssetMentionAudioAttachment(workbench, asset, assetKind) {
  const audioUrl = resolveImportedProjectAudioUrl(asset);
  if (!audioUrl) {
    return;
  }
  const name = asset?.name ?? asset?.label ?? "素材";
  const attachment = {
    id: `quick-mention-audio-file:${assetKind}:${asset?.id ?? asset?.assetId ?? name}`,
    type: "audio",
    kind: "audio",
    name: `${name} 音频`,
    summary: name,
    audioUrl,
    url: audioUrl,
    voiceId: asset?.voiceId ?? null,
    voiceName: asset?.voiceName ?? "",
    voiceSource: asset?.voiceSource ?? inferEpisodeVoiceSource(asset),
  };
  const currentAttachments = Array.isArray(workbench.ui.episodeWorkbenchAttachments)
    ? workbench.ui.episodeWorkbenchAttachments
    : [];
  if (!currentAttachments.some((item) => item?.id === attachment.id)) {
    workbench.ui.episodeWorkbenchAttachments = [attachment, ...currentAttachments];
  }
  const currentSelected = new Set(workbench.ui.episodeWorkbenchSelectedAttachmentIds ?? []);
  currentSelected.add(attachment.id);
  workbench.ui.episodeWorkbenchSelectedAttachmentIds = [...currentSelected];
}

function resolveWorkflowStatus(status) {
  const normalized = String(status ?? "").toLowerCase();
  if (!normalized) {
    return "running";
  }
  if (normalized === "succeeded") {
    return "completed";
  }
  return normalized;
}

function resolveGenerationTaskDisplayStatus(taskOrResult, fallbackStatus = null) {
  const ownStatus = resolveWorkflowStatus(
    taskOrResult?.status ??
      taskOrResult?.generationStatus ??
      fallbackStatus,
  );
  if (isGenerationTaskTerminalStatus(ownStatus)) {
    return ownStatus;
  }
  const workflowStatus = resolveWorkflowStatus(
    taskOrResult?.workflowStatus ??
      taskOrResult?.platform?.workflowStatus ??
      fallbackStatus,
  );
  return isGenerationTaskTerminalStatus(workflowStatus) ? workflowStatus : ownStatus;
}

function syncEpisodeStoryboardMap(currentMap, primaryStoryboards, customEpisodes = []) {
  const primaryByEpisodeId = new Map();
  for (const storyboard of primaryStoryboards ?? []) {
    const episodeId = storyboard.episodeId ?? "episode-primary";
    const bucket = primaryByEpisodeId.get(episodeId) ?? [];
    bucket.push(storyboard);
    primaryByEpisodeId.set(episodeId, bucket);
  }

  const nextMap = {
    ...(currentMap ?? {}),
  };
  if ((primaryStoryboards ?? []).some((storyboard) => !storyboard?.episodeId)) {
    nextMap["episode-primary"] = primaryStoryboards.filter((storyboard) => !storyboard?.episodeId);
  } else {
    delete nextMap["episode-primary"];
  }

  for (const episode of customEpisodes) {
    const latestStoryboards = primaryByEpisodeId.get(episode.id);
    if (Array.isArray(latestStoryboards) && latestStoryboards.length > 0) {
      nextMap[episode.id] = syncStoryboards(nextMap[episode.id] ?? [], latestStoryboards);
      continue;
    }

    if (!Array.isArray(nextMap[episode.id])) {
      nextMap[episode.id] = [];
    }
  }

  return nextMap;
}

function removeLocalPrimaryEpisode(workbench) {
  workbench.ui.storyboards = [];
  workbench.state = {
    ...(workbench.state ?? {}),
    shots: (workbench.state?.shots ?? []).filter((shot) => shot?.episodeId),
    projectDetail: workbench.state?.projectDetail
      ? {
          ...workbench.state.projectDetail,
          shots: (workbench.state.projectDetail.shots ?? []).filter((shot) => shot?.episodeId),
          episodes: (workbench.state.projectDetail.episodes ?? []).filter(
            (episode) => episode?.id !== "episode-primary",
          ),
        }
      : workbench.state?.projectDetail,
  };
  workbench.ui.projectDetail = workbench.state.projectDetail ?? workbench.ui.projectDetail;
  workbench.ui.customEpisodes = getDetailEpisodes(workbench.state);
  workbench.ui.episodeStoryboardMap = {
    ...(workbench.ui.episodeStoryboardMap ?? {}),
  };
  workbench.ui.episodeStoryboardPaginationMap = {
    ...(workbench.ui.episodeStoryboardPaginationMap ?? {}),
  };
  delete workbench.ui.episodeStoryboardMap["episode-primary"];
  delete workbench.ui.episodeStoryboardPaginationMap["episode-primary"];
}

function getActiveStoryboards(workbench, primaryStoryboards = workbench.ui.storyboards) {
  if (workbench.ui.projectPanelMode !== "episode-workbench") {
    return primaryStoryboards;
  }

  return getEpisodeStoryboards(workbench, workbench.ui.selectedEpisodeId, primaryStoryboards);
}

function getEpisodeStoryboards(
  workbench,
  episodeId = workbench.ui.selectedEpisodeId,
  primaryStoryboards = workbench.ui.storyboards,
) {
  if (!episodeId || episodeId === "episode-primary") {
    return primaryStoryboards;
  }

  return workbench.ui.episodeStoryboardMap?.[episodeId] ?? [];
}

function getEpisodeStoryboardPagination(
  workbench,
  episodeId = workbench.ui.selectedEpisodeId,
  fallbackStoryboards = getEpisodeStoryboards(workbench, episodeId),
) {
  const stored = workbench.ui.episodeStoryboardPaginationMap?.[episodeId];
  if (stored && typeof stored === "object") {
    const pageSize = normalizeStoryboardWorkbenchPageSize(stored.pageSize ?? workbench.ui.storyboardPageSize);
    const total = Math.max(0, Math.floor(Number(stored.total ?? fallbackStoryboards.length ?? 0)) || 0);
    const totalPages = Math.max(1, Math.floor(Number(stored.totalPages ?? Math.ceil(total / pageSize) ?? 1)) || 1);
    return {
      mode: String(stored.mode ?? "").trim() === "server" ? "server" : "local",
      page: clampStoryboardWorkbenchPage(stored.page ?? workbench.ui.storyboardPage ?? 1, totalPages),
      pageSize,
      total,
      totalPages,
      hasNext: Boolean(stored.hasNext ?? false),
    };
  }
  const pageSize = normalizeStoryboardWorkbenchPageSize(workbench.ui.storyboardPageSize);
  const total = Array.isArray(fallbackStoryboards) ? fallbackStoryboards.length : 0;
  const totalPages = Math.max(1, Math.ceil(total / pageSize));
  return {
    mode: "local",
    page: clampStoryboardWorkbenchPage(workbench.ui.storyboardPage ?? 1, totalPages),
    pageSize,
    total,
    totalPages,
    hasNext: total > pageSize,
  };
}

function normalizeStoryboardWorkbenchPageSize(value) {
  return Number(value) === 10 ? 10 : 10;
}

function clampStoryboardWorkbenchPage(value, totalPages) {
  const page = Number(value);
  if (!Number.isFinite(page)) {
    return 1;
  }
  return Math.min(Math.max(Math.trunc(page), 1), Math.max(1, totalPages));
}

function syncStoryboardPaginationForSelection(workbench) {
  const pagination = getEpisodeStoryboardPagination(workbench);
  if (pagination.mode === "server") {
    workbench.ui.storyboardPage = clampStoryboardWorkbenchPage(pagination.page, pagination.totalPages);
    return;
  }
  const storyboards = getActiveStoryboards(workbench);
  const selectedIndex = storyboards.findIndex((item) => item.id === workbench.ui.selectedStoryboardId);
  if (selectedIndex >= 0) {
    workbench.ui.storyboardPage = clampStoryboardWorkbenchPage(
      Math.floor(selectedIndex / pagination.pageSize) + 1,
      pagination.totalPages,
    );
    return;
  }
  workbench.ui.storyboardPage = clampStoryboardWorkbenchPage(pagination.page, pagination.totalPages);
}

function ensureEpisodeStoryboards(workbench, episodeId) {
  const existing = getEpisodeStoryboards(workbench, episodeId);
  if (Array.isArray(existing) && existing.length > 0) {
    return existing;
  }

  workbench.ui.episodeStoryboardMap = {
    ...workbench.ui.episodeStoryboardMap,
    [episodeId]: [],
  };
  return [];
}

function replaceActiveStoryboards(workbench, nextStoryboards) {
  const normalizedStoryboards = normalizeStoryboardIndices(nextStoryboards);
  if (workbench.ui.projectPanelMode !== "episode-workbench") {
    workbench.ui.storyboards = normalizedStoryboards;
    return;
  }

  const episodeId = workbench.ui.selectedEpisodeId;
  if (!episodeId || episodeId === "episode-primary") {
    workbench.ui.storyboards = normalizedStoryboards;
    return;
  }

  workbench.ui.episodeStoryboardMap = {
    ...workbench.ui.episodeStoryboardMap,
    [episodeId]: normalizedStoryboards,
  };
}

async function createStoryboardThroughApiOrLocal(workbench, episodeId, anchorStoryboardId) {
  const existing = getEpisodeStoryboards(workbench, episodeId);
  const nextIndex = existing.length + 1;
  const episodeRecord = getDetailEpisodes(workbench.state).find((item) => item?.id === episodeId) ?? null;
  const result = await workbench.api.createShot({
    projectId: workbench.state?.project?.id ?? workbench.state?.projectDetail?.project?.id ?? null,
    episodeId: episodeId === "episode-primary" ? null : episodeId,
    episodeTitle: episodeId === "episode-primary" ? null : (episodeRecord?.title ?? null),
    title: String(nextIndex),
    description: "",
  });
  appendCreatedShotToState(workbench, result.shot);
  if (episodeId !== "episode-primary" && typeof workbench.api.listStoryboards === "function") {
    const refreshedStoryboards = await loadEpisodeStoryboardsForWorkbench(workbench, episodeId);
    workbench.ui.selectedStoryboardId =
      refreshedStoryboards.find((item) => item.linkedShotId === result.shot?.id)?.id ??
      resolveInsertedStoryboardId(refreshedStoryboards, anchorStoryboardId) ??
      refreshedStoryboards.at(-1)?.id ??
      null;
    persistWorkbenchState(workbench);
    return;
  }
  createLocalStoryboard(workbench, episodeId, anchorStoryboardId, result.shot);
}

function createLocalStoryboard(workbench, episodeId, anchorStoryboardId, shot = null) {
  const existing = normalizeStoryboardIndices(getEpisodeStoryboards(workbench, episodeId));
  const nextStoryboards = anchorStoryboardId
    ? insertStoryboardAfter(existing, anchorStoryboardId)
    : addStoryboard(existing);
  const addedStoryboard = shot?.id
    ? nextStoryboards.find((item) => item.linkedShotId === shot.id) ?? nextStoryboards.find((item) => !item.linkedShotId)
    : nextStoryboards.find((item) => !item.linkedShotId);
  if (!addedStoryboard) {
    return null;
  }
  const now = new Date();
  const displayTitle = [
    now.getFullYear(),
    String(now.getMonth() + 1).padStart(2, "0"),
    String(now.getDate()).padStart(2, "0"),
  ].join("-") + ` ${String(now.getHours()).padStart(2, "0")}:${String(now.getMinutes()).padStart(2, "0")}:${String(now.getSeconds()).padStart(2, "0")}`;
  const nextStoryboard = {
    ...addedStoryboard,
    id: shot?.id ? `storyboard-${shot.id}` : addedStoryboard.id,
    linkedShotId: shot?.id ?? addedStoryboard.linkedShotId ?? null,
    displayTitle,
  };
  const previousEpisodeId = workbench.ui.selectedEpisodeId;
  if (episodeId !== "episode-primary") {
    workbench.ui.selectedEpisodeId = episodeId;
  }
  replaceActiveStoryboards(
    workbench,
    nextStoryboards.map((item) => (item === addedStoryboard ? nextStoryboard : item)),
  );
  if (episodeId === "episode-primary") {
    workbench.ui.selectedEpisodeId = previousEpisodeId;
    workbench.ui.storyboards = normalizeStoryboardIndices(
      nextStoryboards.map((item) => (item === addedStoryboard ? nextStoryboard : item)),
    );
  }
  workbench.ui.selectedStoryboardId = nextStoryboard.id;
  persistWorkbenchState(workbench);
  return nextStoryboard;
}

function appendCreatedShotToState(workbench, shot) {
  if (!shot || !shot.id || !workbench.state) {
    return;
  }

  const appendUniqueShot = (shots) => {
    if (!Array.isArray(shots)) {
      return [shot];
    }
    return shots.some((item) => item?.id === shot.id) ? shots : [...shots, shot];
  };

  const nextProjectDetail = workbench.state.projectDetail
    ? {
        ...workbench.state.projectDetail,
        shots: appendUniqueShot(workbench.state.projectDetail.shots),
      }
    : workbench.state.projectDetail;

  workbench.state = {
    ...workbench.state,
    shots: appendUniqueShot(workbench.state.shots),
    projectDetail: nextProjectDetail,
  };
  workbench.ui.projectDetail = nextProjectDetail ?? workbench.ui.projectDetail;
  workbench.ui.customEpisodes = getDetailEpisodes(workbench.state);
}

function removeDeletedShotFromState(workbench, shotId) {
  if (!shotId || !workbench.state) {
    return;
  }

  const nextShots = Array.isArray(workbench.state.shots)
    ? workbench.state.shots.filter((shot) => shot.id !== shotId)
    : workbench.state.shots;
  const nextProjectDetail = workbench.state.projectDetail
    ? {
        ...workbench.state.projectDetail,
        shots: Array.isArray(workbench.state.projectDetail.shots)
          ? workbench.state.projectDetail.shots.filter((shot) => shot.id !== shotId)
          : workbench.state.projectDetail.shots,
      }
    : workbench.state.projectDetail;

  workbench.state = {
    ...workbench.state,
    shots: nextShots,
    projectDetail: nextProjectDetail,
  };
  workbench.ui.projectDetail = nextProjectDetail ?? workbench.ui.projectDetail;
  workbench.ui.customEpisodes = getDetailEpisodes(workbench.state);
}

function resolveScriptReaderProjectId(workbench) {
  const selectedScriptId = String(workbench.ui?.selectedScriptId ?? "");
  const scriptLibraryRecords = Array.isArray(workbench.ui?.scriptLibraryRecords)
    ? workbench.ui.scriptLibraryRecords
    : [];
  const selectedScriptRecord = selectedScriptId
    ? scriptLibraryRecords.find((script) => String(script?.id ?? "") === selectedScriptId)
    : null;
  return (
    selectedScriptRecord?.projectId ??
    selectedScriptRecord?.project?.id ??
    workbench.ui?.selectedProjectCardId ??
    workbench.state?.projectDetail?.project?.id ??
    workbench.state?.project?.id ??
    ""
  );
}

function normalizeScriptReaderSection(section, fallback = {}) {
  return {
    ...fallback,
    ...section,
    id: String(section?.id ?? fallback.id ?? ""),
    title: String(section?.title ?? fallback.title ?? "新增剧情"),
    text: String(section?.body ?? section?.text ?? fallback.text ?? ""),
  };
}

async function loadScriptReaderSections(workbench) {
  const projectId = resolveScriptReaderProjectId(workbench);
  if (!projectId || typeof workbench.api?.getScriptReaderSections !== "function") {
    return;
  }
  const response = await workbench.api.getScriptReaderSections(projectId, {
    scriptId: workbench.ui.selectedScriptId ?? null,
  });
  const sections = Array.isArray(response?.sections) ? response.sections : [];
  workbench.ui.scriptReaderSections = sections.map((section) => normalizeScriptReaderSection(section));
  workbench.ui.scriptReaderSectionsLoaded = true;
  workbench.ui.scriptReaderDrafts = {
    ...(workbench.ui.scriptReaderDrafts ?? {}),
    ...Object.fromEntries(workbench.ui.scriptReaderSections.map((section) => [section.id, section.text])),
  };
  workbench.ui.scriptReaderTitleDrafts = {
    ...(workbench.ui.scriptReaderTitleDrafts ?? {}),
    ...Object.fromEntries(workbench.ui.scriptReaderSections.map((section) => [section.id, section.title])),
  };
  if (
    workbench.ui.scriptReaderSections.length &&
    !workbench.ui.scriptReaderSections.some((section) => section.id === workbench.ui.selectedScriptEpisodeId)
  ) {
    workbench.ui.selectedScriptEpisodeId = workbench.ui.scriptReaderSections[0].id;
  }
}

async function persistScriptReaderSection(workbench, sectionId, patch) {
  const projectId = resolveScriptReaderProjectId(workbench);
  if (!projectId || !sectionId || typeof workbench.api?.updateScriptReaderSection !== "function") {
    return null;
  }
  const response = await workbench.api.updateScriptReaderSection(projectId, sectionId, patch);
  const section = response?.section ? normalizeScriptReaderSection(response.section) : null;
  if (!section || !Array.isArray(workbench.ui.scriptReaderSections)) {
    return section;
  }
  workbench.ui.scriptReaderSections = workbench.ui.scriptReaderSections.map((current) =>
    current.id === section.id ? { ...current, ...section } : current,
  );
  return section;
}

function removeScriptReaderSectionFromUi(workbench, sectionId) {
  const sections = Array.isArray(workbench.ui.scriptReaderSections)
    ? workbench.ui.scriptReaderSections
    : [];
  const removedIndex = sections.findIndex((section) => section.id === sectionId);
  const nextSections = sections.filter((section) => section.id !== sectionId);
  workbench.ui.scriptReaderSections = nextSections;
  workbench.ui.scriptReaderSectionsLoaded = true;
  if (workbench.ui.selectedScriptEpisodeId === sectionId) {
    workbench.ui.selectedScriptEpisodeId =
      nextSections[Math.min(Math.max(removedIndex, 0), nextSections.length - 1)]?.id ?? "";
  }
  if (workbench.ui.scriptReaderDrafts && typeof workbench.ui.scriptReaderDrafts === "object") {
    delete workbench.ui.scriptReaderDrafts[sectionId];
  }
  if (workbench.ui.scriptReaderTitleDrafts && typeof workbench.ui.scriptReaderTitleDrafts === "object") {
    delete workbench.ui.scriptReaderTitleDrafts[sectionId];
  }
}

function saveScriptReaderDraftToState(workbench, episodeId, nextText) {
  if (!workbench?.state) {
    return;
  }

  if (Array.isArray(workbench.ui.scriptReaderSections)) {
    workbench.ui.scriptReaderSections = workbench.ui.scriptReaderSections.map((section) =>
      section?.id === episodeId
        ? {
            ...section,
            text: nextText,
          }
        : section,
    );
  }

  const normalizeEpisode = (episode) =>
    episode?.id === episodeId
      ? {
          ...episode,
          scriptText: nextText,
        }
      : episode;
  const projectDetail = workbench.state.projectDetail ?? null;
  const nextProjectDetail = projectDetail
    ? {
        ...projectDetail,
        script:
          !Array.isArray(projectDetail.episodes) || !projectDetail.episodes.some((episode) => episode?.id === episodeId)
            ? {
                ...(projectDetail.script ?? {}),
                inputText: nextText,
              }
            : projectDetail.script,
        episodes: Array.isArray(projectDetail.episodes)
          ? projectDetail.episodes.map(normalizeEpisode)
          : projectDetail.episodes,
      }
    : projectDetail;

  workbench.state = {
    ...workbench.state,
    script:
      !Array.isArray(workbench.state.projectDetail?.episodes) ||
      !workbench.state.projectDetail.episodes.some((episode) => episode?.id === episodeId)
        ? {
            ...(workbench.state.script ?? {}),
            inputText: nextText,
          }
        : workbench.state.script,
    projectDetail: nextProjectDetail,
  };
  workbench.ui.projectDetail = nextProjectDetail ?? workbench.ui.projectDetail;
  workbench.ui.customEpisodes = getDetailEpisodes(workbench.state);
}

async function commitScriptReaderTitle(workbench, episodeId, nextTitle) {
  const title = String(nextTitle ?? "").trim() || "未命名剧情";
  workbench.ui.scriptReaderTitleDrafts = {
    ...(workbench.ui.scriptReaderTitleDrafts ?? {}),
    [episodeId]: title,
  };

  if (Array.isArray(workbench.ui.scriptReaderSections)) {
    workbench.ui.scriptReaderSections = workbench.ui.scriptReaderSections.map((section) =>
      section?.id === episodeId
        ? {
            ...section,
            title,
          }
        : section,
    );
  }

  const projectDetail = workbench.state?.projectDetail ?? null;
  if (!projectDetail || !Array.isArray(projectDetail.episodes)) {
    await persistScriptReaderSection(workbench, episodeId, { title });
    return;
  }

  const nextProjectDetail = {
    ...projectDetail,
    episodes: projectDetail.episodes.map((episode) =>
      episode?.id === episodeId
        ? {
            ...episode,
            title,
            name: title,
          }
        : episode,
    ),
  };
  workbench.state = {
    ...(workbench.state ?? {}),
    projectDetail: nextProjectDetail,
  };
  workbench.ui.projectDetail = nextProjectDetail;
  workbench.ui.customEpisodes = getDetailEpisodes(workbench.state);
  await persistScriptReaderSection(workbench, episodeId, { title });
}

async function deleteStoryboardCard(workbench, storyboardId) {
  if (!storyboardId) {
    return;
  }

  const storyboards = getActiveStoryboards(workbench);
  const storyboard = storyboards.find((item) => item.id === storyboardId);
  if (!storyboard) {
    render(workbench);
    return;
  }

  const removedIndex = storyboards.findIndex((item) => item.id === storyboardId);
  const nextStoryboards = storyboards.filter((item) => item.id !== storyboardId);
  const fallbackStoryboardId = resolveAdjacentStoryboardId(nextStoryboards, removedIndex);
  const applyLocalRemoval = () => {
    replaceActiveStoryboards(workbench, nextStoryboards);
    workbench.ui.selectedStoryboardId =
      workbench.ui.selectedStoryboardId === storyboardId
        ? fallbackStoryboardId
        : workbench.ui.selectedStoryboardId;
  };

  if (storyboard.linkedShotId && workbench.state?.project?.id) {
    workbench.ui.busy = true;
    workbench.ui.toast = "正在删除当前分镜...";
    render(workbench);
    try {
      await workbench.api.deleteShot({ shotId: storyboard.linkedShotId });
      applyLocalRemoval();
      removeDeletedShotFromState(workbench, storyboard.linkedShotId);
      persistWorkbenchState(workbench);
      workbench.ui.toast = "已删除当前分镜。";
    } catch (error) {
      workbench.ui.toast = `删除失败：${friendlyError(error)}`;
    } finally {
      workbench.ui.busy = false;
      render(workbench);
    }
    return;
  }

  applyLocalRemoval();
  persistWorkbenchState(workbench);
  workbench.ui.toast = "已删除当前分镜。";
  render(workbench);
}

function resolveInsertedStoryboardId(storyboards, anchorStoryboardId) {
  if (!Array.isArray(storyboards) || !storyboards.length) {
    return null;
  }
  if (!anchorStoryboardId) {
    return storyboards.at(-1)?.id ?? null;
  }
  const anchorIndex = storyboards.findIndex((storyboard) => storyboard.id === anchorStoryboardId);
  if (anchorIndex < 0) {
    return storyboards.at(-1)?.id ?? null;
  }
  return storyboards[anchorIndex + 1]?.id ?? storyboards.at(-1)?.id ?? null;
}

function resolveAdjacentStoryboardId(storyboards, removedIndex) {
  if (!Array.isArray(storyboards) || !storyboards.length) {
    return null;
  }
  return storyboards[Math.min(removedIndex, storyboards.length - 1)]?.id ?? storyboards.at(-1)?.id ?? null;
}

function syncSelectedStoryboardId(workbench, storyboards) {
  if (!workbench.ui.selectedStoryboardId && storyboards.length > 0) {
    workbench.ui.selectedStoryboardId = storyboards[0].id;
    syncStoryboardPaginationForSelection(workbench);
    return;
  }

  if (
    workbench.ui.selectedStoryboardId &&
    !storyboards.some((storyboard) => storyboard.id === workbench.ui.selectedStoryboardId)
  ) {
    workbench.ui.selectedStoryboardId = storyboards[0]?.id ?? null;
  }
  syncStoryboardPaginationForSelection(workbench);
}

function hydratePersistedWorkbenchState(workbench) {
  const persisted = readWorkbenchState(workbench.state?.project?.id ?? null);
  if (!persisted) {
    return;
  }

  if (Array.isArray(persisted.storyboards)) {
    workbench.ui.storyboards = persisted.storyboards;
  }
  if (persisted.episodeStoryboardMap && typeof persisted.episodeStoryboardMap === "object") {
    workbench.ui.episodeStoryboardMap = persisted.episodeStoryboardMap;
  }
  if (persisted.episodeStoryboardPaginationMap && typeof persisted.episodeStoryboardPaginationMap === "object") {
    workbench.ui.episodeStoryboardPaginationMap = persisted.episodeStoryboardPaginationMap;
  }
  if (!getDetailEpisodes(workbench.state).length && Array.isArray(persisted.customEpisodes)) {
    workbench.ui.customEpisodes = persisted.customEpisodes;
  }
  if (typeof persisted.selectedEpisodeId === "string" || persisted.selectedEpisodeId === null) {
    workbench.ui.selectedEpisodeId = persisted.selectedEpisodeId;
  }
  if (typeof persisted.selectedStoryboardId === "string" || persisted.selectedStoryboardId === null) {
    workbench.ui.selectedStoryboardId = persisted.selectedStoryboardId;
  }
  if (typeof persisted.storyboardPage === "number") {
    workbench.ui.storyboardPage = persisted.storyboardPage;
  }
  if (typeof persisted.storyboardPageSize === "number") {
    workbench.ui.storyboardPageSize = normalizeStoryboardWorkbenchPageSize(persisted.storyboardPageSize);
  }
  if (typeof persisted.projectPanelMode === "string") {
    workbench.ui.projectPanelMode = persisted.projectPanelMode;
  }
  if (typeof persisted.projectInteriorSection === "string") {
    workbench.ui.projectInteriorSection = normalizeProjectInteriorSection(persisted.projectInteriorSection);
  }
  if (typeof persisted.museScopeMode === "string") {
    workbench.ui.museScopeMode = persisted.museScopeMode;
  }
  if (typeof persisted.episodeQuickAssetRailCollapsed === "boolean") {
    workbench.ui.episodeQuickAssetRailCollapsed = persisted.episodeQuickAssetRailCollapsed;
  }
  if (typeof persisted.projectAssetTab === "string") {
    workbench.ui.projectAssetTab = persisted.projectAssetTab;
  }
  if (typeof persisted.episodeWorkbenchCenterWidthRatio === "number") {
    workbench.ui.episodeWorkbenchCenterWidthRatio = clampEpisodeWorkbenchCenterWidthRatio(
      persisted.episodeWorkbenchCenterWidthRatio,
    );
    if (
      typeof persisted.episodeWorkbenchCenterWidthPx !== "number"
      && (
        Math.abs(workbench.ui.episodeWorkbenchCenterWidthRatio - EPISODE_LAYOUT_LEGACY_DEFAULT_CENTER_WIDTH) < 0.001
        || Math.abs(workbench.ui.episodeWorkbenchCenterWidthRatio - EPISODE_LAYOUT_EARLY_DEFAULT_CENTER_WIDTH) < 0.001
      )
    ) {
      workbench.ui.episodeWorkbenchCenterWidthRatio = EPISODE_LAYOUT_DEFAULT_CENTER_WIDTH;
    }
  } else if (typeof persisted.episodeWorkbenchLeftWidthRatio === "number") {
    workbench.ui.episodeWorkbenchCenterWidthRatio = clampEpisodeWorkbenchCenterWidthRatio(
      persisted.episodeWorkbenchLeftWidthRatio + 0.26,
    );
  }
  if (typeof persisted.episodeWorkbenchCenterWidthPx === "number") {
    workbench.ui.episodeWorkbenchCenterWidthPx = clampEpisodeWorkbenchCenterWidthPx(
      persisted.episodeWorkbenchCenterWidthPx,
    );
  }
  const persistedWidthVersion = Number(persisted.episodeWorkbenchCenterWidthVersion ?? 0);
  if (persistedWidthVersion < EPISODE_LAYOUT_WIDTH_VERSION) {
    const defaultPixelWidth = buildEpisodeWorkbenchDefaultCenterWidthPx();
    if (defaultPixelWidth) {
      workbench.ui.episodeWorkbenchCenterWidthPx = defaultPixelWidth;
      workbench.ui.episodeWorkbenchCenterWidthRatio = EPISODE_LAYOUT_DEFAULT_CENTER_WIDTH;
    }
  }
  if (typeof persisted.selectedEpisodeAssetId === "string" || persisted.selectedEpisodeAssetId === null) {
    workbench.ui.selectedEpisodeAssetId = persisted.selectedEpisodeAssetId;
  }
  if (typeof persisted.selectedEpisodeCardId === "string" || persisted.selectedEpisodeCardId === null) {
    workbench.ui.selectedEpisodeCardId = persisted.selectedEpisodeCardId;
  }
  if (persisted.canvasDocument && typeof persisted.canvasDocument === "object") {
    workbench.ui.canvasDocument = persisted.canvasDocument;
  }
  if (Array.isArray(persisted.canvasProjects)) {
    workbench.ui.canvasProjects = persisted.canvasProjects;
  }
  if (typeof persisted.selectedCanvasProjectId === "string") {
    workbench.ui.selectedCanvasProjectId = persisted.selectedCanvasProjectId;
  }
  if (persisted.canvasDocumentsByProject && typeof persisted.canvasDocumentsByProject === "object") {
    workbench.ui.canvasDocumentsByProject = persisted.canvasDocumentsByProject;
  }
  if (persisted.canvasProjectView === "detail" || persisted.canvasProjectView === "list") {
    workbench.ui.canvasProjectView = persisted.canvasProjectView;
  }
  if (typeof persisted.selectedCanvasNodeId === "string" || persisted.selectedCanvasNodeId === null) {
    workbench.ui.selectedCanvasNodeId = persisted.selectedCanvasNodeId;
  }
  const routeToken = typeof window !== "undefined" ? String(window.location?.hash ?? "").replace(/^#/, "") : "";
  if (routeToken === "tools" || routeToken === "tools-canvas") {
    workbench.ui.canvasProjectView = deriveInitialCanvasProjectView(routeToken);
  }
  sanitizeEpisodeWorkbenchSelection(workbench, { persist: true });
}

function syncWorkbenchRouteState(workbench, hash) {
  const token = String(hash || "").replace(/^#/, "");
  if (parseEpisodeRouteToken(token)) {
    workbench.ui.activeNavTab = "project";
    workbench.ui.projectPanelMode = "episode-workbench";
    workbench.ui.projectInteriorSection = "episodes";
    return;
  }
  if (parseProjectRouteToken(token)) {
    const route = parseProjectRouteToken(token);
    workbench.ui.activeNavTab = "project";
    workbench.ui.projectPanelMode = "workspace";
    workbench.ui.projectInteriorSection = route.section;
    return;
  }
  if (token === "project") {
    workbench.ui.activeNavTab = "project";
    workbench.ui.projectPanelMode = "library";
    return;
  }
  if (token === "project-workspace" || token === "asset-prep-section") {
    workbench.ui.activeNavTab = "project";
    workbench.ui.projectPanelMode = "workspace";
    workbench.ui.projectInteriorSection = workbench.ui.projectInteriorSection ?? "overview";
    return;
  }
  if (token === "community") {
    workbench.ui.activeNavTab = "community";
    workbench.ui.projectPanelMode = "workspace";
    workbench.ui.projectInteriorSection = "episodes";
    return;
  }
  if (token === "media-library") {
    workbench.ui.activeNavTab = "media-library";
    workbench.ui.projectPanelMode = "workspace";
    workbench.ui.projectInteriorSection = "episodes";
    return;
  }
  if (token === "home" || token === "script" || token === "library" || token === "tools" || token === "tools-canvas") {
    workbench.ui.activeNavTab = token;
    if (token === "tools-canvas") {
      workbench.ui.activeNavTab = "tools";
      workbench.ui.canvasProjectView = "detail";
    } else if (token === "tools") {
      workbench.ui.canvasProjectView = "list";
    }
    workbench.ui.projectPanelMode = "library";
    workbench.ui.selectedEpisodeId = null;
    workbench.ui.episodeWorkbenchContext = null;
    if (token === "library") {
      workbench.ui.libraryTeamRoute = "assets";
    }
    return;
  }
  if (token === "team" || token.startsWith("team-dashboard")) {
    if (isTeamMemberSession(workbench.session)) {
      workbench.ui.activeNavTab = "project";
      workbench.ui.projectPanelMode = "workspace";
      workbench.ui.projectInteriorSection = "overview";
      workbench.ui.libraryTeamRoute = "assets";
      return;
    }
    workbench.ui.activeNavTab = "team";
    workbench.ui.projectPanelMode = "library";
    workbench.ui.selectedEpisodeId = null;
    workbench.ui.episodeWorkbenchContext = null;
    workbench.ui.libraryTeamRoute = token.startsWith("team-dashboard") ? "team-dashboard" : "team";
    workbench.ui.teamDashboardTab = deriveInitialTeamDashboardTab(token);
    return;
  }
  if (token !== "storyboard-workbench" && token !== "episode-workbench") {
    return;
  }

  workbench.ui.activeNavTab = "project";
  workbench.ui.projectPanelMode = "episode-workbench";
  workbench.ui.projectInteriorSection = "episodes";
  workbench.ui.selectedEpisodeId =
    workbench.ui.selectedEpisodeId ?? getDefaultEpisodeWorkbenchId(workbench);
}

function syncCanvasRouteState(workbench, hash) {
  const token = String(hash || "").replace(/^#/, "");
  if (token !== "tools" && token !== "tools-canvas") {
    return;
  }
  workbench.ui.activeNavTab = "tools";
  workbench.ui.projectPanelMode = "library";
  workbench.ui.canvasProjectView = deriveInitialCanvasProjectView(token);
  if (token === "tools") {
    workbench.ui.selectedCanvasNodeId = null;
    workbench.ui.canvasEditorOpen = false;
    workbench.ui.canvasAddMenuOpen = false;
    workbench.ui.canvasContextMenu = null;
  }
}

async function restoreEpisodeRouteState(workbench, locationLike) {
  const route = parseEpisodeRouteFromLocation(locationLike);
  if (!route) {
    return false;
  }

  workbench.ui.activeNavTab = "project";
  workbench.ui.projectPanelMode = "episode-workbench";
  workbench.ui.projectInteriorSection = "episodes";
  workbench.ui.selectedProjectCardId = route.projectId;
  workbench.ui.selectedEpisodeId = route.episodeId;

  try {
    if (workbench.state?.project?.id !== route.projectId) {
      applyProjectDetail(workbench, await loadProjectDetailForWorkbench(workbench, route.projectId));
      await syncProjectInteriorSupplementary(workbench);
    }
    await enterEpisodeWorkbench(workbench, route.episodeId, {
      preserveRoute: true,
      shouldRender: false,
    });
    return true;
  } catch (error) {
    workbench.ui.selectedEpisodeId = null;
    workbench.ui.projectPanelMode = "workspace";
    workbench.ui.projectInteriorSection = "episodes";
    workbench.ui.episodeWorkbenchContext = null;
    workbench.ui.episodeWorkbenchError = friendlyError(error);
    workbench.ui.toast = `Episode route restore failed: ${workbench.ui.episodeWorkbenchError}`;
    return false;
  }
}

async function restoreProjectRouteState(workbench, locationLike) {
  const route = parseProjectRouteFromLocation(locationLike);
  if (!route) {
    return false;
  }

  workbench.ui.activeNavTab = "project";
  workbench.ui.projectPanelMode = "workspace";
  workbench.ui.projectInteriorSection = route.section;
  workbench.ui.selectedProjectCardId = route.projectId;

  try {
    applyProjectDetail(workbench, await loadProjectDetailForWorkbench(workbench, route.projectId));
    if (shouldLoadProjectInteriorSupplementary(workbench.ui.projectInteriorSection)) {
      await syncProjectInteriorSupplementary(workbench);
    }
    return true;
  } catch (error) {
    workbench.ui.projectPanelMode = "library";
    workbench.ui.episodeWorkbenchError = friendlyError(error);
    workbench.ui.toast = `Project route restore failed: ${workbench.ui.episodeWorkbenchError}`;
    return false;
  }
}

function parseEpisodeRouteFromLocation(locationLike) {
  const hashRoute = parseEpisodeRouteToken(locationLike?.hash ?? "");
  if (hashRoute) {
    return hashRoute;
  }
  return parseEpisodeRouteToken(locationLike?.pathname ?? "");
}

function parseProjectRouteFromLocation(locationLike) {
  const hashRoute = parseProjectRouteToken(locationLike?.hash ?? "");
  if (hashRoute) {
    return hashRoute;
  }
  return parseProjectRouteToken(locationLike?.pathname ?? "");
}

export function parseEpisodeRouteForWorkbench(locationLike) {
  return parseEpisodeRouteFromLocation(locationLike);
}

export function parseProjectRouteForWorkbench(locationLike) {
  return parseProjectRouteFromLocation(locationLike);
}

function parseEpisodeRouteToken(value) {
  const token = decodeURIComponent(String(value || ""))
    .replace(/^#/, "")
    .replace(/^\//, "")
    .replace(/^!\/?/, "");
  const match = token.match(/^projects?\/([^/?#]+)\/episodes\/([^/?#]+)/);
  if (!match) {
    return null;
  }
  return {
    projectId: match[1],
    episodeId: match[2],
  };
}

function parseProjectRouteToken(value) {
  const token = decodeURIComponent(String(value || ""))
    .replace(/^#/, "")
    .replace(/^\//, "")
    .replace(/^!\/?/, "");
  const match = token.match(/^projects?\/([^/?#]+)(?:\/([^/?#]+))?\/?$/);
  if (!match) {
    return null;
  }
  if (match[2] && !PROJECT_INTERIOR_SECTIONS.has(match[2])) {
    return null;
  }
  const section = normalizeProjectInteriorSection(match[2]);
  return {
    projectId: match[1],
    section,
  };
}

function getDefaultEpisodeWorkbenchId(workbench) {
  const episodes = getDetailEpisodes(workbench.state);
  const realEpisode = episodes.find((episode) => episode?.id && episode.id !== "episode-primary");
  return realEpisode?.id ?? episodes[0]?.id ?? "episode-primary";
}

function hasPersistedEpisodeWorkbenchId(workbench, episodeId = workbench?.ui?.selectedEpisodeId ?? null) {
  if (!episodeId || episodeId === "episode-primary") {
    return false;
  }
  const detailEpisodes = getDetailEpisodes(workbench?.state ?? {});
  return detailEpisodes.some((episode) => episode?.id === episodeId);
}

function resolvePersistedEpisodeWorkbenchId(workbench, episodeId = workbench?.ui?.selectedEpisodeId ?? null) {
  if (hasPersistedEpisodeWorkbenchId(workbench, episodeId)) {
    return episodeId;
  }
  const fallbackEpisodeId = getDefaultEpisodeWorkbenchId(workbench);
  return fallbackEpisodeId === "episode-primary" ? null : fallbackEpisodeId;
}

export function sanitizeEpisodeWorkbenchSelection(workbench, options = {}) {
  const previousEpisodeId = workbench?.ui?.selectedEpisodeId ?? null;
  const resolvedEpisodeId = resolvePersistedEpisodeWorkbenchId(workbench, previousEpisodeId);
  const shouldResetEpisodeSelection =
    workbench?.ui?.projectPanelMode === "episode-workbench" &&
    previousEpisodeId &&
    previousEpisodeId !== "episode-primary" &&
    !hasPersistedEpisodeWorkbenchId(workbench, previousEpisodeId);
  if (!shouldResetEpisodeSelection && previousEpisodeId === resolvedEpisodeId) {
    return false;
  }
  workbench.ui.selectedEpisodeId = resolvedEpisodeId;
  if (shouldResetEpisodeSelection) {
    workbench.ui.selectedEpisodeAssetId = null;
    workbench.ui.selectedEpisodeCardId = null;
    workbench.ui.selectedEpisodeAssetIds = [];
    workbench.ui.imageGenerationResult = null;
    workbench.ui.videoGenerationResult = null;
  }
  syncStoryboardPaginationForSelection(workbench);
  if (options.persist === true) {
    writeWorkbenchState(workbench.state?.project?.id ?? null, buildPersistedWorkbenchStatePayload(workbench));
  }
  return true;
}

function persistWorkbenchState(workbench) {
  writeWorkbenchState(workbench.state?.project?.id ?? null, buildPersistedWorkbenchStatePayload(workbench));
}

function readWorkbenchState(projectId) {
  if (typeof window === "undefined" || !window.localStorage || !projectId) {
    return null;
  }

  try {
    const raw = window.localStorage.getItem(getWorkbenchStorageKey(projectId));
    return raw ? JSON.parse(raw) : null;
  } catch {
    return null;
  }
}

function writeWorkbenchState(projectId, payload) {
  if (typeof window === "undefined" || !window.localStorage || !projectId || !payload) {
    return;
  }

  try {
    window.localStorage.setItem(getWorkbenchStorageKey(projectId), JSON.stringify(payload));
  } catch {
    // Ignore persistence failures in constrained browsers.
  }
}

function getWorkbenchStorageKey(projectId) {
  return `${WORKBENCH_STORAGE_PREFIX}:${projectId}`;
}

function buildPersistedWorkbenchStatePayload(workbench) {
  const projectId = workbench.state?.project?.id ?? null;
  if (!projectId) {
    return null;
  }
  const detailEpisodes = getDetailEpisodes(workbench.state);
  const storyboardPagination = getEpisodeStoryboardPagination(workbench);
  const selectedEpisodeId = hasPersistedEpisodeWorkbenchId(workbench)
    ? (workbench.ui.selectedEpisodeId ?? null)
    : resolvePersistedEpisodeWorkbenchId(workbench);
  return {
    selectedEpisodeId,
    selectedStoryboardId: workbench.ui.selectedStoryboardId ?? null,
    storyboardPage: clampStoryboardWorkbenchPage(
      workbench.ui.storyboardPage,
      storyboardPagination.totalPages,
    ),
    storyboardPageSize: normalizeStoryboardWorkbenchPageSize(workbench.ui.storyboardPageSize),
    selectedEpisodeAssetId: workbench.ui.selectedEpisodeAssetId ?? null,
    selectedEpisodeCardId: workbench.ui.selectedEpisodeCardId ?? null,
    projectPanelMode: workbench.ui.projectPanelMode ?? "library",
    projectInteriorSection: normalizeProjectInteriorSection(workbench.ui.projectInteriorSection),
    museScopeMode: workbench.ui.museScopeMode ?? "storyboard",
    episodeQuickAssetRailCollapsed: Boolean(workbench.ui.episodeQuickAssetRailCollapsed),
    episodeWorkbenchCenterWidthRatio: clampEpisodeWorkbenchCenterWidthRatio(
      workbench.ui.episodeWorkbenchCenterWidthRatio,
    ),
    episodeWorkbenchCenterWidthPx: clampEpisodeWorkbenchCenterWidthPx(
      workbench.ui.episodeWorkbenchCenterWidthPx,
    ),
    episodeWorkbenchCenterWidthVersion: EPISODE_LAYOUT_WIDTH_VERSION,
    projectAssetTab: workbench.ui.projectAssetTab ?? "character",
    storyboards: Array.isArray(workbench.ui.storyboards) ? workbench.ui.storyboards : [],
    episodeStoryboardMap: workbench.ui.episodeStoryboardMap ?? {},
    episodeStoryboardPaginationMap: workbench.ui.episodeStoryboardPaginationMap ?? {},
    canvasDocument: workbench.ui.canvasDocument ?? null,
    canvasProjects: normalizeCanvasProjects(workbench.ui),
    selectedCanvasProjectId: workbench.ui.selectedCanvasProjectId ?? DEFAULT_CANVAS_PROJECT_ID,
    canvasDocumentsByProject: workbench.ui.canvasDocumentsByProject ?? null,
    canvasProjectView: workbench.ui.canvasProjectView === "detail" ? "detail" : "list",
    selectedCanvasNodeId: workbench.ui.selectedCanvasNodeId ?? null,
    customEpisodes: detailEpisodes.length
      ? detailEpisodes
      : (Array.isArray(workbench.ui.customEpisodes) ? workbench.ui.customEpisodes : []),
  };
}

function syncSelectedEpisodeAssetForCurrentTab(workbench) {
  const assetTab = workbench.ui.projectAssetTab ?? "character";
  const assetEntries =
    assetTab === "other"
      ? workbench.ui.importedAssets?.other?.[normalizeProjectOtherAssetMediaType(workbench.ui.projectOtherAssetMediaType, "audio")] ?? []
      : workbench.ui.importedAssets?.[assetTab] ?? [];
  const selectedId =
    assetEntries.find((item) => item.id === workbench.ui.selectedEpisodeCardId)?.id ??
    assetEntries.find((item) => item.id === workbench.ui.selectedEpisodeAssetId)?.id ??
    assetEntries[0]?.id ??
    null;
  workbench.ui.selectedEpisodeCardId = selectedId;
  workbench.ui.selectedEpisodeAssetId = selectedId;
  const validIds = new Set(assetEntries.map((item) => item.id));
  workbench.ui.selectedEpisodeAssetIds = (workbench.ui.selectedEpisodeAssetIds ?? []).filter((id) => validIds.has(id));
  return selectedId;
}

async function handleAssetImportFiles(workbench, files) {
  const assetKind = workbench.ui.assetImportModal ?? workbench.ui.projectAssetTab ?? "character";
  const existingDrafts = workbench.ui.assetImportDrafts ?? [];
  const slotsLeft = Math.max(20 - existingDrafts.length, 0);
  const acceptedFiles = files.slice(0, slotsLeft);

  if (!acceptedFiles.length) {
    workbench.ui.toast = "一次最多可导入 20 个本地资产。";
    render(workbench);
    return;
  }

  const nextDrafts = await Promise.all(
    acceptedFiles.map((file, index) =>
      buildAssetImportDraftFromFile(workbench, assetKind, existingDrafts.length + index, file),
    ),
  );

  workbench.ui.assetImportDrafts = [...existingDrafts, ...nextDrafts];
  workbench.ui.assetImportSelection = createAssetSelectionList([
    ...(workbench.ui.assetImportSelection ?? []),
    ...nextDrafts.map((draft) => draft.id),
  ]);
  workbench.ui.toast =
    files.length > acceptedFiles.length
      ? `已导入 ${acceptedFiles.length} 个资产，超出部分已忽略。`
      : `已添加 ${acceptedFiles.length} 个待导入资产。`;
  render(workbench);
}

async function handleLocalStoryboardVideoFiles(workbench, storyboardId, files) {
  const acceptedFiles = files.filter((file) => String(file.type || "").startsWith("video/"));
  if (!acceptedFiles.length) {
    workbench.ui.toast = "请选择视频文件后再上传。";
    render(workbench);
    return;
  }

  for (const file of acceptedFiles) {
    await startStoryboardVideoUpload(workbench, storyboardId, file);
  }

  workbench.ui.toast = `已添加 ${acceptedFiles.length} 个待上传视频。`;
  render(workbench);
}

async function handleLocalStoryboardImageFile(workbench, storyboardId, file) {
  if (!String(file.type || "").startsWith("image/")) {
    workbench.ui.toast = "请选择图片文件后再上传。";
    render(workbench);
    return;
  }

  const existingStoryboard = getActiveStoryboards(workbench).find((item) => item.id === storyboardId);
  const hadPinnedImage = Boolean(existingStoryboard?.previewImageUrl || existingStoryboard?.currentImageAssetVersionId);

  updateStoryboardById(workbench, storyboardId, (storyboard) => ({
    ...storyboard,
    imageStatus: "uploading",
    uploadedImageName: file.name,
  }));
  workbench.ui.toast = "正在上传分镜图片...";
  render(workbench);

  let upload;
  try {
    upload = await uploadLocalFile(workbench, file, "storyboard-images");
  } catch (error) {
    updateStoryboardById(workbench, storyboardId, (storyboard) => ({
      ...storyboard,
      imageStatus: storyboard.previewImageUrl ? "ready" : "empty",
    }));
    workbench.ui.toast = `图片上传失败：${friendlyError(error)}`;
    render(workbench);
    return;
  }

  const previewImageUrl = resolveApiUrl(upload.publicUrl);
  const createImageEntry = (imageId) => ({
    id: imageId,
    deleteAssetId: imageId,
    fileName: file.name,
    src: previewImageUrl,
    status: "ready",
    createdAt: Date.now(),
  });
  const applyLocalReadyImage = (imageId, toastMessage) => {
    updateStoryboardById(workbench, storyboardId, (storyboard) => {
      const shouldAutoPin = !hadPinnedImage;
      const uploadedImage = createImageEntry(imageId);
      const nextStoryboard = {
        ...storyboard,
        imageStatus: "ready",
        uploadedImages: mergeStoryboardUploadedImages(storyboard.uploadedImages ?? [], [uploadedImage]),
        previewImageUrl: shouldAutoPin ? previewImageUrl : storyboard.previewImageUrl ?? null,
        uploadedImageName: shouldAutoPin ? file.name : storyboard.uploadedImageName,
        currentImageAssetVersionId: shouldAutoPin ? uploadedImage.id : storyboard.currentImageAssetVersionId ?? null,
      };
      return {
        ...nextStoryboard,
        previewUrl: shouldAutoPin ? previewImageUrl : resolveStoryboardCombinedPreviewUrl(nextStoryboard),
      };
    });
    workbench.ui.toast = toastMessage;
    render(workbench);
  };
  let storyboard = getActiveStoryboards(workbench).find((item) => item.id === storyboardId);
  if (!storyboard?.linkedShotId && workbench.state?.project?.id) {
    try {
      storyboard = await ensureStoryboardShot(workbench, storyboardId);
    } catch (error) {
      applyLocalReadyImage(
        `local-image-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
        `图片已保留在本地，后端同步失败：${friendlyError(error)}`,
      );
      return;
    }
  }
  const activeStoryboardId = storyboard?.id ?? storyboardId;
  if (storyboard?.linkedShotId) {
    let importedVersionId = null;
    let importSucceeded = false;
    await runAction(workbench, "正在同步分镜图片...", async () => {
      const bound = await bindEpisodeUploadIfAvailable(workbench, upload, {
        targetType: "storyboard",
        targetId: activeStoryboardId,
        mediaKind: "image",
        width: 1024,
        height: 1024,
      });
      const imported = bound
        ? null
        : await workbench.api.importShotMedia(storyboard.linkedShotId, {
            kind: "image",
            name: file.name,
            uploadSessionId: upload.uploadSessionId,
            storageObjectId: upload.storageObjectId,
            mimeType: upload.mimeType,
            width: 1024,
            height: 1024,
          });
      importedVersionId = bound?.fileResource?.assetVersionId ?? imported?.version?.id ?? null;
      updateStoryboardById(workbench, activeStoryboardId, (currentStoryboard) => {
        const shouldAutoPin = !hadPinnedImage;
        const importedImage = createImageEntry(importedVersionId ?? `local-image-${Date.now()}`);
        importedImage.assetVersionId = importedVersionId;
        importedImage.storageObjectId = bound?.fileResource?.storageObjectId ?? upload.storageObjectId ?? null;
        importedImage.src = resolveApiUrl(bound?.file?.previewUrl ?? importedImage.src);
        const nextStoryboard = {
          ...currentStoryboard,
          imageStatus: "ready",
          uploadedImages: mergeStoryboardUploadedImages(currentStoryboard.uploadedImages ?? [], [importedImage]),
          previewImageUrl: shouldAutoPin ? importedImage.src : currentStoryboard.previewImageUrl ?? null,
          uploadedImageName: shouldAutoPin ? file.name : currentStoryboard.uploadedImageName,
          currentImageAssetVersionId:
            shouldAutoPin ? importedImage.id : currentStoryboard.currentImageAssetVersionId ?? null,
        };
        return {
          ...nextStoryboard,
          previewUrl: shouldAutoPin ? importedImage.src : resolveStoryboardCombinedPreviewUrl(nextStoryboard),
        };
      });
      if (hadPinnedImage && storyboard.currentImageAssetVersionId) {
        await workbench.api.updateShot({
          shotId: storyboard.linkedShotId,
          currentImageAssetVersionId: storyboard.currentImageAssetVersionId,
        });
      }
      importSucceeded = true;
    });
    if (!importSucceeded) {
      applyLocalReadyImage(
        importedVersionId ?? `local-image-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
        `${file.name} uploaded locally; backend sync is still pending.`,
      );
    }
    return;
  }

  updateStoryboardById(workbench, activeStoryboardId, (storyboard) => {
    const shouldAutoPin = !hadPinnedImage;
    const uploadedImage = createImageEntry(`local-image-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`);
    const nextStoryboard = {
      ...storyboard,
      imageStatus: "ready",
      uploadedImages: mergeStoryboardUploadedImages(storyboard.uploadedImages ?? [], [uploadedImage]),
      previewImageUrl: shouldAutoPin ? previewImageUrl : storyboard.previewImageUrl ?? null,
      uploadedImageName: shouldAutoPin ? file.name : storyboard.uploadedImageName,
      currentImageAssetVersionId: shouldAutoPin ? uploadedImage.id : storyboard.currentImageAssetVersionId ?? null,
    };
    return {
      ...nextStoryboard,
      previewUrl: shouldAutoPin ? previewImageUrl : resolveStoryboardCombinedPreviewUrl(nextStoryboard),
    };
  });

  workbench.ui.toast = `已上传 ${file.name}，可继续作为分镜图片使用。`;
  render(workbench);
}

async function startStoryboardVideoUpload(workbench, storyboardId, file) {
  const videoId = `local-video-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
  const localPreviewSrc = URL.createObjectURL(file);
  let storyboard = getActiveStoryboards(workbench).find((item) => item.id === storyboardId);
  if (!storyboard?.linkedShotId && workbench.state?.project?.id) {
    try {
      storyboard = await ensureStoryboardShot(workbench, storyboardId);
    } catch (error) {
      cancelStoryboardVideoUpload(workbench, storyboardId, videoId);
      updateStoryboardById(workbench, storyboardId, (currentStoryboard) => {
        const localReadyVideo = {
          id: videoId,
          fileName: file.name,
          src: localPreviewSrc,
          progress: 100,
          status: "ready",
          durationLabel: "00:10",
          createdAt: Date.now(),
          thumbnailSrc: null,
        };
        const uploadedVideos = [...(currentStoryboard.uploadedVideos ?? []).filter((video) => video.id !== videoId), localReadyVideo];
        const nextStoryboard = {
          ...currentStoryboard,
          uploadedVideos,
          selectedUploadedVideoId: currentStoryboard.selectedUploadedVideoId ?? videoId,
          videoStatus: "ready",
          previewVideo: currentStoryboard.previewVideo ?? localReadyVideo.src,
          previewThumbnailUrl: currentStoryboard.previewThumbnailUrl ?? null,
        };
        return {
          ...nextStoryboard,
          previewUrl: resolveStoryboardCombinedPreviewUrl(nextStoryboard),
        };
      });
      workbench.ui.toast = `创建分镜视频失败：${friendlyError(error)}`;
      render(workbench);
      return;
    }
  }
  const hadPinnedVideo = Boolean(storyboard?.selectedUploadedVideoId);
  const pendingVideo = {
    id: videoId,
    fileName: file.name,
    src: localPreviewSrc,
    progress: 12,
    status: "uploading",
    durationLabel: "00:10",
    createdAt: Date.now(),
    thumbnailSrc: null,
  };

  workbench.uploadTasks.set(videoId, { src: localPreviewSrc });
  updateStoryboardById(workbench, storyboardId, (currentStoryboard) => ({
    ...currentStoryboard,
    uploadedVideos: [...(currentStoryboard.uploadedVideos ?? []), pendingVideo],
    selectedUploadedVideoId: currentStoryboard.selectedUploadedVideoId ?? videoId,
    videoStatus: "uploading",
  }));
  workbench.ui.toast = "Uploading storyboard video...";
  render(workbench);

  let upload;
  try {
    upload = await uploadLocalFile(workbench, file, "storyboard-videos", {
      onProgress(progress) {
        const percent = Math.max(0, Math.min(100, Math.round((progress?.progress ?? 0) * 100)));
        updateStoryboardById(workbench, storyboardId, (currentStoryboard) => ({
          ...currentStoryboard,
          uploadedVideos: (currentStoryboard.uploadedVideos ?? []).map((video) =>
            video.id === videoId
              ? {
                  ...video,
                  progress: percent,
                  status: "uploading",
                }
              : video,
          ),
        }));
        render(workbench);
      },
    });
  } catch (error) {
    cancelStoryboardVideoUpload(workbench, storyboardId, videoId);
    workbench.ui.toast = `视频上传失败：${friendlyError(error)}`;
    render(workbench);
    return;
  }

  if (!isStoryboardVideoPending(workbench, storyboardId, videoId)) {
    URL.revokeObjectURL(localPreviewSrc);
    workbench.uploadTasks.delete(videoId);
    return;
  }

  const resolvedUploadUrl = resolveApiUrl(upload.publicUrl);
  URL.revokeObjectURL(localPreviewSrc);
  workbench.uploadTasks.delete(videoId);
  const localReadyVideo = {
    id: videoId,
    fileName: file.name,
    src: resolvedUploadUrl,
    progress: 100,
    status: "ready",
    durationLabel: "00:10",
    createdAt: Date.now(),
    thumbnailSrc: null,
  };

  updateStoryboardById(workbench, storyboardId, (currentStoryboard) => {
    const uploadedVideos = (currentStoryboard.uploadedVideos ?? []).map((video) =>
      video.id === videoId ? localReadyVideo : video,
    );
    const shouldAutoPin = !hadPinnedVideo;
    const nextStoryboard = {
      ...currentStoryboard,
      uploadedVideos,
      selectedUploadedVideoId: shouldAutoPin ? videoId : currentStoryboard.selectedUploadedVideoId,
      videoStatus: "ready",
      previewVideo: shouldAutoPin ? localReadyVideo.src : currentStoryboard.previewVideo ?? null,
      previewThumbnailUrl:
        shouldAutoPin ? (localReadyVideo.thumbnailSrc ?? null) : currentStoryboard.previewThumbnailUrl ?? null,
    };
    return {
      ...nextStoryboard,
      previewUrl: resolveStoryboardCombinedPreviewUrl(nextStoryboard),
    };
  });
  workbench.ui.toast = `${file.name} uploaded.`;
  render(workbench);
  hydrateStoryboardVideoPreview(workbench, storyboardId, videoId, resolvedUploadUrl);

  if (storyboard?.linkedShotId) {
    await runAction(workbench, "正在同步分镜视频...", async () => {
      const bound = await bindEpisodeUploadIfAvailable(workbench, upload, {
        targetType: "storyboard",
        targetId: storyboardId,
        mediaKind: "video",
        width: 1024,
        height: 1024,
      });
      const imported = bound
        ? null
        : await workbench.api.importShotMedia(storyboard.linkedShotId, {
            kind: "video",
            name: file.name,
            uploadSessionId: upload.uploadSessionId,
            storageObjectId: upload.storageObjectId,
            mimeType: upload.mimeType,
            width: 1024,
            height: 1024,
          });
      const boundPreviewUrl = resolveApiUrl(bound?.file?.previewUrl ?? resolvedUploadUrl);
      const importedVideo = {
        id: bound?.fileResource?.assetVersionId ?? imported?.version?.id ?? videoId,
        assetVersionId: bound?.fileResource?.assetVersionId ?? imported?.version?.id ?? null,
        fileName: file.name,
        src: boundPreviewUrl,
        progress: 100,
        status: "ready",
        durationLabel: formatDurationLabelFromMs(imported?.version?.metadata?.durationMs),
        createdAt: Date.parse(imported?.version?.createdAt ?? "") || Date.now(),
        storageObjectId: bound?.fileResource?.storageObjectId ?? upload.storageObjectId ?? null,
        thumbnailSrc:
          getActiveStoryboards(workbench)
            .find((item) => item.id === storyboardId)
            ?.uploadedVideos?.find((video) => video.id === videoId)?.thumbnailSrc ?? null,
      };
      updateStoryboardById(workbench, storyboardId, (currentStoryboard) => {
        const withoutPending = (currentStoryboard.uploadedVideos ?? []).filter((video) => video.id !== videoId);
        const uploadedVideos = mergeStoryboardUploadedVideos(withoutPending, [importedVideo]);
        const shouldAutoPin = !hadPinnedVideo;
        const selectedUploadedVideoId =
          currentStoryboard.selectedUploadedVideoId === videoId
            ? importedVideo.id
            : shouldAutoPin
              ? importedVideo.id
              : currentStoryboard.selectedUploadedVideoId;
        return {
          ...currentStoryboard,
          uploadedVideos,
          selectedUploadedVideoId,
          videoStatus: "ready",
          previewVideo: selectedUploadedVideoId === importedVideo.id ? importedVideo.src : currentStoryboard.previewVideo ?? null,
          previewThumbnailUrl:
            selectedUploadedVideoId === importedVideo.id
              ? (importedVideo.thumbnailSrc ?? null)
              : currentStoryboard.previewThumbnailUrl ?? null,
          currentVideoAssetVersionId:
            selectedUploadedVideoId === importedVideo.id
              ? importedVideo.id
              : currentStoryboard.currentVideoAssetVersionId,
        };
        const nextStoryboard = {
          ...currentStoryboard,
          uploadedVideos,
          selectedUploadedVideoId,
          videoStatus: "ready",
          previewVideo: selectedUploadedVideoId === importedVideo.id ? importedVideo.src : currentStoryboard.previewVideo ?? null,
          previewThumbnailUrl:
            selectedUploadedVideoId === importedVideo.id
              ? (importedVideo.thumbnailSrc ?? null)
              : currentStoryboard.previewThumbnailUrl ?? null,
          currentVideoAssetVersionId:
            selectedUploadedVideoId === importedVideo.id
              ? importedVideo.id
              : currentStoryboard.currentVideoAssetVersionId,
        };
        return {
          ...nextStoryboard,
          previewUrl: resolveStoryboardCombinedPreviewUrl(nextStoryboard),
        };
      });
      hydrateStoryboardVideoPreview(workbench, storyboardId, importedVideo.id, importedVideo.src);
    });
    return;
  }

}

function isStoryboardVideoPending(workbench, storyboardId, videoId) {
  return Boolean(
    getActiveStoryboards(workbench)
      .find((storyboard) => storyboard.id === storyboardId)
      ?.uploadedVideos?.some((video) => video.id === videoId && video.status === "uploading"),
  );
}

function cancelStoryboardVideoUpload(workbench, storyboardId, videoId) {
  if (!storyboardId || !videoId) {
    return;
  }

  const task = workbench.uploadTasks.get(videoId);
  if (task) {
    window.clearInterval(task.intervalId);
    if (task.src && String(task.src).startsWith("blob:")) {
      URL.revokeObjectURL(task.src);
    }
    workbench.uploadTasks.delete(videoId);
  }

  updateStoryboardById(workbench, storyboardId, (storyboard) => {
    const uploadedVideos = (storyboard.uploadedVideos ?? []).filter((video) => video.id !== videoId);
    if (uploadedVideos.length === (storyboard.uploadedVideos ?? []).length) {
      return storyboard;
    }
    const selectedUploadedVideoId =
      storyboard.selectedUploadedVideoId === videoId
        ? uploadedVideos.find((video) => video.status === "ready")?.id ?? uploadedVideos[0]?.id ?? null
        : storyboard.selectedUploadedVideoId;
    const selectedVideo =
      uploadedVideos.find((video) => video.id === selectedUploadedVideoId && video.status === "ready") ?? null;
    const nextStoryboard = {
      ...storyboard,
      uploadedVideos,
      selectedUploadedVideoId,
      videoStatus: uploadedVideos.some((video) => video.status === "ready") ? "ready" : "empty",
      previewVideo: storyboard.selectedUploadedVideoId === videoId ? selectedVideo?.src ?? null : storyboard.previewVideo,
      previewThumbnailUrl:
        storyboard.selectedUploadedVideoId === videoId ? selectedVideo?.thumbnailSrc ?? null : storyboard.previewThumbnailUrl,
    };
    return {
      ...nextStoryboard,
      previewUrl: resolveStoryboardCombinedPreviewUrl(nextStoryboard),
    };
  });
}

async function selectStoryboardUploadedVideo(workbench, storyboardId, videoId) {
  if (!storyboardId || !videoId) {
    return;
  }

  const storyboard = getActiveStoryboards(workbench).find((item) => item.id === storyboardId);
  const selectedVideo = (storyboard?.uploadedVideos ?? []).find(
    (video) => video.id === videoId && video.status === "ready",
  );
  if (!selectedVideo) {
    return;
  }

  const applyLocalSelection = () => {
    updateStoryboardById(workbench, storyboardId, (currentStoryboard) => {
      const currentSelectedVideo = (currentStoryboard.uploadedVideos ?? []).find(
        (video) => video.id === videoId && video.status === "ready",
      );
      if (!currentSelectedVideo) {
        return currentStoryboard;
      }
      const nextStoryboard = {
        ...currentStoryboard,
        selectedUploadedVideoId: videoId,
        previewVideo: currentSelectedVideo.src,
        previewThumbnailUrl: currentSelectedVideo.thumbnailSrc ?? null,
        currentVideoAssetVersionId: videoId,
      };
      return {
        ...nextStoryboard,
        previewUrl: resolveStoryboardCombinedPreviewUrl(nextStoryboard),
      };
    });
  };

  if (storyboard?.linkedShotId && typeof workbench.api?.updateShot === "function") {
    await runAction(workbench, "正在设置分镜视频...", async () => {
      await workbench.api.updateShot({
        shotId: storyboard.linkedShotId,
        currentVideoAssetVersionId: videoId,
      });
      applyLocalSelection();
    });
    render(workbench);
    hydrateStoryboardVideoPreview(workbench, storyboardId, videoId, selectedVideo.src);
    return;
  }

  applyLocalSelection();
  render(workbench);
  hydrateStoryboardVideoPreview(workbench, storyboardId, videoId, selectedVideo.src);
}

async function setStoryboardVideoResult(workbench, storyboardId, videoId, preferredVideo = null, prompt = "") {
  const storyboard = getActiveStoryboards(workbench).find((item) => item.id === storyboardId);
  const selectedVideo =
    (preferredVideo && preferredVideo.id === videoId && preferredVideo.status === "ready"
      ? preferredVideo
      : null) ??
    (storyboard?.uploadedVideos ?? []).find(
      (video) => video.id === videoId && video.status === "ready",
    );
  if (!selectedVideo) {
    return;
  }
  if (
    isRealEpisodeWorkbench(workbench) &&
    typeof workbench.api.setStoryboardVideo === "function" &&
    isUuidLike(storyboardId) &&
    isUuidLike(videoId)
  ) {
    await runAction(workbench, "正在设置分镜视频...", async () => {
      let savedVideoSrc = selectedVideo.src;
      let savedVideoId = videoId;
      let savedThumbnailSrc = selectedVideo.thumbnailSrc ?? null;
      const result = await workbench.api.setStoryboardVideo(
        workbench.ui.selectedEpisodeId,
        storyboardId,
        {
          assetVersionId: selectedVideo.assetVersionId ?? videoId,
          storageObjectId: selectedVideo.storageObjectId ?? null,
          sourceUrl: selectedVideo.src ?? selectedVideo.url ?? null,
          thumbnailUrl: selectedVideo.thumbnailSrc ?? null,
        },
      );
      updateStoryboardById(workbench, storyboardId, (currentStoryboard) => {
        const file = result?.file ?? {};
        const src =
          result?.storyboard?.currentVideoUrl ??
          file.sourceUrl ??
          file.previewUrl ??
          selectedVideo.src;
        savedVideoSrc = src;
        savedVideoId = result?.storyboard?.currentVideoFileId ?? videoId;
        savedThumbnailSrc =
          result?.storyboard?.currentVideoThumbnailUrl ??
          file.thumbnailUrl ??
          selectedVideo.thumbnailSrc ??
          null;
        const nextStoryboard = {
          ...currentStoryboard,
          selectedUploadedVideoId: savedVideoId,
          previewVideo: src,
          previewThumbnailUrl:
            savedThumbnailSrc,
          currentVideoAssetVersionId: savedVideoId,
          pendingCurrentVideoAssetVersionId: savedVideoId,
          pendingCurrentVideoSourceUrl: src,
          pendingCurrentVideoThumbnailUrl: savedThumbnailSrc,
          videoStatus: "ready",
          uploadedVideos: mergeStoryboardUploadedVideos(currentStoryboard.uploadedVideos ?? [], [
            {
              ...selectedVideo,
              id: savedVideoId,
              src,
              storageObjectId: file.storageObjectId ?? selectedVideo.storageObjectId ?? null,
              thumbnailSrc: savedThumbnailSrc,
              status: "ready",
            },
          ]),
        };
        return {
          ...nextStoryboard,
          previewUrl: resolveStoryboardCombinedPreviewUrl(nextStoryboard),
        };
      });
      if (workbench.ui.selectedEpisodeId && typeof workbench.api?.listStoryboards === "function") {
        await loadEpisodeStoryboardsForWorkbench(workbench, workbench.ui.selectedEpisodeId);
        updateStoryboardById(workbench, storyboardId, (currentStoryboard) => {
          const persistedVideo =
            (currentStoryboard.uploadedVideos ?? []).find(
              (item) => item.id === savedVideoId && item.status === "ready",
            ) ??
            (currentStoryboard.uploadedVideos ?? []).find(
              (item) => item.status === "ready" && item.src === savedVideoSrc,
            ) ??
            null;
          const nextVideoId = persistedVideo?.id ?? savedVideoId;
          const nextStoryboard = {
            ...currentStoryboard,
            selectedUploadedVideoId: nextVideoId,
            currentVideoAssetVersionId: nextVideoId,
            previewVideo: persistedVideo?.src ?? savedVideoSrc ?? currentStoryboard.previewVideo ?? null,
            previewThumbnailUrl:
              persistedVideo?.thumbnailSrc ?? savedThumbnailSrc ?? currentStoryboard.previewThumbnailUrl ?? null,
            videoStatus: "ready",
            pendingCurrentVideoAssetVersionId: nextVideoId,
            pendingCurrentVideoSourceUrl: persistedVideo?.src ?? savedVideoSrc ?? null,
            pendingCurrentVideoThumbnailUrl:
              persistedVideo?.thumbnailSrc ?? savedThumbnailSrc ?? currentStoryboard.previewThumbnailUrl ?? null,
            uploadedVideos: mergeStoryboardUploadedVideos(currentStoryboard.uploadedVideos ?? [], [
              {
                ...selectedVideo,
                ...(persistedVideo ?? {}),
                id: nextVideoId,
                src: persistedVideo?.src ?? savedVideoSrc,
                storageObjectId:
                  persistedVideo?.storageObjectId ??
                  selectedVideo.storageObjectId ??
                  null,
                thumbnailSrc: persistedVideo?.thumbnailSrc ?? savedThumbnailSrc ?? null,
                status: "ready",
              },
            ]),
          };
          return {
            ...nextStoryboard,
            previewUrl: resolveStoryboardCombinedPreviewUrl(nextStoryboard),
          };
        });
      }
      applyStoryboardResultPrompt(workbench, storyboardId, prompt);
      persistWorkbenchState(workbench);
      hydrateStoryboardVideoPreview(workbench, storyboardId, savedVideoId, savedVideoSrc);
    });
    return;
  }
  await selectStoryboardUploadedVideo(workbench, storyboardId, videoId);
  applyStoryboardResultPrompt(workbench, storyboardId, prompt);
  persistWorkbenchState(workbench);
  render(workbench);
}

async function setStoryboardImageResult(workbench, storyboardId, imageId, prompt = "", imageOverride = null) {
  const storyboard = getActiveStoryboards(workbench).find((item) => item.id === storyboardId);
  const image = imageOverride?.src ? imageOverride : findStoryboardImage(storyboard, imageId);
  const imageAssetVersionId = image?.assetVersionId ?? (isUuidLike(image?.id) ? image.id : null);
  const imageStorageObjectId = image?.storageObjectId ?? null;
  if (!storyboardId || !image) {
    workbench.ui.toast = "当前没有可设置的分镜图片。";
    render(workbench);
    return;
  }
  if (
    isRealEpisodeWorkbench(workbench) &&
    typeof workbench.api.setStoryboardImage === "function" &&
    isUuidLike(storyboardId) &&
    (isUuidLike(imageAssetVersionId) || isUuidLike(imageStorageObjectId))
  ) {
    await runAction(workbench, "正在设置分镜图片...", async () => {
      const result = await workbench.api.setStoryboardImage(
        workbench.ui.selectedEpisodeId,
        storyboardId,
        {
          assetVersionId: isUuidLike(imageAssetVersionId) ? imageAssetVersionId : null,
          storageObjectId: isUuidLike(imageStorageObjectId) ? imageStorageObjectId : null,
        },
      );
      const file = result?.file ?? {};
      updateStoryboardById(workbench, storyboardId, (currentStoryboard) => {
        const src = file.previewUrl ?? image.src;
        return {
          ...currentStoryboard,
          currentImageAssetVersionId: result?.storyboard?.currentImageFileId ?? image.id,
          previewImageUrl: src,
          previewUrl: src,
          imageStatus: "ready",
          uploadedImages: [
            ...(currentStoryboard.uploadedImages ?? []).filter((item) => item.id !== image.id),
            {
              ...image,
              id: result?.storyboard?.currentImageFileId ?? image.id,
              src,
              storageObjectId: file.storageObjectId ?? image.storageObjectId ?? null,
              status: "ready",
            },
          ],
        };
      });
      applyStoryboardResultPrompt(workbench, storyboardId, prompt);
      persistWorkbenchState(workbench);
    });
    return;
  }
  updateStoryboardById(workbench, storyboardId, (currentStoryboard) => ({
    ...currentStoryboard,
    currentImageAssetVersionId: image.id,
    previewImageUrl: image.src,
    previewUrl: image.src,
    imageStatus: "ready",
  }));
  applyStoryboardResultPrompt(workbench, storyboardId, prompt);
  persistWorkbenchState(workbench);
  render(workbench);
}

async function createEpisodeExportPreview(workbench) {
  return createEpisodeExportPreviewWithKind(workbench, "mp4");
}

async function createEpisodeExportPreviewWithKind(workbench, exportKind = "mp4") {
  const fallbackPreview = async () => {
    const preview = await workbench.api.previewExport();
    return {
      ...preview,
      export: {
        ...(preview?.export ?? {}),
        kind: exportKind,
      },
    };
  };
  if (
    isRealEpisodeWorkbench(workbench) &&
    typeof workbench.api.createEpisodeExportTask === "function"
  ) {
    const storyboards = getActiveStoryboards(workbench);
    const hasIncompleteStoryboard = storyboards.some((storyboard) => {
      const hasVideo =
        Boolean(storyboard?.previewVideo) ||
        Boolean(storyboard?.currentVideoAssetVersionId) ||
        (storyboard?.uploadedVideos ?? []).some((item) => item?.status === "ready" && item?.src);
      return !hasVideo;
    });
    if (hasIncompleteStoryboard) {
      const error = new Error("还有分镜未完成，暂时无法导出");
      error.code = "storyboard_export_blocked";
      throw error;
    }
    const exportableVideos = storyboards.flatMap((storyboard) =>
      (storyboard.uploadedVideos ?? []).filter(
        (item) =>
          item?.status === "ready" &&
          (item.storageObjectId || item.assetVersionId || isUuidLike(item.id)),
      ),
    );
    const selectedVideo =
      storyboards
        .map((storyboard) =>
          (storyboard.uploadedVideos ?? []).find(
            (item) =>
              item?.status === "ready" &&
              item.id === (storyboard.selectedUploadedVideoId ?? storyboard.currentVideoAssetVersionId) &&
              (item.storageObjectId || item.assetVersionId || isUuidLike(item.id)),
            ) ?? null,
        )
        .find(Boolean) ?? null;
    const latestGeneratedVideo =
      (workbench.ui.videoGenerationResult?.fixedVideos ?? []).find(
        (item) =>
          item &&
          (item.assetVersionId || item.storageObjectId || isUuidLike(item.id)) &&
          readPublicGenerationMediaUrl(item.src, item.url),
      ) ??
      (readPublicGenerationMediaUrl(workbench.ui.videoGenerationResult?.result?.videoUrl)
        ? {
            id:
              workbench.ui.videoGenerationResult?.result?.assetVersionId ??
              workbench.ui.videoGenerationResult?.result?.storageObjectId ??
              workbench.ui.videoGenerationResult?.taskId ??
              null,
            assetVersionId: workbench.ui.videoGenerationResult?.result?.assetVersionId ?? null,
            storageObjectId: workbench.ui.videoGenerationResult?.result?.storageObjectId ?? null,
            src: readPublicGenerationMediaUrl(workbench.ui.videoGenerationResult?.result?.videoUrl),
            url: readPublicGenerationMediaUrl(workbench.ui.videoGenerationResult?.result?.videoUrl),
          }
        : null);
    const exportCandidate =
      latestGeneratedVideo ??
      selectedVideo ??
      exportableVideos.find((item) => item.storageObjectId || item.assetVersionId || isUuidLike(item.id)) ??
      null;
    if (!exportCandidate) {
      const error = new Error("还有分镜未完成，暂时无法导出");
      error.code = "storyboard_export_blocked";
      throw error;
    }
    const result = await workbench.api.createEpisodeExportTask(workbench.ui.selectedEpisodeId, {
      assetVersionId: exportCandidate.assetVersionId ?? exportCandidate.id,
      storageObjectId: exportCandidate.storageObjectId ?? null,
      exportType: exportKind,
    });
    return {
      exportRecord: result?.exportTask ?? null,
      export: {
        status: result?.exportTask?.status ?? "ready",
        signedUrl: result?.exportTask?.downloadUrl ?? null,
        sourceUrl: result?.exportTask?.sourceUrl ?? null,
        workflowId: result?.exportTask?.workflowId ?? null,
        kind: exportKind,
      },
    };
  }
  return fallbackPreview();
}

function resolveExportPreviewDownloadUrl(exportPreviewResult) {
  return (
    exportPreviewResult?.platform?.signedUrl ??
    exportPreviewResult?.export?.signedUrl ??
    exportPreviewResult?.export?.url ??
    ""
  );
}

function resolveEpisodeExportModalError(error) {
  const code = String(error?.code ?? error?.errorCode ?? "");
  if (code === "storyboard_export_blocked" || code === "storyboard_media_incomplete") {
    return "请确保所有分镜都已生成图片或者视频";
  }
  return friendlyError(error);
}

async function clearStoryboardUploadedVideoSelection(workbench, storyboardId) {
  if (!storyboardId) {
    return;
  }

  const storyboard = getActiveStoryboards(workbench).find((item) => item.id === storyboardId);
  if (!storyboard?.selectedUploadedVideoId) {
    return;
  }

  const applyLocalClear = () => {
    updateStoryboardById(workbench, storyboardId, (currentStoryboard) => {
      if (!currentStoryboard.selectedUploadedVideoId) {
        return currentStoryboard;
      }
      const nextStoryboard = {
        ...currentStoryboard,
        selectedUploadedVideoId: null,
        previewVideo: null,
        previewThumbnailUrl: null,
        currentVideoAssetVersionId: null,
      };
      return {
        ...nextStoryboard,
        previewUrl: resolveStoryboardCombinedPreviewUrl(nextStoryboard),
      };
    });
  };

  if (storyboard.linkedShotId) {
    await runAction(workbench, "正在取消分镜视频选择...", async () => {
      await workbench.api.updateShot({
        shotId: storyboard.linkedShotId,
        currentVideoAssetVersionId: null,
      });
      applyLocalClear();
    });
    return;
  }

  applyLocalClear();
  render(workbench);
}

function updateStoryboardById(workbench, storyboardId, updater) {
  updateActiveStoryboards(workbench, (storyboard) =>
    storyboard.id === storyboardId ? updater(storyboard) : storyboard,
  );
}

async function ensureStoryboardShot(workbench, storyboardId) {
  const storyboard = getActiveStoryboards(workbench).find((item) => item.id === storyboardId);
  if (!storyboard || storyboard.linkedShotId || !workbench.state?.project?.id) {
    return storyboard ?? null;
  }

  const episodeId =
    workbench.ui.projectPanelMode === "episode-workbench"
      ? workbench.ui.selectedEpisodeId ?? "episode-primary"
      : "episode-primary";
  const existing = getEpisodeStoryboards(workbench, episodeId);
  const nextIndex =
    existing.find((item) => item.id === storyboardId)?.index ??
    existing.length + 1;
  const episodeRecord = getDetailEpisodes(workbench.state).find((item) => item?.id === episodeId) ?? null;
  const result = await workbench.api.createShot({
    projectId: workbench.state?.project?.id ?? workbench.state?.projectDetail?.project?.id ?? null,
    episodeId: episodeId === "episode-primary" ? null : episodeId,
    episodeTitle: episodeId === "episode-primary" ? null : (episodeRecord?.title ?? null),
    title: storyboard.title || String(nextIndex),
    description: storyboard.description || "",
  });
  updateStoryboardById(workbench, storyboardId, (currentStoryboard) => ({
    ...currentStoryboard,
    id: result.shot?.id ? `storyboard-${result.shot.id}` : currentStoryboard.id,
    linkedShotId: result.shot?.id ?? currentStoryboard.linkedShotId ?? null,
    title: result.shot?.title ?? currentStoryboard.title,
    description: result.shot?.description ?? currentStoryboard.description,
  }));
  if (workbench.ui.selectedStoryboardId === storyboardId && result.shot?.id) {
    workbench.ui.selectedStoryboardId = `storyboard-${result.shot.id}`;
  }
  appendCreatedShotToState(workbench, result.shot);
  return getActiveStoryboards(workbench).find((item) => item.linkedShotId === result.shot?.id) ?? storyboard;
}

function applyPostRenderEffects(workbench) {
  syncEpisodeWorkbenchLayoutVars(workbench);
  positionPromptMentionPreview(workbench);
  scheduleSelectedAssetGenerationPolling(workbench, "image");
  syncProjectAssetGenerationPollingForCurrentView(workbench);
  const episodeWorkbenchScrollTarget = workbench.ui.episodeWorkbenchScrollTarget ?? null;
  const episodeWorkbenchConversationScrollMode = workbench.ui.episodeWorkbenchConversationScrollMode ?? null;
  const shouldPinEpisodeWorkbenchConversation = shouldKeepEpisodeWorkbenchConversationPinned(workbench);
  if (
    episodeWorkbenchScrollTarget &&
    workbench.ui.projectPanelMode === "episode-workbench" &&
    (workbench.ui.museScopeMode ?? "assets") === "assets"
  ) {
    const scrollContainer = workbench.root.querySelector(".episode-replica-left");
    const targetSection = workbench.root.querySelector(
      `[data-asset-section="${escapeAttributeSelector(episodeWorkbenchScrollTarget)}"]`,
    );
    if (scrollContainer && targetSection) {
      const stickyHead = workbench.root.querySelector(".episode-replica-asset-toolbar-head");
      const stickyOffset = stickyHead?.getBoundingClientRect().height ?? 0;
      const offsetTop =
        targetSection.getBoundingClientRect().top -
        scrollContainer.getBoundingClientRect().top +
        scrollContainer.scrollTop -
        stickyOffset;
      scrollContainer.scrollTo({
        top: Math.max(0, offsetTop),
        behavior: "smooth",
      });
    }
    workbench.ui.episodeWorkbenchScrollTarget = null;
  }

  if (
    (
      episodeWorkbenchConversationScrollMode === "latest" ||
      episodeWorkbenchConversationScrollMode === "bottom" ||
      shouldPinEpisodeWorkbenchConversation
    ) &&
    workbench.ui.projectPanelMode === "episode-workbench"
  ) {
    const conversationContainer = workbench.root.querySelector(".episode-replica-stage-body");
    const latestConversationEntry = conversationContainer?.querySelector(
      [
        ".episode-replica-asset-conversation-entry:last-of-type",
        ".episode-replica-storyboard-conversation-list > .episode-replica-generated-stage:last-of-type",
        ".episode-replica-generated-stage.visible:last-of-type",
      ].join(", "),
    );
    if (episodeWorkbenchConversationScrollMode === "latest" && latestConversationEntry) {
      latestConversationEntry.scrollIntoView({ block: "end", inline: "nearest", behavior: "auto" });
    } else if (conversationContainer) {
      conversationContainer.scrollTop = conversationContainer.scrollHeight;
    }
    workbench.ui.episodeWorkbenchConversationScrollStickyUntil = Date.now() + 1800;
    keepEpisodeWorkbenchConversationPinnedToBottom(workbench);
    workbench.ui.episodeWorkbenchConversationScrollMode = null;
  }

  syncMembershipPaymentCountdown(workbench);

  const pendingIds = workbench.ui.assetLibraryPendingFocusAssetIds ?? [];
  if (!pendingIds.length) {
    return;
  }
  if (workbench.ui.projectPanelMode !== "workspace" || workbench.ui.projectInteriorSection !== "assets") {
    return;
  }

  const focusTarget = pendingIds
    .map((assetId) => workbench.root.querySelector(`[data-imported-asset-id="${escapeAttributeSelector(assetId)}"]`))
    .find(Boolean);

  if (!focusTarget) {
    return;
  }

  focusTarget.scrollIntoView({ block: "center", inline: "nearest", behavior: "smooth" });
  focusTarget.focus({ preventScroll: true });
  workbench.ui.assetLibraryPendingFocusAssetIds = [];
}

function disposeHomeLiquidEther(workbench) {
  workbench.homeLiquidEtherToken = Symbol("liquid-ether-disposed");
  if (!workbench.homeLiquidEther) {
    return;
  }
  workbench.homeLiquidEther.dispose();
  workbench.homeLiquidEther = null;
}

function disposeHomeLightfall(workbench) {
  workbench.homeLightfallToken = Symbol("lightfall-disposed");
  if (!workbench.homeLightfall) {
    return;
  }
  workbench.homeLightfall.dispose();
  workbench.homeLightfall = null;
}

function updateHomeHeroPointerAura(workbench, event) {
  const eventTarget = resolveEventElement(event.target);
  const hero = eventTarget?.closest?.(".home-hero") ?? workbench.root.querySelector(".home-hero");
  if (!hero || typeof hero.getBoundingClientRect !== "function") {
    return;
  }

  const rect = hero.getBoundingClientRect();
  if (!rect.width || !rect.height) {
    return;
  }

  const x = Math.min(100, Math.max(0, ((event.clientX - rect.left) / rect.width) * 100));
  const y = Math.min(100, Math.max(0, ((event.clientY - rect.top) / rect.height) * 100));
  hero.style.setProperty("--home-pointer-x", `${x.toFixed(2)}%`);
  hero.style.setProperty("--home-pointer-y", `${y.toFixed(2)}%`);
}

function syncHomeLiquidEther(workbench) {
  if (typeof window === "undefined" || typeof document === "undefined") {
    return;
  }

  const mount = workbench.root.querySelector("[data-liquid-ether-root]");
  if (!mount) {
    disposeHomeLiquidEther(workbench);
    return;
  }

  if (workbench.homeLiquidEther?.container === mount) {
    return;
  }

  if (workbench.homeLiquidEther) {
    workbench.homeLiquidEther.dispose();
    workbench.homeLiquidEther = null;
  }

  const token = Symbol("liquid-ether-mount");
  workbench.homeLiquidEtherToken = token;

  import("./liquid-ether.js?liquid-ether=3")
    .then(({ mountLiquidEther }) => {
      if (workbench.homeLiquidEtherToken !== token || !mount.isConnected) {
        return;
      }
      const effectTheme = resolveHomeEffectThemeOptions(workbench);
      const instance = mountLiquidEther(mount, {
        ...effectTheme.liquidEther,
        mouseForce: 18,
        cursorSize: 120,
        resolution: 0.42,
        isViscous: false,
        iterationsPoisson: 28,
        autoDemo: true,
        autoSpeed: 0.42,
        autoIntensity: 2.35,
        autoResumeDelay: 1200,
        autoRampDuration: 0.7,
      });
      if (workbench.homeLiquidEtherToken !== token || !mount.isConnected) {
        instance.dispose();
        return;
      }
      mount.dataset.liquidEtherState = "ready";
      workbench.homeLiquidEther = instance;
    })
    .catch((error) => {
      mount.dataset.liquidEtherState = "failed";
      console.warn("LiquidEther failed to mount", error);
    });
}

function syncHomeLightfall(workbench) {
  if (typeof window === "undefined" || typeof document === "undefined") {
    return;
  }

  const mount = workbench.root.querySelector("[data-lightfall-root]");
  if (!mount) {
    disposeHomeLightfall(workbench);
    return;
  }

  if (workbench.homeLightfall?.container === mount) {
    return;
  }

  if (workbench.homeLightfall) {
    workbench.homeLightfall.dispose();
    workbench.homeLightfall = null;
  }

  const token = Symbol("lightfall-mount");
  workbench.homeLightfallToken = token;

  import("./lightfall.js?home-lightfall=1")
    .then(({ mountHomeLightfall }) => {
      if (workbench.homeLightfallToken !== token || !mount.isConnected) {
        return;
      }
      const effectTheme = resolveHomeEffectThemeOptions(workbench);
      const instance = mountHomeLightfall(mount, {
        streakCount: 2,
        streakWidth: 1,
        streakLength: 1,
        twinkle: 1,
        glow: 1,
        zoom: 3,
        opacity: 1,
        mouseInteraction: true,
        mouseStrength: 0.5,
        mouseRadius: 1,
        maxDpr: 1.35,
        ...effectTheme.lightfall,
      });
      if (workbench.homeLightfallToken !== token || !mount.isConnected) {
        instance.dispose();
        return;
      }
      mount.dataset.lightfallState = mount.dataset.lightfallState || "ready";
      workbench.homeLightfall = instance;
    })
    .catch((error) => {
      mount.dataset.lightfallState = "failed";
      console.warn("HomeLightfall failed to mount", error);
    });
}

function updateStoryboardVideoById(workbench, storyboardId, videoId, updater) {
  updateStoryboardById(workbench, storyboardId, (storyboard) => ({
    ...storyboard,
    uploadedVideos: (storyboard.uploadedVideos ?? []).map((video) =>
      video.id === videoId ? updater(video) : video,
    ),
    selectedUploadedVideoId: storyboard.selectedUploadedVideoId ?? null,
  }));
}

function updateActiveStoryboards(workbench, updater) {
  const scopedUpdate = applyStoryboardScopeUpdate(
    {
      storyboards: workbench.ui.storyboards ?? [],
      episodeStoryboardMap: workbench.ui.episodeStoryboardMap ?? {},
      projectPanelMode: workbench.ui.projectPanelMode ?? "library",
      selectedEpisodeId: workbench.ui.selectedEpisodeId ?? null,
    },
    updater,
  );
  workbench.ui.storyboards = scopedUpdate.storyboards;
  workbench.ui.episodeStoryboardMap = scopedUpdate.episodeStoryboardMap;
  syncSelectedStoryboardId(workbench, scopedUpdate.activeStoryboards);
  workbench.ui.selectedStoryboard = getSelectedStoryboard(
    scopedUpdate.activeStoryboards,
    workbench.ui.selectedStoryboardId,
  );
}

function hydrateVideoDurationLabel(workbench, storyboardId, videoId, src) {
  if (typeof document === "undefined") {
    return;
  }
  const probe = document.createElement("video");
  probe.preload = "metadata";
  probe.src = src;
  probe.muted = true;
  probe.onloadedmetadata = () => {
    updateStoryboardVideoById(workbench, storyboardId, videoId, (video) => ({
      ...video,
      durationLabel: formatDurationLabel(probe.duration),
    }));
    render(workbench);
  };
}

async function hydrateStoryboardVideoPreview(workbench, storyboardId, videoId, src) {
  hydrateVideoDurationLabel(workbench, storyboardId, videoId, src);
  const thumbnailSrc = await captureVideoThumbnail(src, 2500);
  if (!thumbnailSrc) {
    return;
  }

  updateStoryboardVideoById(workbench, storyboardId, videoId, (video) => ({
    ...video,
    thumbnailSrc,
  }));
  updateStoryboardById(workbench, storyboardId, (storyboard) => ({
    ...storyboard,
    previewThumbnailUrl:
      storyboard.selectedUploadedVideoId === videoId
        ? thumbnailSrc
        : storyboard.previewThumbnailUrl ?? null,
  }));
  render(workbench);
}

function formatDurationLabel(value) {
  const safeSeconds = Math.max(0, Math.round(Number.isFinite(value) ? value : 10));
  const minutes = String(Math.floor(safeSeconds / 60)).padStart(2, "0");
  const seconds = String(safeSeconds % 60).padStart(2, "0");
  return `${minutes}:${seconds}`;
}

function formatDurationLabelFromMs(value) {
  return formatDurationLabel(Number(value ?? 10_000) / 1000);
}

async function captureVideoThumbnail(src, timeoutMs = 2500) {
  if (typeof document === "undefined") {
    return null;
  }

  return new Promise((resolve) => {
    const probe = document.createElement("video");
    probe.preload = "auto";
    probe.src = src;
    probe.muted = true;
    probe.playsInline = true;
    probe.crossOrigin = "anonymous";
    let settled = false;
    let timeoutId = null;

    const settle = (value) => {
      if (settled) {
        return;
      }
      settled = true;
      cleanup();
      resolve(value);
    };

    const cleanup = () => {
      if (timeoutId !== null) {
        window.clearTimeout(timeoutId);
      }
      probe.onloadeddata = null;
      probe.onerror = null;
      probe.pause();
      probe.removeAttribute("src");
      probe.load();
    };

    timeoutId = window.setTimeout(() => settle(null), timeoutMs);

    probe.onloadeddata = () => {
      try {
        const canvas = document.createElement("canvas");
        const width = probe.videoWidth || 320;
        const height = probe.videoHeight || 180;
        canvas.width = width;
        canvas.height = height;
        const context = canvas.getContext("2d");
        if (!context) {
          settle(null);
          return;
        }
        context.drawImage(probe, 0, 0, width, height);
        const thumbnailSrc = canvas.toDataURL("image/jpeg", 0.82);
        settle(thumbnailSrc);
      } catch (_error) {
        settle(null);
      }
    };

    probe.onerror = () => {
      settle(null);
    };
  });
}

