function applyManualAssetDraftDefaults(workbench, kind, assetId, name) {
  if (!assetId) {
    return;
  }
  const description = buildManualAssetDefaultDescription(kind, name);
  const groups = cloneImportedAssets(workbench.ui.importedAssets);
  groups[kind] = (groups[kind] ?? []).map((item) => {
    if (item.id !== assetId && item.assetId !== assetId) {
      return item;
    }
    return {
      ...item,
      description: item.description || description,
      voiceName: kind === "character" ? (item.voiceName ?? "") : item.voiceName,
      voiceSource: kind === "character" ? (item.voiceSource ?? "custom") : item.voiceSource,
    };
  });
  workbench.ui.importedAssets = groups;
}

function resolveEventElement(target) {
  if (target instanceof Element) {
    return target;
  }
  if (target instanceof Node) {
    return target.parentElement;
  }
  return null;
}

export function hasActiveWorkbenchTextSelection(target, selection = globalThis.window?.getSelection?.()) {
  const doc = target?.ownerDocument ?? globalThis.document ?? null;
  const activeElement = doc?.activeElement ?? null;
  if (activeElement?.matches?.("textarea, input")) {
    const selectionStart = Number(activeElement.selectionStart ?? 0);
    const selectionEnd = Number(activeElement.selectionEnd ?? selectionStart);
    if (selectionEnd > selectionStart) {
      return true;
    }
  }
  if (!selection || selection.isCollapsed) {
    return false;
  }
  const selectedText = String(selection.toString?.() ?? "").trim();
  if (!selectedText) {
    return false;
  }
  if (target && selection.rangeCount > 0 && typeof selection.getRangeAt === "function") {
    try {
      const range = selection.getRangeAt(0);
      if (range && typeof range.intersectsNode === "function" && !range.intersectsNode(target)) {
        return false;
      }
    } catch {
      return false;
    }
  }
  return true;
}

function findScopedInput(root, trigger, selector) {
  const scopes = [
    trigger?.closest?.("[data-upload-panel]"),
    trigger?.closest?.(".console-block"),
    trigger?.closest?.(".stage-video-library"),
    trigger?.closest?.(".stage-image-library"),
    trigger?.closest?.(".cinematic-stage-empty"),
    trigger?.closest?.(".project-gallery-poster"),
    root,
  ].filter(Boolean);

  for (const scope of scopes) {
    const match = scope.querySelector(selector);
    if (match) {
      return match;
    }
  }

  return null;
}

