function normalizeRoutePath(pathname) {
  const path = String(pathname ?? "/").trim() || "/";
  const normalized = path.replace(/\/+$/, "") || "/";
  if (normalized === "/app.html") {
    return "/";
  }
  return normalized;
}

function readWorkbenchRouteToken(locationLike = globalThis.window?.location) {
  const hashToken = String(locationLike?.hash ?? "").replace(/^#/, "").trim();
  if (hashToken) {
    return hashToken;
  }
  const pathToken = PUBLIC_PATH_TOKENS.get(normalizeRoutePath(locationLike?.pathname));
  return pathToken ?? "";
}

function deriveInitialNavTab(hash, session = {}) {
  const token = String(hash || "").replace(/^#/, "");
  if (!token) {
    return "home";
  }
  if (parseEpisodeRouteToken(token) || parseProjectRouteToken(token)) {
    return "project";
  }
  if (token === "community") {
    return "community";
  }
  if (token === "media-library") {
    return "media-library";
  }
  if (token === "home") {
    return "home";
  }
  if (
    token === "asset-prep-section" ||
    token === "project-workspace" ||
    token === "storyboard-workbench" ||
    token === "episode-workbench" ||
    token === "project"
  ) {
    return "project";
  }
  if (token === "script") {
    return "script";
  }
  if (token === "library") {
    return "library";
  }
  if (token === "tools" || token === "tools-canvas") {
    return "tools";
  }
  if (token === "team" || token.startsWith("team-dashboard")) {
    if (isTeamMemberSession(session)) {
      return "project";
    }
    return "team";
  }
  return "project";
}

const LINGXI_COMMUNITY_STORAGE_KEY = "lingxi-community-board";

function readLingxiCommunityData() {
  const fallback = createDefaultLingxiCommunityData();
  try {
    const parsed = JSON.parse(localStorage.getItem(LINGXI_COMMUNITY_STORAGE_KEY) || "null");
    return {
      posts: normalizeLingxiCommunityPosts(Array.isArray(parsed?.posts) ? parsed.posts : fallback.posts),
      features: normalizeLingxiCommunityFeatures(Array.isArray(parsed?.features) ? parsed.features : fallback.features),
    };
  } catch {
    return fallback;
  }
}

function writeLingxiCommunityData(data) {
  try {
    localStorage.setItem(LINGXI_COMMUNITY_STORAGE_KEY, JSON.stringify({
      posts: Array.isArray(data?.posts) ? data.posts : [],
      features: Array.isArray(data?.features) ? data.features : [],
    }));
  } catch {
    // Keep the community usable even if storage is unavailable.
  }
}

function mergeLingxiCommunityItems(primaryItems = [], nextItems = []) {
  const merged = [];
  const seen = new Set();
  for (const item of [...primaryItems, ...nextItems]) {
    const id = String(item?.id ?? "").trim();
    const key = id || `${String(item?.title ?? "").trim()}::${String(item?.content ?? "").trim()}`;
    if (!key || seen.has(key)) continue;
    seen.add(key);
    merged.push(item);
  }
  return merged;
}

function normalizeLingxiCommunityPosts(posts = []) {
  return posts.map((post) => {
    const likedBy = Array.isArray(post?.likedBy) ? post.likedBy.map(String) : [];
    const comments = Array.isArray(post?.comments)
      ? post.comments.map((comment) => ({
        ...comment,
        replies: Array.isArray(comment?.replies) ? comment.replies : [],
      }))
      : [];
    return {
      ...post,
      userId: String(post?.userId || inferCommunityUserIdFromAuthor(post?.author) || ""),
      likedBy,
      likes: Number(post?.likes ?? likedBy.length ?? 0),
      comments,
    };
  });
}

function normalizeLingxiCommunityFeatures(features = []) {
  return features.map((feature) => ({
    ...feature,
    votes: Number(feature?.votes ?? 0),
    voterIds: Array.isArray(feature?.voterIds) ? feature.voterIds.map(String) : [],
  }));
}

async function loadLingxiCommunityBoard(workbench) {
  if (typeof workbench.api?.getCommunityBoard !== "function") {
    return;
  }
  try {
    const data = await workbench.api.getCommunityBoard();
    writeLingxiCommunityData(data);
    workbench.ui.communityPosts = Array.isArray(data?.posts) ? data.posts : [];
    workbench.ui.communityFeatures = Array.isArray(data?.features) ? data.features : [];
    render(workbench);
  } catch {
    const data = readLingxiCommunityData();
    workbench.ui.communityPosts = data.posts;
    workbench.ui.communityFeatures = data.features;
  }
}

async function loadPersonalMediaLibrarySurface(workbench) {
  if (
    typeof workbench?.api?.getPersonalMediaLibrary !== "function" ||
    typeof workbench?.api?.getPersonalMediaLibrarySummary !== "function"
  ) {
    workbench.ui.personalMediaLibraryError = "当前环境暂不支持个人素材库。";
    workbench.ui.personalMediaLibraryLoading = false;
    render(workbench);
    return;
  }
  const requestId = (workbench.personalMediaLibraryRequestId ?? 0) + 1;
  workbench.personalMediaLibraryRequestId = requestId;
  workbench.ui.personalMediaLibraryLoading = true;
  workbench.ui.personalMediaLibraryError = "";
  render(workbench);
  try {
    const query = {
      media: workbench.ui.personalMediaLibraryMediaFilter ?? "all",
      range: workbench.ui.personalMediaLibraryRangeFilter ?? "all",
      keyword: workbench.ui.personalMediaLibraryKeyword ?? "",
    };
    const [summary, payload] = await Promise.all([
      workbench.api.getPersonalMediaLibrarySummary(query),
      workbench.api.getPersonalMediaLibrary({
        ...query,
        page: workbench.ui.personalMediaLibraryPage ?? 1,
        pageSize: PERSONAL_MEDIA_LIBRARY_PAGE_SIZE,
      }),
    ]);
    if (workbench.personalMediaLibraryRequestId !== requestId) {
      return;
    }
    workbench.ui.personalMediaLibrarySummary = summary ?? null;
    workbench.ui.personalMediaLibraryRows = Array.isArray(payload?.data) ? payload.data : [];
    workbench.ui.personalMediaLibraryMeta = payload?.meta ?? {
      page: workbench.ui.personalMediaLibraryPage ?? 1,
      pageSize: PERSONAL_MEDIA_LIBRARY_PAGE_SIZE,
      total: workbench.ui.personalMediaLibraryRows.length,
      totalPages: 1,
    };
  } catch (error) {
    if (workbench.personalMediaLibraryRequestId !== requestId) {
      return;
    }
    workbench.ui.personalMediaLibraryRows = [];
    workbench.ui.personalMediaLibrarySummary = null;
    workbench.ui.personalMediaLibraryMeta = null;
    workbench.ui.personalMediaLibraryError = friendlyError(error) || "素材库加载失败。";
  } finally {
    if (workbench.personalMediaLibraryRequestId === requestId) {
      workbench.ui.personalMediaLibraryLoading = false;
      render(workbench);
    }
  }
}

