export function applyProjectDetail(workbench, detail) {
  const normalizedDetail = normalizeProjectDetailContract(detail);
  if (!normalizedDetail?.project) {
    return;
  }
  const previousEpisodeId = workbench?.ui?.selectedEpisodeId ?? null;
  const shouldPreserveEpisodeAssets =
    workbench?.ui?.projectPanelMode === "episode-workbench" &&
    hasPersistedEpisodeWorkbenchId(workbench, previousEpisodeId);
  workbench.state = {
    ...(workbench.state ?? {}),
    project: normalizedDetail.project,
    script: normalizedDetail.script ?? null,
    shots: normalizedDetail.shots ?? [],
    projectDetail: normalizedDetail,
  };
  workbench.ui.projectDetail = normalizedDetail;
  workbench.ui.exportHistory = normalizedDetail.exportHistory ?? workbench.ui.exportHistory ?? [];
  workbench.ui.projectLibraryAssetsByType = normalizedDetail.assetsByType ?? null;
  if (!shouldPreserveEpisodeAssets) {
    const nextImportedAssets = mapProjectDetailAssets(normalizedDetail.assetsByType, workbench.ui.importedAssets);
    if (workbench?.ui?.projectPanelMode === "episode-workbench") {
      workbench.ui.importedAssets = {
        ...(workbench.ui.importedAssets ?? {}),
        other: nextImportedAssets.other,
      };
    } else {
      workbench.ui.importedAssets = nextImportedAssets;
    }
  }
  workbench.ui.customEpisodes = getDetailEpisodes(workbench.state);
  if (
    workbench?.ui?.projectPanelMode === "episode-workbench" &&
    previousEpisodeId &&
    previousEpisodeId !== "episode-primary" &&
    !hasPersistedEpisodeWorkbenchId(workbench, previousEpisodeId)
  ) {
    workbench.ui.selectedEpisodeId = resolvePersistedEpisodeWorkbenchId(workbench, previousEpisodeId);
    workbench.ui.selectedEpisodeAssetId = null;
    workbench.ui.selectedEpisodeCardId = null;
    workbench.ui.selectedEpisodeAssetIds = [];
    workbench.ui.imageGenerationResult = null;
    workbench.ui.videoGenerationResult = null;
  }
}

function normalizeProjectDetailContract(detail) {
  if (!detail || typeof detail !== "object") {
    return detail;
  }
  const project = detail.project && typeof detail.project === "object"
    ? {
        ...detail.project,
        id: detail.project.id ?? detail.project.projectId ?? null,
        projectId: detail.project.projectId ?? detail.project.id ?? null,
      }
    : detail.project;
  const episodes = Array.isArray(detail.episodes)
    ? detail.episodes.map((episode) => ({
        ...episode,
        id: episode.id ?? episode.episodeId ?? null,
        episodeId: episode.episodeId ?? episode.id ?? null,
        previewUrl: episode.previewUrl ?? episode.previewMedia?.url ?? null,
      }))
    : detail.episodes;
  return {
    ...detail,
    project,
    episodes,
  };
}

function mapEpisodeStoryboardContract(storyboard) {
  const apiStoryboardId =
    firstUuidLikeValue(storyboard?.storyboardId, storyboard?.shotId, storyboard?.linkedShotId, storyboard?.id) ??
    null;
  const storyboardId =
    apiStoryboardId ??
    storyboard?.id ??
    storyboard?.storyboardId ??
    storyboard?.shotId ??
    `storyboard-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
  const previewImageUrl =
    storyboard?.previewImageUrl ??
    storyboard?.currentImageUrl ??
    storyboard?.currentImage?.url ??
    storyboard?.imageUrl ??
    null;
  const previewVideo =
    storyboard?.previewVideo ??
    storyboard?.currentVideoUrl ??
    storyboard?.currentVideo?.url ??
    storyboard?.videoUrl ??
    null;
  const previewThumbnailUrl =
    storyboard?.previewThumbnailUrl ??
    storyboard?.currentVideoThumbnailUrl ??
    storyboard?.currentVideo?.thumbnailUrl ??
    null;
  const generationDrafts = normalizeEpisodeStoryboardGenerationDrafts(storyboard?.generationDrafts);
  const videoDraft = generationDrafts.find((draft) => draft.mode === "video") ?? null;
  const imageDraft = generationDrafts.find((draft) => draft.mode === "image") ?? null;
  const fallbackVideoPrompt = resolveEpisodeStoryboardVideoPrompt(storyboard);
  const fallbackImagePrompt = resolveEpisodeStoryboardImagePrompt(storyboard);
  const resolvedVideoPrompt = videoDraft?.prompt ?? fallbackVideoPrompt;
  const activeDraft = videoDraft ?? imageDraft ?? (
    resolvedVideoPrompt || fallbackImagePrompt
      ? {
          mode: resolvedVideoPrompt ? "video" : "image",
          prompt: resolvedVideoPrompt || fallbackImagePrompt,
          payload: {},
          updatedAt: null,
        }
      : null
  );
  return {
    id: storyboardId,
    linkedShotId: apiStoryboardId ?? storyboard?.linkedShotId ?? storyboard?.shotId ?? storyboard?.storyboardId ?? storyboardId,
    episodeId: storyboard?.episodeId ?? null,
    index: Number(storyboard?.index ?? storyboard?.indexNo ?? storyboard?.sortOrder ?? 1),
    title: storyboard?.title ?? String(storyboard?.indexNo ?? storyboard?.sortOrder ?? 1),
    description: resolvedVideoPrompt || (storyboard?.description ?? storyboard?.sceneAnalysis ?? storyboard?.plotPreview ?? ""),
    sceneAnalysis: storyboard?.sceneAnalysis ?? "",
    plotPreview: storyboard?.plotPreview ?? "",
    previewImageUrl,
    previewVideo,
    previewUrl: previewVideo ?? previewImageUrl,
    previewThumbnailUrl,
    imageStatus: previewImageUrl ? "ready" : "empty",
    videoStatus: previewVideo ? "ready" : "empty",
    currentImageAssetVersionId: storyboard?.currentImageFileId ?? storyboard?.currentImageAssetVersionId ?? null,
    currentVideoAssetVersionId: storyboard?.currentVideoFileId ?? storyboard?.currentVideoAssetVersionId ?? null,
    uploadedImages: previewImageUrl
      ? [{ id: storyboard?.currentImageFileId ?? `${storyboardId}-image`, src: previewImageUrl, status: "ready" }]
      : [],
    uploadedVideos: previewVideo
      ? [{
          id: storyboard?.currentVideoFileId ?? `${storyboardId}-video`,
          src: previewVideo,
          thumbnailSrc: previewThumbnailUrl,
          status: "ready",
        }]
      : [],
    generationDrafts,
    imagePromptDraft: imageDraft,
    videoPromptDraft: videoDraft,
    generationState: {
      ...createEmptyGenerationState(),
      prompt: activeDraft?.prompt ?? "",
      imagePrompt: imageDraft?.prompt ?? fallbackImagePrompt,
      videoPrompt: resolvedVideoPrompt,
    },
  };
}

function resolveEpisodeStoryboardVideoPrompt(storyboard) {
  const candidates = [
    storyboard?.chapterVideoPrompt,
    storyboard?.chapter_video_prompt,
    storyboard?.videoPrompt,
    storyboard?.video_prompt,
    storyboard?.motionPrompt,
    storyboard?.motion_prompt,
    storyboard?.videoPromptDraft?.prompt,
    storyboard?.generationState?.videoPrompt,
    ...(Array.isArray(storyboard?.generationDrafts)
      ? storyboard.generationDrafts
        .filter((draft) => String(draft?.mode ?? "").trim() === "video")
        .map((draft) => draft?.prompt)
      : []),
  ];
  for (const candidate of candidates) {
    const text = String(candidate ?? "").trim();
    if (text) {
      return text;
    }
  }
  const description = String(storyboard?.description ?? "").trim();
  return description.includes("[场景分析]") ||
    description.includes("【场景分析】") ||
    description.includes("[镜头") ||
    description.includes("【镜头") ||
    description.includes("动态视频提示词")
    ? description
    : "";
}

function resolveEpisodeStoryboardImagePrompt(storyboard) {
  const candidates = [
    storyboard?.chapterImagePrompt,
    storyboard?.imagePrompt,
    storyboard?.image_prompt,
    storyboard?.staticImagePrompt,
    storyboard?.static_image_prompt,
    storyboard?.imagePromptDraft?.prompt,
    storyboard?.generationState?.imagePrompt,
    ...(Array.isArray(storyboard?.generationDrafts)
      ? storyboard.generationDrafts
        .filter((draft) => String(draft?.mode ?? "").trim() === "image")
        .map((draft) => draft?.prompt)
      : []),
  ];
  for (const candidate of candidates) {
    const text = String(candidate ?? "").trim();
    if (text) {
      return text;
    }
  }
  return "";
}

function normalizeEpisodeStoryboardGenerationDrafts(drafts) {
  if (!Array.isArray(drafts)) {
    return [];
  }
  return drafts
    .map((draft) => {
      const mode = String(draft?.mode ?? "").trim();
      if (mode !== "image" && mode !== "video" && mode !== "lip_sync") {
        return null;
      }
      return {
        mode,
        prompt: String(draft?.prompt ?? ""),
        payload: draft?.payload && typeof draft.payload === "object" ? draft.payload : {},
        updatedAt: draft?.updatedAt ?? null,
      };
    })
    .filter(Boolean);
}

function mapEpisodeAssetContracts(assets = [], kind) {
  return [...assets].map((asset) => {
    const resolvedPreview = resolvePreferredFixedImageUrl(
      asset?.fixedImageUrl,
      asset?.previewUrl,
      asset?.latestVersion?.previewUrl,
      asset?.latestVersion?.metadata?.fixedImageUrl,
      asset?.latestVersion?.metadata?.previewUrl,
      asset?.sourceUrl,
    );
    return {
      id: asset?.assetId ?? asset?.id ?? `asset-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
      assetId: asset?.assetId ?? asset?.id ?? null,
      name: asset?.name ?? asset?.label ?? "未命名资产",
      preview: resolvedPreview,
      previewUrl: resolvedPreview,
      description: resolveEpisodeAssetDescription(asset),
      kind,
      source: "episode",
      assetSource: "episode",
      voiceId: asset?.voiceId ?? null,
      voiceName: asset?.voiceName ?? "",
      voiceSource: asset?.voiceSource ?? inferEpisodeVoiceSource(asset),
      dubbingConfig: asset?.dubbingConfig ?? null,
      updatedAt: asset?.updatedAt ?? null,
      fixedImageFileId: asset?.fixedImageFileId ?? null,
      fixedImageUrl: resolvedPreview,
      fixedImageStorageObjectId: asset?.fixedImageStorageObjectId ?? null,
    };
  });
}

function resolveEpisodeAssetDescription(asset) {
  return normalizeEpisodeAssetDescriptionText(
    asset?.description ??
      asset?.latestVersion?.metadata?.description ??
      asset?.metadata?.description ??
      asset?.promptPreview ??
      asset?.prompt ??
      "",
  );
}

function mapProjectDetailAssets(assetsByType = {}, existingImportedAssets = null) {
  const otherImageAssets = mapProjectDetailAssetRecords(assetsByType.other?.image, "other", existingImportedAssets?.other?.image);
  const otherVideoAssets = mapProjectDetailAssetRecords(assetsByType.other?.video, "other", existingImportedAssets?.other?.video);
  const explicitAudioAssets = mapProjectDetailAssetRecords(assetsByType.other?.audio, "other", existingImportedAssets?.other?.audio);
  const otherAudioAssets = [
    ...explicitAudioAssets,
    ...otherVideoAssets.filter((asset) => resolveImportedProjectAudioUrl(asset)),
  ];
  return {
    character: mapProjectDetailAssetRecords(assetsByType.character, "character", existingImportedAssets?.character),
    scene: mapProjectDetailAssetRecords(assetsByType.scene, "scene", existingImportedAssets?.scene),
    prop: mapProjectDetailAssetRecords(assetsByType.prop, "prop", existingImportedAssets?.prop),
    other: {
      audio: otherAudioAssets,
      image: otherImageAssets.filter((asset) => !resolveImportedProjectAudioUrl(asset)),
      video: otherVideoAssets.filter((asset) => !resolveImportedProjectAudioUrl(asset)),
    },
  };
}

function mapProjectDetailAssetRecords(assets = [], kind, existingAssets = []) {
  const existingById = new Map(
    (Array.isArray(existingAssets) ? existingAssets : [])
      .map((asset) => [String(asset?.id ?? asset?.assetId ?? "").trim(), asset])
      .filter(([id]) => id),
  );
  return [...assets].filter((asset) => !isTemporaryEpisodeUploadAsset(asset)).map((asset) => {
    const localAsset = existingById.get(String(asset?.id ?? asset?.assetId ?? "").trim()) ?? null;
    const localAssetIsEpisode = [localAsset?.source, localAsset?.assetSource, localAsset?.latestVersion?.metadata?.source]
      .some((source) => String(source ?? "").trim().toLowerCase() === "episode");
    const displaySource = localAssetIsEpisode
      ? "episode"
      : asset.latestVersion?.metadata?.source ?? localAsset?.source ?? "import";
    const localEpisodeDerivedAsset = localAssetIsEpisode || isEpisodeDerivedProjectAsset(asset, localAsset);
    const { generationResult, generationStatus, generationTaskId } = localEpisodeDerivedAsset
      ? { generationResult: null, generationStatus: "", generationTaskId: "" }
      : resolveProjectAssetGenerationSnapshot(asset, localAsset);
    const preview = resolvePreferredFixedImageUrl(
      generationResult?.version?.previewUrl,
      generationResult?.version?.metadata?.previewUrl,
      generationResult?.version?.metadata?.fixedImageUrl,
      generationResult?.result?.imageUrl,
      generationResult?.result?.previewUrl,
      generationResult?.fixedImages?.[0]?.previewUrl,
      generationResult?.fixedImages?.[0]?.url,
      generationResult?.fixedImages?.[0]?.src,
      asset.previewUrl,
      asset.latestVersion?.metadata?.fixedImageUrl,
      asset.latestVersion?.previewUrl,
      asset.latestVersion?.metadata?.previewUrl,
      localAsset?.preview,
      localAsset?.previewUrl,
      localAsset?.fixedImageUrl,
    );
    return {
      id: asset.id,
      assetId: asset.assetId ?? asset.id ?? null,
      name: asset.label ?? asset.assetKey ?? localAsset?.name ?? "未命名资产",
      preview,
      previewUrl: preview,
      fixedImageUrl: preview,
      description: normalizeEpisodeAssetDescriptionText(
        asset.latestVersion?.metadata?.description ?? localAsset?.description ?? asset.assetKey ?? "",
      ),
      kind,
      isMain: Boolean(asset.latestVersion?.metadata?.isMain ?? localAsset?.isMain),
      assetSource: localAssetIsEpisode ? "episode" : asset.latestVersion?.metadata?.source ?? localAsset?.assetSource ?? "import",
      updatedAt: asset.updatedAt ?? asset.latestVersion?.createdAt ?? localAsset?.updatedAt ?? asset.createdAt ?? null,
      latestVersion: asset.latestVersion ?? localAsset?.latestVersion ?? null,
      source: displaySource,
      generationStatus,
      generationTaskId,
      generationResult,
      generationPrompt:
        generationResult?.prompt ??
        asset.latestVersion?.metadata?.generationPrompt ??
        localAsset?.generationPrompt ??
        null,
      generationModel:
        generationResult?.model ??
        asset.latestVersion?.metadata?.generationModel ??
        localAsset?.generationModel ??
        null,
      generationParameters:
        generationResult?.parameters ??
        asset.latestVersion?.metadata?.generationParameters ??
        localAsset?.generationParameters ??
        null,
    };
  });
}

function filterTemporaryEpisodeUploadAssets(assets = []) {
  return (Array.isArray(assets) ? assets : []).filter((asset) => !isTemporaryEpisodeUploadAsset(asset));
}

function isTemporaryEpisodeUploadAsset(asset) {
  const metadata = asset?.latestVersion?.metadata && typeof asset.latestVersion.metadata === "object"
    ? asset.latestVersion.metadata
    : asset?.metadata && typeof asset.metadata === "object"
      ? asset.metadata
      : {};
  const assetKey = String(asset?.assetKey ?? asset?.key ?? asset?.label ?? "").trim().toLowerCase();
  const purpose = String(metadata?.purpose ?? asset?.purpose ?? "").trim().toLowerCase();
  const targetType = String(metadata?.targetType ?? asset?.targetType ?? "").trim().toLowerCase();
  return (
    assetKey.startsWith("upload:") &&
    (targetType === "episode" || purpose.startsWith("episode-attachments/"))
  );
}

function isEpisodeDerivedProjectAsset(asset, localAsset = null) {
  const episodeResult = [
    localAsset?.generationResult,
    asset?.generationResult,
    asset?.latestVersion?.metadata?.generationResult,
  ].find((value) => value && typeof value === "object" && !Array.isArray(value)) ?? null;
  if (!episodeResult) {
    return false;
  }
  return Boolean(
    episodeResult.assetId ||
      episodeResult.promptPreview ||
      episodeResult.selectionContext ||
      episodeResult.storyboardId ||
      episodeResult.episodeId,
  );
}

function normalizeEpisodeAssetDescriptionText(value) {
  const lines = String(value ?? "")
    .replace(/\r/g, "")
    .split("\n")
    .map((line) => line.trim())
    .filter(Boolean);
  const values = [];
  for (const line of lines) {
    if (containsComparableEpisodeAssetText(values, line)) {
      continue;
    }
    for (let index = values.length - 1; index >= 0; index -= 1) {
      if (includesComparableEpisodeAssetText(line, values[index])) {
        values.splice(index, 1);
      }
    }
    values.push(line);
  }
  return values.join("\n");
}

function containsComparableEpisodeAssetText(values, candidate) {
  return values.some((value) => includesComparableEpisodeAssetText(value, candidate));
}

function includesComparableEpisodeAssetText(container, candidate) {
  const normalizedContainer = normalizeComparableEpisodeAssetText(container);
  const normalizedCandidate = normalizeComparableEpisodeAssetText(candidate);
  return Boolean(normalizedCandidate && normalizedContainer.includes(normalizedCandidate));
}

function normalizeComparableEpisodeAssetText(value) {
  return String(value ?? "").replace(/\s+/g, "");
}

function seedImportedEpisodeAssets(workbench, assetKind, importedAssets = []) {
  if (!isRealEpisodeWorkbench(workbench) || assetKind === "other" || !importedAssets.length) {
    return;
  }
  const nextImportedAssets = cloneImportedAssets(workbench.ui.importedAssets);
  const currentAssets = Array.isArray(nextImportedAssets[assetKind]) ? nextImportedAssets[assetKind] : [];
  const existingKeys = new Set(
    currentAssets.flatMap((asset) =>
      [asset?.assetId, asset?.id].map((value) => String(value ?? "").trim()).filter(Boolean),
    ),
  );
  for (const asset of importedAssets) {
    const keys = [asset?.assetId, asset?.id].map((value) => String(value ?? "").trim()).filter(Boolean);
    if (keys.some((key) => existingKeys.has(key))) {
      continue;
    }
    currentAssets.push(asset);
    for (const key of keys) {
      existingKeys.add(key);
    }
  }
  nextImportedAssets[assetKind] = currentAssets;
  workbench.ui.importedAssets = nextImportedAssets;
}

function resolveAssetImportLibraryRecords(workbench, assetKind, options = {}) {
  const source = options.source ?? workbench.ui.assetImportModalSource ?? "project";
  if (source === "official") {
    return getLibraryAssetsForImport({
      assetKind,
      folder: workbench.ui.assetImportCategory ?? "domestic-modern-city",
      searchQuery: "",
    }).map((asset) => ({
      id: asset.id,
      name: asset.name ?? "未命名资产",
      preview: asset.previewUrl ?? asset.preview ?? "",
      previewDataUrl: asset.previewUrl ?? asset.preview ?? "",
      sourceUrl: asset.previewUrl ?? asset.preview ?? "",
      sourceAssetId: asset.id,
      source: "official",
    }));
  }
  if (isRealEpisodeWorkbench(workbench) && assetKind !== "other") {
    const seen = new Set();
    return collectEpisodeAssetCandidates(workbench, assetKind).flatMap((asset) => {
      const id = String(asset.id ?? asset.assetId ?? "").trim();
      if (!id || seen.has(id)) {
        return [];
      }
      seen.add(id);
      return [{
        id,
        name: asset.name ?? asset.label ?? asset.assetKey ?? "未命名资产",
        preview: asset.previewUrl ?? asset.preview ?? asset.fixedImageUrl ?? asset.latestVersion?.previewUrl ?? "",
        previewDataUrl: asset.previewUrl ?? asset.preview ?? asset.fixedImageUrl ?? asset.latestVersion?.previewUrl ?? "",
        mimeType: asset.mimeType ?? asset.latestVersion?.metadata?.mimeType ?? "image/png",
        width: Number(asset.width ?? asset.latestVersion?.metadata?.width ?? 240),
        height: Number(asset.height ?? asset.latestVersion?.metadata?.height ?? 240),
        storageObjectId: asset.storageObjectId ?? asset.latestVersion?.storageObjectId ?? null,
        storageObjectKey: asset.storageObjectKey ?? asset.latestVersion?.storageObjectKey ?? "",
        sourceUrl:
          asset.sourceUrl ??
          asset.previewUrl ??
          asset.preview ??
          asset.fixedImageUrl ??
          asset.latestVersion?.previewUrl ??
          "",
        sourceAssetId: id,
        source: "library",
      }];
    });
  }
  const libraryAssets = assetKind === "character"
    ? workbench.ui.projectLibraryAssetsByType?.character ?? []
    : assetKind === "scene"
      ? workbench.ui.projectLibraryAssetsByType?.scene ?? []
      : assetKind === "prop"
        ? workbench.ui.projectLibraryAssetsByType?.prop ?? []
        : [];
  if (libraryAssets.length) {
    return libraryAssets.map((asset) => ({
      id: asset.id,
      name: asset.label ?? asset.assetKey ?? "未命名资产",
      preview: asset.previewUrl ?? asset.latestVersion?.previewUrl ?? "",
      previewDataUrl: asset.previewUrl ?? asset.latestVersion?.previewUrl ?? "",
      mimeType: asset.latestVersion?.metadata?.mimeType ?? "image/png",
      width: Number(asset.latestVersion?.metadata?.width ?? 240),
      height: Number(asset.latestVersion?.metadata?.height ?? 240),
      storageObjectId: asset.latestVersion?.storageObjectId ?? null,
      storageObjectKey: asset.latestVersion?.storageObjectKey ?? "",
      sourceUrl:
        asset.latestVersion?.metadata?.sourceUrl ??
        asset.latestVersion?.previewUrl ??
        asset.previewUrl ??
        "",
      sourceAssetId: asset.id,
      source: "library",
    }));
  }
  return [];
}

function mapBackendAssets(assets = [], kind) {
  return [...assets].map((asset) => ({
    id: asset.id,
    name: asset.label ?? asset.assetKey ?? "未命名资产",
    preview: asset.previewUrl ?? asset.latestVersion?.previewUrl ?? "",
    description: asset.assetKey ?? "",
    kind,
    source: "backend",
  }));
}

function getDetailEpisodes(state) {
  const detailEpisodes = (state?.projectDetail?.episodes ?? []).map((episode) => ({
    id: episode.id,
    title: episode.title,
    sequence: Number(episode.sequence ?? 0),
    status: episode.status === "ready" ? "已完成" : "草稿",
    createdAt: formatProjectDate(new Date(episode.createdAt ?? Date.now())),
    createdAtMs: Date.parse(episode.createdAt ?? "") || Date.now(),
    storyboardCount: episode.storyboardCount ?? 0,
    previewUrl: episode.previewUrl ?? null,
  }));
  const shots = Array.isArray(state?.projectDetail?.shots)
    ? state.projectDetail.shots
    : (Array.isArray(state?.shots) ? state.shots : []);
  const hasPrimaryEpisode = detailEpisodes.some((episode) => episode.id === "episode-primary");
  const unassignedShots = shots.filter((shot) => !shot?.episodeId);
  if (!hasPrimaryEpisode && unassignedShots.length) {
    const primaryCreatedAtSource = state?.projectDetail?.project?.createdAt ?? state?.project?.createdAt ?? Date.now();
    detailEpisodes.unshift({
      id: "episode-primary",
      sequence: 0,
      title: "未分配剧集",
      status: "草稿",
      createdAt: formatProjectDate(new Date(primaryCreatedAtSource)),
      createdAtMs: Date.parse(String(primaryCreatedAtSource)) || Date.now(),
      storyboardCount: unassignedShots.length,
      previewUrl: null,
    });
  }
  return [...detailEpisodes].sort((left, right) => {
    const timeDelta = (Number(right.createdAtMs) || 0) - (Number(left.createdAtMs) || 0);
    if (timeDelta !== 0) {
      return timeDelta;
    }
    const sequenceDelta = Number(right.sequence ?? 0) - Number(left.sequence ?? 0);
    if (sequenceDelta !== 0) {
      return sequenceDelta;
    }
    return String(right.id ?? "").localeCompare(String(left.id ?? ""), "zh-CN-u-kn-true");
  });
}

function inferMimeTypeFromDataUrl(value) {
  const match = /^data:([^;,]+)/.exec(String(value ?? ""));
  return match?.[1] ?? "image/png";
}

function extensionForMimeType(mimeType) {
  return (
    {
      "image/svg+xml": "svg",
      "image/png": "png",
      "image/jpeg": "jpg",
      "image/webp": "webp",
      "video/mp4": "mp4",
    }[String(mimeType ?? "").toLowerCase()] ?? "bin"
  );
}

function dataUrlToFile(dataUrl, fileName) {
  const value = String(dataUrl ?? "");
  const match = /^data:([^;,]+)?((?:;[^,]+)*),(.*)$/s.exec(value);
  if (!match) {
    throw new Error("invalid_data_url");
  }
  const mimeType = match[1] ?? "application/octet-stream";
  const modifiers = match[2] ?? "";
  const payload = match[3] ?? "";
  const bytes = modifiers.includes(";base64")
    ? Uint8Array.from(atob(payload), (char) => char.charCodeAt(0))
    : new TextEncoder().encode(decodeURIComponent(payload));
  return new File([bytes], fileName, { type: mimeType });
}

async function buildOfficialAssetImportPayload(workbench, record, assetKind) {
  const mimeType = record.mimeType ?? inferMimeTypeFromDataUrl(record.previewDataUrl);
  const fileNameBase =
    String(record.name ?? assetKind ?? "official-asset")
      .trim()
      .toLowerCase()
      .replace(/[^a-z0-9\u4e00-\u9fa5]+/gi, "-")
      .replace(/^-+|-+$/g, "") || "official-asset";
  const file = dataUrlToFile(
    record.previewDataUrl,
    `${fileNameBase}.${extensionForMimeType(mimeType)}`,
  );
  const upload = await uploadLocalFile(workbench, file, "official-assets");
  return {
    name: record.name,
    uploadSessionId: upload.uploadSessionId,
    storageObjectId: upload.storageObjectId,
    mimeType,
    width: record.width ?? 240,
    height: record.height ?? 240,
  };
}

async function syncProjectLibraryFromApi(workbench, options = {}) {
  const requestedPage = Math.max(1, Math.floor(Number(options.page ?? workbench.ui.projectLibraryPage ?? 1)));
  const keyword = String(options.keyword ?? workbench.ui.projectSearchQuery ?? "").trim();
  const pageSize = normalizeProjectLibraryPageSize(options.pageSize ?? workbench.ui.projectLibraryPagination?.pageSize);
  const payload = await workbench.api.getProjects({
    page: requestedPage,
    pageSize,
    keyword,
  });
  const projects = Array.isArray(payload.projects)
    ? payload.projects.map((project) => mapProjectRecordToCard(project))
    : [];
  const pagination = normalizeProjectLibraryPagination(payload.pagination, {
    page: requestedPage,
    pageSize,
    total: projects.length,
  });
  workbench.ui.projectLibrary = projects;
  workbench.ui.projectLibraryPagination = pagination;
  workbench.ui.projectLibraryPage = pagination.page;
  syncSelectedProjectCard(workbench, projects);
  if (options.includeAssets !== false) {
    await syncProjectLibraryAssets(workbench);
  }
}

function normalizeProjectLibraryPagination(value, fallback = {}) {
  const pageSize = normalizeProjectLibraryPageSize(value?.pageSize ?? fallback.pageSize);
  const total = Math.max(0, Number(value?.total ?? fallback.total ?? 0));
  const totalPages = Math.max(1, Number(value?.totalPages ?? Math.ceil(total / pageSize) ?? 1));
  const page = Math.min(totalPages, Math.max(1, Number(value?.page ?? fallback.page ?? 1)));
  return {
    page,
    pageSize,
    total,
    totalPages,
  };
}

function normalizeSingleEpisodeScriptLibraryPagination(value, fallback = {}) {
  const pageSize = Math.max(1, Math.min(100, Math.floor(Number(value?.pageSize ?? fallback.pageSize ?? 10)) || 10));
  const totalValue = Number(value?.total);
  const fallbackTotal = Math.max(0, Number(fallback.total ?? 0));
  const total = Number.isFinite(totalValue) && totalValue > 0 ? totalValue : fallbackTotal;
  const totalPages = Math.max(1, Number(value?.totalPages ?? Math.ceil(total / pageSize) ?? 1));
  const page = Math.min(totalPages, Math.max(1, Number(value?.page ?? fallback.page ?? 1)));
  return {
    page,
    pageSize,
    total,
    totalPages,
  };
}

function normalizeProjectLibraryPageSize(value) {
  return 18;
}

function runLazyWorkbenchTask(workbench, label, task) {
  void Promise.resolve()
    .then(task)
    .catch((error) => {
      console.warn(`[workbench] ${label} failed`, error);
      if (!workbench?.ui) {
        return;
      }
      if (label === "project styles") {
        workbench.ui.projectStyles = [];
      }
      if (label === "storyboard prompt packages") {
        workbench.ui.storyboardPromptPackages = [];
      }
    });
}

async function refreshProjectLibraryIfAvailable(workbench) {
  if (typeof workbench.api?.getProjects !== "function") {
    return;
  }
  await syncProjectLibraryFromApi(workbench);
}

async function syncCanvasProjectsFromApi(workbench) {
  if (typeof workbench.api?.getCanvasProjects !== "function") {
    if (workbench.ui.canvasProjectView === "detail") {
      try {
        await loadProjectCanvasForActiveProject(workbench);
      } catch (error) {
        workbench.ui.toast = `项目画布同步失败：${friendlyError(error)}`;
      }
    }
    syncActiveCanvasDocument(workbench);
    return;
  }
  try {
    const payload = await workbench.api.getCanvasProjects();
    const remoteProjects = Array.isArray(payload?.projects)
      ? payload.projects.map((project, index) => createDefaultCanvasProjectRecord({
        id: project?.id ?? (index === 0 ? DEFAULT_CANVAS_PROJECT_ID : `canvas-project-${index + 1}`),
        projectId: project?.projectId ?? project?.project_id ?? project?.project?.id ?? null,
        title: project?.title ?? project?.name ?? (index === 0 ? "画布项目" : `画布项目 ${index + 1}`),
        createdAt: project?.createdAt ?? "2026/06/11",
        status: project?.status ?? "草稿",
      }))
      : [];
    if (remoteProjects.length) {
      workbench.ui.canvasProjects = remoteProjects;
    } else {
      workbench.ui.canvasProjects = [];
    }
  } catch (error) {
    workbench.ui.toast = `画布项目同步失败：${friendlyError(error)}`;
    workbench.ui.canvasProjects = normalizeCanvasProjects(workbench.ui);
  }
  if (workbench.ui.canvasProjectView === "detail") {
    await loadSelectedStandaloneCanvasDocument(workbench);
  }
  syncActiveCanvasDocument(workbench);
  persistWorkbenchState(workbench);
}

async function loadSelectedStandaloneCanvasDocument(workbench) {
  if (typeof workbench.api?.getStandaloneCanvas !== "function") {
    return false;
  }
  const projects = normalizeCanvasProjects(workbench.ui);
  const selectedProjectId = projects.some((project) => project.id === workbench.ui.selectedCanvasProjectId)
    ? workbench.ui.selectedCanvasProjectId
    : projects[0]?.id ?? "";
  if (!selectedProjectId) {
    return false;
  }
  workbench.ui.selectedCanvasProjectId = selectedProjectId;
  workbench.ui.activeCanvasBusinessProjectId = null;
  workbench.ui.activeCanvasProjectId = selectedProjectId;
  try {
    await loadStandaloneCanvasProject(workbench, selectedProjectId);
    return true;
  } catch (error) {
    workbench.ui.toast = `画布加载失败：${friendlyError(error)}`;
    return false;
  }
}

async function syncScriptLibraryFromApi(workbench, options = {}) {
  if (typeof workbench.api?.getWorkspaceScripts !== "function") {
    return;
  }
  const currentPagination = workbench.ui.singleEpisodeScriptLibraryPagination ?? { page: 1, pageSize: 10 };
  const requestedPage = Math.max(1, Math.floor(Number(options.page ?? currentPagination.page ?? 1)) || 1);
  const requestedPageSize = Math.max(1, Math.floor(Number(options.pageSize ?? currentPagination.pageSize ?? 10)) || 10);
  const payload = await workbench.api.getWorkspaceScripts({
    page: requestedPage,
    pageSize: requestedPageSize,
  });
  if (Array.isArray(payload?.scripts)) {
    workbench.ui.scriptLibraryRecords = payload.scripts;
    workbench.ui.singleEpisodeScriptLibrary = payload.scripts;
  }
  if (payload?.pagination && typeof payload.pagination === "object") {
    workbench.ui.singleEpisodeScriptLibraryPagination = {
      ...normalizeSingleEpisodeScriptLibraryPagination(payload.pagination, {
        page: requestedPage,
        pageSize: requestedPageSize,
        total: payload?.scripts?.length ?? 0,
      }),
      mode: "server",
    };
  } else {
    workbench.ui.singleEpisodeScriptLibraryPagination = {
      ...normalizeSingleEpisodeScriptLibraryPagination({
        page: requestedPage,
        pageSize: requestedPageSize,
        total: Array.isArray(payload?.scripts) ? payload.scripts.length : 0,
      }, currentPagination),
      mode: "server",
    };
  }
}

async function refreshScriptLibraryIfAvailable(workbench) {
  if (typeof workbench.api?.getWorkspaceScripts !== "function") {
    return;
  }
  try {
    await syncScriptLibraryFromApi(workbench);
  } catch (error) {
    console.warn("[script-library] refresh failed", error);
  }
}

async function preloadTeamMemberAssignableResources(workbench) {
  if (typeof workbench.api?.getTeamMemberAssignableResources === "function") {
    await Promise.allSettled(
      ["project", "script", "canvas"].map((resourceType) =>
        loadTeamMemberAssignableResourcePage(workbench, resourceType, 1),
      ),
    );
    return;
  }
  const refreshes = [];
  if (typeof workbench.api?.getProjects === "function") {
    refreshes.push(refreshProjectLibraryIfAvailable(workbench));
  }
  if (typeof workbench.api?.getWorkspaceScripts === "function") {
    refreshes.push(refreshScriptLibraryIfAvailable(workbench));
  }
  if (typeof workbench.api?.getCanvasProjects === "function") {
    refreshes.push(syncCanvasProjectsFromApi(workbench));
  }
  if (!refreshes.length) {
    return;
  }
  await Promise.allSettled(refreshes);
}

async function loadTeamMemberAssignableResourcePage(workbench, resourceType, page = 1) {
  const normalizedType = String(resourceType ?? "").trim();
  if (normalizedType !== "project" && normalizedType !== "script" && normalizedType !== "canvas") {
    return;
  }
  if (typeof workbench.api?.getTeamMemberAssignableResources !== "function") {
    await preloadTeamMemberAssignableResources(workbench);
    return;
  }
  const requestedPage = Math.max(1, Math.floor(Number(page) || 1));
  try {
    const payload = await workbench.api.getTeamMemberAssignableResources({
      type: normalizedType,
      page: requestedPage,
      pageSize: TEAM_MEMBER_RESOURCE_PAGE_SIZE,
    });
    const resources = Array.isArray(payload?.resources) ? payload.resources : [];
    const pagination = payload?.pagination && typeof payload.pagination === "object"
      ? payload.pagination
      : {
          page: requestedPage,
          pageSize: TEAM_MEMBER_RESOURCE_PAGE_SIZE,
          total: resources.length,
          totalPages: 1,
        };
    applyTeamMemberAssignableResourcePage(workbench, normalizedType, resources, pagination);
  } catch (error) {
    workbench.ui.toast = `资源列表加载失败：${friendlyError(error)}`;
  }
}

function applyTeamMemberAssignableResourceSnapshot(target, resourceType, resources, pagination) {
  if (!target) {
    return;
  }
  const normalizedResources = Array.isArray(resources) ? resources : [];
  const normalizedPagination = {
    page: Math.max(1, Number(pagination?.page ?? 1) || 1),
    pageSize: Math.max(1, Number(pagination?.pageSize ?? TEAM_MEMBER_RESOURCE_PAGE_SIZE) || TEAM_MEMBER_RESOURCE_PAGE_SIZE),
    total: Math.max(0, Number(pagination?.total ?? normalizedResources.length) || 0),
    totalPages: Math.max(1, Number(pagination?.totalPages ?? 1) || 1),
  };
  const listKey = resourceType === "project"
    ? "availableProjects"
    : resourceType === "script"
      ? "availableScripts"
      : "availableCanvases";
  target[listKey] = normalizedResources;
  target.resourcePickerPage = normalizedPagination.page;
  target.resourcePagination = {
    ...(target.resourcePagination ?? {}),
    [resourceType]: normalizedPagination,
  };
  target.resourceCounts = {
    ...(target.resourceCounts ?? {}),
    [resourceType]: normalizedPagination.total,
  };
}

function applyTeamMemberAssignableResourcePage(workbench, resourceType, resources, pagination) {
  const listKey = resourceType === "project"
    ? "projectLibrary"
    : resourceType === "script"
      ? "scriptLibraryRecords"
      : "canvasProjects";
  const normalizedResources = Array.isArray(resources) ? resources : [];
  workbench.ui[listKey] = normalizedResources;
  applyTeamMemberAssignableResourceSnapshot(workbench.ui.teamMemberDraft, resourceType, normalizedResources, pagination);
  applyTeamMemberAssignableResourceSnapshot(workbench.ui.editMemberModal, resourceType, normalizedResources, pagination);
  const selectedIds = resourceType === "project"
    ? normalizeSelectedResourceIds(workbench.ui.teamMemberDraft?.projectIds)
    : resourceType === "script"
      ? normalizeSelectedResourceIds(workbench.ui.teamMemberDraft?.scriptIds)
      : normalizeSelectedResourceIds(workbench.ui.teamMemberDraft?.canvasIds);
  selectedIds.forEach((resourceId) => {
    if (normalizedResources.some((resource) => String(resource?.id ?? "") === resourceId)) {
      rememberSelectedTeamMemberResource(workbench, resourceType, resourceId);
    }
  });
}

async function syncAssetLibraryFromApi(workbench, options = {}) {
  const scope = normalizeLibraryAssetScope(workbench);
  if (scope !== (workbench.ui.libraryTeamAssetScope ?? "official")) {
    workbench.ui.libraryTeamAssetScope = scope;
  }
  if (
    scope === "personal" ||
    typeof workbench.api.getLibraryAssets !== "function" ||
    !shouldFetchAssetLibrary(workbench)
  ) {
    workbench.ui.libraryLoading = false;
    workbench.ui.libraryError = "";
    if (scope !== "official") {
      workbench.ui.libraryAssets = [];
    }
    return;
  }

  workbench.ui.libraryLoading = true;
  workbench.ui.libraryError = "";
  const requestInput = {
    scope,
    category: workbench.ui.libraryCategory,
    folder: workbench.ui.libraryFolder,
    query: workbench.ui.libraryQuery,
  };
  const cacheKey = assetLibraryCacheKey(requestInput);
  try {
    const payload = await loadAssetLibraryPayload(workbench, cacheKey, requestInput);
    if (options.requestId && workbench.librarySearchRequestId !== options.requestId) {
      return;
    }
    const folders = Array.isArray(payload.folders) ? payload.folders : [];
    workbench.ui.libraryCategories = Array.isArray(payload.categories) ? payload.categories : [];
    workbench.ui.libraryFolders = folders;
    workbench.ui.libraryAssets = Array.isArray(payload.assets) ? payload.assets : [];
    workbench.ui.libraryEntitlement = payload.entitlement ?? null;
    if (!workbench.ui.libraryFolder && folders[0]) {
      workbench.ui.libraryFolder = folders[0];
    }
  } catch (error) {
    if (options.requestId && workbench.librarySearchRequestId !== options.requestId) {
      return;
    }
    workbench.ui.libraryAssets = [];
    workbench.ui.libraryError = friendlyError(error);
  } finally {
    if (!options.requestId || workbench.librarySearchRequestId === options.requestId) {
      workbench.ui.libraryLoading = false;
    }
  }
}

function assetLibraryCacheKey(input = {}) {
  return [
    input.scope ?? "",
    input.category ?? "",
    input.folder ?? "",
    String(input.query ?? "").trim(),
  ].join("\u001f");
}

async function loadAssetLibraryPayload(workbench, cacheKey, requestInput) {
  const now = Date.now();
  const cached = workbench.assetLibraryCache?.get?.(cacheKey);
  if (cached && now - Number(cached.createdAt ?? 0) < ASSET_LIBRARY_CACHE_TTL_MS) {
    return cached.payload;
  }
  if (!workbench.assetLibraryInFlight) {
    workbench.assetLibraryInFlight = new Map();
  }
  const pending = workbench.assetLibraryInFlight.get(cacheKey);
  if (pending) {
    return pending;
  }
  const request = workbench.api.getLibraryAssets(requestInput)
    .then((payload) => {
      if (!workbench.assetLibraryCache) {
        workbench.assetLibraryCache = new Map();
      }
      workbench.assetLibraryCache.set(cacheKey, {
        createdAt: Date.now(),
        payload,
      });
      return payload;
    })
    .finally(() => {
      workbench.assetLibraryInFlight?.delete?.(cacheKey);
    });
  workbench.assetLibraryInFlight.set(cacheKey, request);
  return request;
}

function shouldFetchAssetLibrary(workbench) {
  const scope = workbench.ui.libraryTeamAssetScope ?? "official";
  return (
    hasActiveSessionUser(workbench.session) &&
    scope !== "personal" &&
    isApiBackedLibraryCategory(workbench.ui.libraryCategory)
  );
}

function shouldPrefetchReusableAssetLibrary(workbench) {
  return (
    workbench.ui.activeNavTab === "library" &&
    (workbench.ui.libraryTeamRoute ?? "assets") === "assets" &&
    shouldFetchAssetLibrary(workbench)
  );
}

function isApiBackedLibraryCategory(category) {
  return ["character", "scene", "prop", "image", "video"].includes(category);
}

function libraryAssetScopeLabel(scope) {
  if (scope === "official") {
    return "官方";
  }
  if (scope === "team") {
    return "团队";
  }
  return "个人";
}

function syncSelectedProjectCard(workbench, projects) {
  const selectedProjectId = workbench.ui.selectedProjectCardId;
  if (selectedProjectId && projects.some((project) => project.id === selectedProjectId)) {
    return;
  }

  const activeProjectId = workbench.state?.project?.id ?? null;
  if (activeProjectId && projects.some((project) => project.id === activeProjectId)) {
    workbench.ui.selectedProjectCardId = activeProjectId;
    return;
  }

  workbench.ui.selectedProjectCardId = projects[0]?.id ?? null;
}

function groupLibraryAssetsByType(assets = []) {
  const grouped = {
    character: [],
    scene: [],
    prop: [],
    other: {
      audio: [],
      image: [],
      video: [],
    },
  };

  for (const asset of Array.isArray(assets) ? assets : []) {
    const normalized = {
      ...asset,
      previewUrl: asset?.previewUrl ?? asset?.latestVersion?.previewUrl ?? "",
    };
    const mimeType = String(asset?.mimeType ?? asset?.latestVersion?.mimeType ?? asset?.latestVersion?.metadata?.mimeType ?? "").trim().toLowerCase();
    if (asset?.assetType === "character_sheet") {
      grouped.character.push(normalized);
    } else if (asset?.assetType === "scene_reference") {
      grouped.scene.push(normalized);
    } else if (asset?.assetType === "prop_reference") {
      grouped.prop.push(normalized);
    } else if (mimeType.startsWith("audio/")) {
      grouped.other.audio.push(normalized);
    } else if (asset?.assetType === "shot_video") {
      grouped.other.video.push(normalized);
    } else {
      grouped.other.image.push(normalized);
    }
  }

  return grouped;
}

function mapProjectRecordToCard(project) {
  const createdAtValue = project.createdAt ? new Date(project.createdAt) : new Date();
  const createdAtTimestamp = Number.isFinite(createdAtValue.getTime())
    ? createdAtValue.getTime()
    : Date.now();

  return {
    id: project.id,
    name: project.name ?? "未命名项目",
    aspectRatio: project.aspectRatio ?? "9:16",
    projectType: inferProjectType(project),
    status: phaseToProjectStatus(project.phase),
    scriptTitle: project.scriptTitle ?? project.script_title ?? project.script?.title ?? "",
    scriptName: project.scriptName ?? project.script_name ?? project.script?.name ?? "",
    scriptFileName: project.scriptFileName ?? project.script_file_name ?? "",
    originalScriptTitle: project.originalScriptTitle ?? project.original_script_title ?? "",
    currentScriptTitle: project.currentScriptTitle ?? project.current_script_title ?? "",
    script: project.script ?? null,
    scripts: Array.isArray(project.scripts) ? project.scripts : [],
    coverImageUrl: project.coverImageUrl ?? "",
    createdAtTimestamp,
    createdAt: formatProjectDate(createdAtValue),
  };
}

function phaseToProjectStatus(phase) {
  if (phase === "export") {
    return "已交付";
  }
  if (phase === "shot_generation" || phase === "asset_review") {
    return "进行中";
  }
  return "草稿";
}

function projectStatusToPhase(status) {
  if (status === "Delivered" || status === "Completed") {
    return "export";
  }
  if (status === "In Progress") {
    return "shot_generation";
  }
  return "script_input";
}

function inferProjectType(project) {
  const name = String(project.name ?? "").toLocaleLowerCase();
  if (name.includes("live") || name.includes("真人")) {
    return "domestic-live";
  }
  return "anime";
}

function formatProjectDate(date) {
  const year = date.getFullYear();
  const month = `${date.getMonth() + 1}`.padStart(2, "0");
  const day = `${date.getDate()}`.padStart(2, "0");
  return `${year}/${month}/${day}`;
}

function readFileAsDataUrl(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(String(reader.result ?? ""));
    reader.onerror = () => reject(reader.error ?? new Error("cover_read_failed"));
    reader.readAsDataURL(file);
  });
}

function setImageReferenceFromStoryboard(workbench, storyboardId, cropMode = "cover") {
  const storyboard = getActiveStoryboards(workbench).find((item) => item.id === storyboardId);
  const image = findStoryboardImage(
    storyboard,
    storyboard?.currentImageAssetVersionId ?? storyboard?.uploadedImages?.[0]?.id ?? "",
  );
  if (!image?.src || !image?.id) {
    return false;
  }
  updateStoryboardGenerationState(workbench, storyboardId, (state) => ({
    ...state,
    imageReference: {
      name: storyboard.uploadedImageName || "storyboard-image",
      kind: "image",
      status: "ready",
      summary: "已引用当前分镜图片",
      url: storyboard.previewImageUrl,
      cropMode,
    },
  }));
  return true;
}

function setEditSourceVideoFromStoryboard(workbench, storyboardId, videoId = "") {
  const storyboard = getActiveStoryboards(workbench).find((item) => item.id === storyboardId);
  const candidate =
    (storyboard?.uploadedVideos ?? []).find((item) => item.id === videoId && item.src) ??
    (storyboard?.uploadedVideos ?? []).find((item) => item.id === storyboard?.selectedUploadedVideoId && item.src) ??
    (storyboard?.uploadedVideos ?? []).find((item) => item.status === "ready" && item.src) ??
    null;
  if (!candidate?.src) {
    return null;
  }
  updateStoryboardGenerationState(workbench, storyboardId, (state) => ({
    ...state,
    editSourceVideo: {
      name: candidate.fileName || "storyboard-video",
      kind: "video",
      status: "ready",
      summary: "已选择当前分镜视频",
      url: candidate.src,
    },
  }));
  return candidate;
}

function openAssetInspector(workbench, payload) {
  workbench.ui.assetInspector = payload;
}

function applyStoryboardImageToolAction(workbench, action, storyboardId) {
  const storyboard = getActiveStoryboards(workbench).find((item) => item.id === storyboardId);
  if (!storyboard?.previewImageUrl) {
    workbench.ui.toast = "当前分镜还没有可用图片。";
    return;
  }

  if (action === "storyboard-image-to-video") {
    workbench.ui.episodeMediaMode = "video";
    workbench.ui.videoGenerationMode = "first-frame";
    workbench.ui.selectedModelId = resolveConfiguredVideoModelCode(workbench, "first-frame", "seedance-i2v-pro");
    syncGenerationStateFromStoryboardImage(workbench, storyboardId);
    workbench.ui.prompt = workbench.ui.prompt || buildSuggestedPrompt(storyboard, { episodeMediaMode: "video" });
    workbench.ui.toast = "";
    return;
  }

  if (action === "storyboard-image-edit") {
    workbench.ui.episodeMediaMode = "image";
    workbench.ui.imageGenerationMode = "single-image";
    workbench.ui.selectedModelId = resolveConfiguredImageModelCode(workbench, "single-image", "gpt-image-2-cn");
    setImageReferenceFromStoryboard(workbench, storyboardId);
    workbench.ui.prompt = workbench.ui.prompt || buildSuggestedPrompt(storyboard, { episodeMediaMode: "image" });
    workbench.ui.toast = "已带入当前分镜图片，进入文字改图模式。";
    return;
  }

  if (action === "storyboard-image-multi-view") {
    workbench.ui.episodeMediaMode = "image";
    workbench.ui.imageGenerationMode = "multi-image";
    workbench.ui.selectedModelId = resolveConfiguredImageModelCode(workbench, "multi-image", "gpt-image-2-cn");
    workbench.ui.imageCount = clampCount(workbench.ui.imageCount ?? 4, 1, 4);
    syncGenerationStateFromStoryboardImage(workbench, storyboardId);
    workbench.ui.toast = "已带入当前分镜图片，进入多视图生成模式。";
    return;
  }

  if (action === "storyboard-image-crop") {
    setImageReferenceFromStoryboard(workbench, storyboardId, "contain");
    updateStoryboardGenerationState(workbench, storyboardId, (state) => ({
      ...state,
      imageReference: state.imageReference
        ? {
            ...state.imageReference,
            cropMode: state.imageReference.cropMode === "contain" ? "cover" : "contain",
          }
        : state.imageReference,
    }));
    workbench.ui.toast = "";
    return;
  }

  openAssetInspector(workbench, {
    type: "image",
    storyboardId,
    title: storyboard.title || "分镜图片",
    name: storyboard.uploadedImageName || "分镜图片",
    url: storyboard.previewImageUrl,
    status: storyboard.imageStatus || "ready",
  });
}

function applyStoryboardVideoToolAction(workbench, action, storyboardId, videoId) {
  const storyboard = getActiveStoryboards(workbench).find((item) => item.id === storyboardId);
  const video = setEditSourceVideoFromStoryboard(workbench, storyboardId, videoId);
  if (!video?.src) {
    workbench.ui.toast = "当前分镜还没有可用视频。";
    return;
  }

  if (action === "storyboard-video-more" || action === "storyboard-video-info") {
    openAssetInspector(workbench, {
      type: "video",
      storyboardId,
      videoId: video.id,
      title: storyboard?.title || "分镜视频",
      name: video.fileName || "分镜视频",
      url: video.src,
      status: video.status || "ready",
      durationLabel: video.durationLabel || "00:10",
    });
    return;
  }

  workbench.ui.episodeMediaMode = "video";
  workbench.ui.videoGenerationMode = "edit-video";
  workbench.ui.selectedModelId = resolveConfiguredVideoModelCode(workbench, "edit-video", "happy-horse");
  if (action === "storyboard-video-upscale") {
    workbench.ui.videoResolution = "2K";
    workbench.ui.toast = "";
    return;
  }
  if (action === "storyboard-video-subtitle-clean") {
    workbench.ui.prompt = `${workbench.ui.prompt || ""} remove subtitles, keep framing and motion stable`.trim();
    workbench.ui.toast = "已填入去字幕处理提示词。";
    return;
  }
  workbench.ui.toast = "";
}

async function deleteStoryboardImage(workbench, storyboardId, imageId = "") {
  const storyboard = getActiveStoryboards(workbench).find((item) => item.id === storyboardId);
  const image = findStoryboardImage(storyboard, imageId);
  if (!storyboardId || !image) {
    workbench.ui.toast = "当前分镜没有可删除的图片。";
    render(workbench);
    return;
  }

  const resolvedAssetVersionId = resolveStoryboardImageAssetVersionId(workbench, storyboard, image, imageId);
  const removedUrl = image.src;
  const applyLocalRemoval = () => {
    updateStoryboardById(workbench, storyboardId, (currentStoryboard) => {
      const remainingImages = (currentStoryboard.uploadedImages ?? []).filter((item) => {
        if (item.id === image.id) {
          return false;
        }
        if (resolvedAssetVersionId && item.id === resolvedAssetVersionId) {
          return false;
        }
        if (resolvedAssetVersionId && item.deleteAssetId === resolvedAssetVersionId) {
          return false;
        }
        return true;
      });
      const nextSelectedImage =
        remainingImages.find((item) => item.id === currentStoryboard.currentImageAssetVersionId) ??
        remainingImages[0] ??
        null;
      const removedSelected =
        currentStoryboard.currentImageAssetVersionId === image.id ||
        (resolvedAssetVersionId &&
          currentStoryboard.currentImageAssetVersionId === resolvedAssetVersionId);
      return {
        ...currentStoryboard,
        uploadedImages: remainingImages,
        imageStatus: remainingImages.length ? "ready" : "empty",
        previewImageUrl:
          removedSelected ? (nextSelectedImage?.src ?? null) : currentStoryboard.previewImageUrl ?? null,
        previewUrl:
          removedSelected
            ? (nextSelectedImage?.src ?? null)
            : currentStoryboard.previewUrl ?? currentStoryboard.previewImageUrl ?? null,
        uploadedImageName:
          removedSelected ? (nextSelectedImage?.fileName ?? "") : currentStoryboard.uploadedImageName,
        currentImageAssetVersionId:
          removedSelected ? (nextSelectedImage?.id ?? null) : currentStoryboard.currentImageAssetVersionId,
      };
    });
    updateStoryboardGenerationState(workbench, storyboardId, (state) => ({
      ...state,
      firstFrame: state.firstFrame?.url === removedUrl ? null : state.firstFrame,
      lastFrame: state.lastFrame?.url === removedUrl ? null : state.lastFrame,
      imageReference: state.imageReference?.url === removedUrl ? null : state.imageReference,
    }));
    clearStoryboardImageFromState(
      workbench,
      storyboard?.linkedShotId ?? null,
      resolvedAssetVersionId ?? image.id,
      (storyboard?.uploadedImages ?? []).find((item) =>
        item.id !== image.id &&
        (!resolvedAssetVersionId || (item.id !== resolvedAssetVersionId && item.deleteAssetId !== resolvedAssetVersionId))
      ) ?? null,
    );
  };

  if (storyboard.linkedShotId) {
    workbench.ui.busy = true;
    workbench.ui.toast = "正在删除分镜图片...";
    render(workbench);
    try {
      const result = await deleteEpisodeFileResourceIfAvailable(workbench, {
        ...image,
        assetVersionId: resolvedAssetVersionId ?? image.assetVersionId ?? image.id,
      }) ?? await workbench.api.deleteShotMedia(storyboard.linkedShotId, {
        kind: "image",
        assetVersionId: resolvedAssetVersionId,
      });
      applyLocalRemoval();
      if (result?.missing) {
        workbench.ui.toast = "图片已从当前视图移除，后端媒体记录未找到。";
        return;
      }
      workbench.ui.toast = "已删除当前分镜图片。";
    } catch (error) {
      workbench.ui.toast = `删除失败：${friendlyError(error)}`;
    } finally {
      workbench.ui.busy = false;
      render(workbench);
    }
    return;
  }

  applyLocalRemoval();
  workbench.ui.toast = "已移除当前分镜图片。";
  render(workbench);
}

async function deleteStoryboardVideo(workbench, storyboardId, videoId) {
  if (!storyboardId || !videoId) {
    return;
  }

  const storyboard = getActiveStoryboards(workbench).find((item) => item.id === storyboardId);
  if (storyboard?.currentVideoAssetVersionId === videoId) {
    workbench.ui.toast = "当前定格视频不能删除，请先取消定格。";
    render(workbench);
    return;
  }
  const video = (storyboard?.uploadedVideos ?? []).find((item) => item.id === videoId);
  if (!video) {
    workbench.ui.toast = "当前分镜没有可删除的视频。";
    render(workbench);
    return;
  }

  const applyLocalRemoval = () => {
    cancelStoryboardVideoUpload(workbench, storyboardId, videoId);
    updateStoryboardById(workbench, storyboardId, (currentStoryboard) => {
      const remainingVideos = (currentStoryboard.uploadedVideos ?? []).filter((item) => item.id !== videoId);
      const nextSelectedVideo =
        remainingVideos.find((item) => item.id === currentStoryboard.selectedUploadedVideoId && item.status === "ready") ??
        remainingVideos.find((item) => item.status === "ready") ??
        null;
      const nextStoryboard = {
        ...currentStoryboard,
        uploadedVideos: remainingVideos,
        selectedUploadedVideoId: nextSelectedVideo?.id ?? null,
        videoStatus: nextSelectedVideo ? "ready" : "empty",
        previewVideo: nextSelectedVideo?.src ?? null,
        previewThumbnailUrl: nextSelectedVideo?.thumbnailSrc ?? null,
        currentVideoAssetVersionId:
          currentStoryboard.currentVideoAssetVersionId === videoId
            ? nextSelectedVideo?.id ?? null
            : currentStoryboard.currentVideoAssetVersionId,
      };
      return {
        ...nextStoryboard,
        previewUrl: resolveStoryboardCombinedPreviewUrl(nextStoryboard),
      };
    });
    clearStoryboardVideoFromState(workbench, storyboard?.linkedShotId ?? null, videoId);
  };

  if (storyboard.linkedShotId) {
    await runAction(workbench, "正在删除分镜视频...", async () => {
      try {
        await deleteEpisodeFileResourceIfAvailable(workbench, {
          ...video,
          assetVersionId: video.assetVersionId ?? videoId,
        }) ?? await workbench.api.deleteShotMedia(storyboard.linkedShotId, {
          kind: "video",
          assetVersionId: videoId,
        });
      } catch (error) {
        const errorMessage = String(error instanceof Error ? error.message : error);
        if (!errorMessage.includes("shot_media_not_found")) {
          throw error;
        }
      }
      applyLocalRemoval();
    });
    return;
  }

  applyLocalRemoval();
  persistWorkbenchState(workbench);
  workbench.ui.toast = `已移除 ${video.fileName || "分镜视频"}。`;
  render(workbench);
}

export function mapEpisodeAssetContractsForTest(assets = [], kind = "character") {
  return mapEpisodeAssetContracts(assets, kind);
}
